with.script:
const { owner, repo } = context.repo;
const title  = process.env.ISSUE_TITLE;
const label  = process.env.ISSUE_LABEL;
const body   = [
  process.env.ISSUE_BODY,
  '',
  '---',
  `_Auto-managed by \`admin-action-notifier.yml\` · Gap: \`${process.env.GAP_ID}\` · Probe: HTTP \`${process.env.HTTP_STATUS}\` — ${process.env.RESPONSE_MSG}_`,
  `_Last checked: ${new Date().toISOString()}_`,
].join('\n');

// Ensure label exists
try {
  await github.rest.issues.createLabel({
    owner, repo,
    name: label,
    color: 'e11d48',
    description: 'Requires manual admin action to unblock CI automation',
  });
} catch (_) { /* label already exists — ignore */ }

// Find existing open issue for this gap
let existing = null;
const open = await github.rest.issues.listForRepo({
  owner, repo, state: 'open', labels: label, per_page: 50,
});
existing = open.data.find(i => i.title === title);

let issueNum;
if (existing) {
  await github.rest.issues.update({ owner, repo, issue_number: existing.number, body });
  issueNum = existing.number;
  core.info(`↩️  Updated existing issue #${issueNum} for ${process.env.GAP_ID}`);
} else {
  const created = await github.rest.issues.create({
    owner, repo, title, body,
    labels:    [label],
    assignees: [process.env.ASSIGNEE],
  });
  issueNum = created.data.number;
  core.info(`✅ Created issue #${issueNum}: ${created.data.html_url}`);
  core.notice(`Admin action required (${process.env.GAP_ID}) — see issue #${issueNum}`);
}
core.setOutput('issue_number', String(issueNum));

const { owner, repo } = context.repo;
const open = await github.rest.issues.listForRepo({
  owner, repo, state: 'open', labels: process.env.ISSUE_LABEL, per_page: 50,
});
const existing = open.data.find(i => i.title === process.env.ISSUE_TITLE);
if (existing) {
  await github.rest.issues.createComment({
    owner, repo, issue_number: existing.number,
    body: [
      `## ✅ ${process.env.GAP_ID} Gap Closed`,
      '',
      `Probe returned expected HTTP status — the admin action has been completed.`,
      '',
      `_Auto-resolved by \`admin-action-notifier.yml\` at ${new Date().toISOString()}_`,
    ].join('\n'),
  });
  await github.rest.issues.update({
    owner, repo, issue_number: existing.number,
    state: 'closed', state_reason: 'completed',
  });
  core.info(`✅ Auto-closed issue #${existing.number} for ${process.env.GAP_ID}`);
} else {
  core.info(`ℹ️  No open ${process.env.GAP_ID} issue found — nothing to close`);
}

// Update COGNITIVE_BRAIN_SESSION_NUMBER to 109
await github.request('PATCH /repos/{owner}/{repo}/actions/variables/{name}', {
  owner: context.repo.owner,
  repo: context.repo.repo,
  name: 'COGNITIVE_BRAIN_SESSION_NUMBER',
  value: '109',
});

// Ensure all three delegated agent identities are in COGNITIVE_BRAIN_ALLOWED_ACTORS:
//   1. copilot-swe-agent[bot]  — GitHub Copilot coding agent
//   2. github-copilot[bot]     — GitHub Copilot app / custom agents
//   3. github-actions[bot]     — standard CI/AI workflow automation
const REQUIRED_AGENTS = [
  'copilot-swe-agent[bot]',
  'github-copilot[bot]',
  'github-actions[bot]',
];

// Fetch the current value first to avoid overwriting other actors
// Default: mbaetiong (human admin) + github-actions[bot] (CI automation)
let currentActors = 'mbaetiong,github-actions[bot]';
try {
  const resp = await github.request('GET /repos/{owner}/{repo}/actions/variables/{name}', {
    owner: context.repo.owner,
    repo: context.repo.repo,
    name: 'COGNITIVE_BRAIN_ALLOWED_ACTORS',
  });
  currentActors = resp.data.value || currentActors;
} catch (e) {
  core.warning(`Could not fetch current COGNITIVE_BRAIN_ALLOWED_ACTORS: ${e.message}. Using default.`);
}

// Use array-based exact matching to avoid partial-name false positives
const actorSet = new Set(
  currentActors.split(',').map(a => a.trim()).filter(a => a.length > 0)
);
for (const agent of REQUIRED_AGENTS) {
  actorSet.add(agent);
}
const updatedActors = Array.from(actorSet).join(',');
await github.request('PATCH /repos/{owner}/{repo}/actions/variables/{name}', {
  owner: context.repo.owner,
  repo: context.repo.repo,
  name: 'COGNITIVE_BRAIN_ALLOWED_ACTORS',
  value: updatedActors,
});
core.info(`✅ Session number updated to 109. COGNITIVE_BRAIN_ALLOWED_ACTORS: ${updatedActors}`);

run_commands.command:
python scripts/ci/approve_pending_runs.py || {
  echo "::warning::approve_pending_runs.py failed; continuing to avoid blocking delegation workflow."
  exit 0
}

with.script:
// Branches that are staging gates — never the HEAD of an agent session.
const INTEGRATION_BRANCHES = ['0D_base_'];
const PROMOTION_TARGETS = ['main', 'master'];
const pr = context.payload.pull_request;
if (!pr) return;

const head = pr.head.ref;
const base = pr.base.ref;

if (!INTEGRATION_BRANCHES.includes(head)) {
  core.info(`REQ-11 PASS: head='${head}' is not an integration branch.`);
  return;
}

// Exception: this is a promotion PR (integration_branch → main/master).
// Promotion merges are the intended flow; REQ-11 only blocks direct
// coding sessions, not the staging-gate → main promotion PR.
if (PROMOTION_TARGETS.includes(base)) {
  core.info(`REQ-11 PASS: '${head}' → '${base}' is a promotion PR. Promotion merges are allowed.`);
  return;
}

// HEAD is an integration branch opened against a non-promotion target
// — build redirect comment.
const runUrl = `${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID}`;
const ts = new Date().toISOString();
const MARKER = '<!-- req11-integration-branch-guard -->';
const body = [
  MARKER,
  `## 🚫 REQ-11: Direct Session on Integration Branch Blocked`,
  ``,
  `**Branch \`${head}\` is a staging integration branch** — Copilot Coding Agent sessions`,
  `must never run directly on it.`,
  ``,
  `### Why`,
  `\`${head}\` is the **staging gate** that accumulates reviewed sub-PR work before`,
  `promotion to \`main\`.  Running a session directly on \`${head}\` bypasses the`,
  `sub-PR review cycle and risks polluting the staging branch with unreviewed changes.`,
  ``,
  `### Architecture`,
  `\`\`\``,
  `copilot/session-*  ──►  ${head}  ──►  main`,
  `(your work here)        (staging gate)   (promotion PR)`,
  `\`\`\``,
  ``,
  `### ✅ How to Start a New Agent Session`,
  ``,
  `**Option A — Automated (recommended):** Trigger the session-chain workflow:`,
  `\`\`\`bash`,
  `gh workflow run copilot-session-chain.yml \\`,
  `  -f source_branch=${head} \\`,
  `  -f session_title="Describe your task here" \\`,
  `  -f auto_start=true`,
  `\`\`\``,
  `This automatically creates a new \`copilot/session-*\` branch, opens a sub-PR`,
  `targeting \`${head}\`, and posts the \`@copilot\` trigger comment.`,
  ``,
  `**Option B — Manual:**`,
  `1. Create a new branch from \`${head}\`:`,
  `   \`\`\`bash`,
  `   git fetch origin ${head}`,
  `   git checkout -b copilot/session-$(date +%Y%m%d-%H%M%S) origin/${head}`,
  `   git push origin HEAD`,
  `   \`\`\``,
  `2. Open a PR targeting \`${head}\` (NOT \`main\`).`,
  `3. Post \`@copilot+claude-haiku-4.5 /plan\` on the new PR.`,
  ``,
  `**Copy-paste Copilot prompt for a new session:**`,
  `\`\`\``,
  `@copilot+claude-haiku-4.5 /plan`,
  ``,
  `Open a new sub-PR targeting \`${head}\` for this agent session.`,
  `Architecture: sub-PR → ${head} → main.`,
  `Do NOT commit directly to \`${head}\`.`,
  `Delegate independent subtasks to Custom Agents (e.g. ci-auto-healer-agent, unified-coverage-agent) using the task tool to work in parallel.`,
  `\`\`\``,
  ``,
  `---`,
  `_Auto-posted by \`cognitive-preflight\` REQ-11 gate at ${ts}_`,
  `_[View run](${runUrl}) · [INTEGRATION_BRANCH_MODEL.md](.codex/docs/INTEGRATION_BRANCH_MODEL.md)_`,
].join('\n');

// Upsert: replace any previous REQ-11 guard comment.
const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo:  context.repo.repo,
  issue_number: pr.number,
  per_page: 100,
});
const existing = comments.find(c => (c.body || '').includes(MARKER));
if (existing) {
  await github.rest.issues.updateComment({
    owner:      context.repo.owner,
    repo:       context.repo.repo,
    comment_id: existing.id,
    body,
  });
} else {
  await github.rest.issues.createComment({
    owner:        context.repo.owner,
    repo:         context.repo.repo,
    issue_number: pr.number,
    body,
  });
}

await core.summary
  .addHeading('REQ-11: Integration-Branch Guard', 3)
  .addRaw(
    `\n🚫 FAIL — \`${head}\` is an integration/staging branch.\n` +
    `Copilot sessions must use a sub-PR.  See comment on PR #${pr.number} for instructions.\n`
  )
  .write();

core.setFailed(
  `REQ-11 FAIL: Branch '${head}' is the staging integration branch. ` +
  `Copilot sessions must NOT run directly on '${head}'. ` +
  `Create a sub-PR branch targeting '${head}' instead. ` +
  `See the REQ-11 comment on this PR for step-by-step instructions, ` +
  `or run: gh workflow run copilot-session-chain.yml -f source_branch=${head}`
);

const fs = require('fs');
const sha = (context.sha || 'unknown').slice(0, 7);
const MARKER = 'COGNITIVE PRE-FLIGHT CHECKLIST';

// Upsert: find existing comment by stable anchor marker
const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.issue.number,
  per_page: 100,
});

// Scan for existing priority directive to surface inline
const directive = comments.find(c =>
  c.body.includes('Priority for this session:')
);
const priorityLine = directive
  ? (() => {
      const m = directive.body.match(/Priority for this session:\s*(.+)/);
      return m
        ? `\n> ⚡ **ACTIVE SESSION PRIORITY:** ${m[1].trim()} _(set by @${directive.user.login})_\n`
        : '';
    })()
  : '\n> ℹ️ No session priority directive found. Post a comment with `Priority for this session: X` to set one.\n';

const UPSERT_MARKER = '<!-- cognitive-preflight-checklist -->';

// Inject pending session requirements (from comment-review-gate) at top of checklist.
// Read actual file content — the session_reqs step downloads to a known path.
const sessionReqsHasReq = '${{ steps.session_reqs.outputs.has_requirements }}' === 'true';
let sessionReqsContent = '';
if (sessionReqsHasReq) {
  try {
    sessionReqsContent = fs.readFileSync(
      '/tmp/session-req-download/session_requirements.md', 'utf8'
    ).trim();
  } catch (e) {
    core.warning(`Could not read session requirements file: ${e.message}`);
  }
}
const pendingRequirementsBlock = sessionReqsHasReq && sessionReqsContent
  ? [
      '',
      '---',
      '',
      '### 📋 Pending Comment Requirements (Pre-pended from Comment Review Gate)',
      '',
      '> **These comments were unaddressed on the previous scan and are injected here**',
      '> **as session requirements. Address each one BEFORE making file changes.**',
      '',
      sessionReqsContent,
      '',
      '---',
      '',
    ].join('\n')
  : '';

const body = [
  UPSERT_MARKER,
  `## 🧠 ${MARKER} — SHA: ${sha}`,
  '',
  '> **Auto-posted by `cognitive-preflight` job BEFORE session activation.**',
  '> Treat this as active instruction — NOT background memory. This is a CI gate.',
  priorityLine,
  pendingRequirementsBlock,
  '---',
  '',
  '### ✅ Agent Pre-flight Checklist',
  '',
  '> **⚠️ MANDATORY: Complete items 0a and 0b BEFORE any file changes.**',
  '',
  '- [ ] **0a. 🤖 Review ALL bot-posted comments** — fetch and address every open thread from `copilot-pull-request-reviewer[bot]`, `github-advanced-security[bot]`, `github-code-quality[bot]`, `github-actions[bot]` on this PR _(per §0 of CODEBASE_AGENCY_POLICY.md)_',
  '- [ ] **0b. ❌ Fix ALL failing CI checks** — review every failing/warning check in the latest workflow runs; fix all code-fixable failures before pushing new commits _(per §0 of CODEBASE_AGENCY_POLICY.md)_',
  '- [ ] **0c. 🔀 REQ-10: Check branch rebase status** — if a `BRANCH_REBASE_REQUIRED` comment is present on this PR, rebase BEFORE any other work: `git fetch origin && git rebase origin/<base> && git push --force-with-lease` _(CI hard block if unresolved)_',
  '- [ ] **1.** Update `docs/accountability/.codex/archive/reports/AGENT_ACCOUNTABILITY_REPORT.md` in your commit _(CI will fail if not touched)_',
  '- [ ] **2.** Review CI failure patterns in the Actions job summary (Actions tab → this run → Job Summary)',
  '- [ ] **3.** Confirm `.gitignore` allows `.codex/agent_auth_session.json` _(CI will fail if blocked)_',
  '- [ ] **4.** Read the `Priority for this session: X` comment on this PR — that is your **PRIMARY directive**',
  '- [ ] **5.** Post your Phase execution plan as a PR comment BEFORE making any file changes',
  '- [ ] **6.** Follow `.codex/CODEBASE_AGENCY_POLICY.md` at all times — violations must be self-corrected',
  '- [ ] **7. REQ-13 (HARD STOP):** Address ALL comments from `@mbaetiong` and ALL bot-posted comments (copilot-pull-request-reviewer, github-actions, github-advanced-security, github-code-quality) **before** committing any new changes. CI gate `comment-review-gate.yml` enforces this.',
  '',
  '### ⚙️ Policy Quick Reference',
  '',
  '| Rule | Requirement |',
  '|------|-------------|',
  '| **Pre-session** | Review ALL bot comments + fix ALL failing CI checks FIRST |',
  '| **REQ-13** | Reply to ALL `mbaetiong` + critical-bot comments before new commits (enforced by `comment-review-gate.yml`) |',
  '| Execution trigger | Within 60 seconds of reading a clear task |',
  '| Self-review | Minimum 5 passes before session close |',
  '| Deferral | NEVER without: documented blocker + 5 attempts + follow-up `@copilot` comment |',
  '| Terminology | pre-commit/commit cycles — NOT days/weeks |',
  '| Follow-up | Post `@copilot ...` PR comment if session ends with incomplete work |',
  '| **PR requirement** | Sessions no longer create PRs by default (GitHub change 2026-03). **Always work on a pre-existing PR branch.** If none exists, run `gh pr create --base 0D_base_` before starting work. Include "open a pull request" in any `@copilot` prompt posted on an issue. |',
  '',
  '### 🔗 Policy References',
  '',
  '| File | Purpose |',
  '|------|---------|',
  '| `.codex/CODEBASE_AGENCY_POLICY.md` | Master policy (§0 pre-session review) |',
  '| `.codex/patterns/ci_failure_patterns.yaml` | CI pattern library (25 patterns) |',
  '| `docs/accountability/.codex/archive/reports/AGENT_ACCOUNTABILITY_REPORT.md` | Session accountability |',
  '',
  '---',
  `_Auto-posted: ${new Date().toISOString()} | cognitive-preflight gate | WF-001_`,
  `_Last updated for SHA: \`${sha}\` | ${new Date().toISOString()}_`,
  '',
  '---',
  `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
].join('\n');

// Paginated upsert: search ALL pages so PRs with >100 comments are handled.
let existing = null;
let page = 1;
while (!existing && page <= 20) {
  const { data: batch } = await github.rest.issues.listComments({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    per_page: 100,
    page,
  });
  existing = batch.find(c => c.body && c.body.includes(UPSERT_MARKER));
  if (existing || batch.length < 100) break;
  page++;
}
if (existing) {
  await github.rest.issues.updateComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    comment_id: existing.id,
    body,
  });
  console.log(`✅ Checklist updated in-place for SHA ${sha}`);
} else {
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    body,
  });
  console.log(`✅ Checklist posted for SHA ${sha}`);
}

const sha    = (context.sha || 'unknown').slice(0, 7);
const MARKER = 'COGNITIVE SESSION-TYPE DIRECTIVE';

const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.issue.number,
  per_page: 100,
});

// Detect session signals from session-watchdog.yml markers
const hasExploration   = comments.some(c => c.body.includes('SESSION_TYPE_EXPLORATION'));
const doNotAutoProceed = comments.some(c => /do\s+not\s+auto.?proceed/i.test(c.body));

// Detect active (non-expired) timebox
let activeTimebox = null;
const now = new Date();
for (const c of comments.filter(c => c.body.includes('SESSION_TIMEBOX_START'))) {
  const m = c.body.match(/\*\*Expires:\*\*\s*(\S+)/);
  if (m) {
    const exp = new Date(m[1]);
    if (!isNaN(exp.getTime()) && now < exp) {
      const minsLeft = Math.round((exp - now) / 60000);
      activeTimebox = { expiresISO: m[1], minsLeft };
    }
  }
}

// Only post if there is something to surface
if (!hasExploration && !activeTimebox && !doNotAutoProceed) {
  console.log('No session-type directives detected — skipping injection.');
  return;
}

const UPSERT_MARKER_WF002 = '<!-- cognitive-preflight-session-directives -->';
const lines = [
  UPSERT_MARKER_WF002,
  `## 🎯 ${MARKER} — SHA: ${sha}`,
  '',
  '> **Auto-posted by `cognitive-preflight` — session-type specific enforcement rules.**',
  '> These items are IN ADDITION to the standard Pre-flight Checklist above.',
  '',
];

if (activeTimebox) {
  lines.push(`> ⏱ **ACTIVE TIMEBOX: ~${activeTimebox.minsLeft} minutes remaining** (expires \`${activeTimebox.expiresISO}\`)`);
  lines.push('> Complete your work and post `## 🧠 Session Summary` BEFORE this expires.');
  lines.push('');
}

if (hasExploration) {
  lines.push('### 🔍 Exploration Session Active — [Session Continuity Policy](.github/docs/SessionContinuityPolicy.md) applies:');
  lines.push('');
  lines.push('- [ ] **A.** After each agenda item: post PR comment with findings; ask "proceed or go deeper?"');
  lines.push('- [ ] **B.** Every ~10 minutes: post an incremental progress summary as a PR comment');
  lines.push('- [ ] **C.** Treat silence from human as PAUSE — do NOT auto-proceed to next item');
  lines.push('- [ ] **D.** On session close: post `## 🧠 Session Summary` with topics, key findings, and a follow-up `@copilot` prompt');
  lines.push('');
}

if (doNotAutoProceed) {
  lines.push('### 🛑 "Do NOT Auto-Proceed" Directive Active:');
  lines.push('');
  lines.push('- [ ] After each agenda item: **STOP.** Post findings. Wait for explicit human "continue" reply.');
  lines.push('- [ ] Do NOT start the next item without an explicit human response.');
  lines.push('');
}

lines.push('_auto-posted by cognitive-preflight | WF-002 | [SessionContinuityPolicy.md](.github/docs/SessionContinuityPolicy.md)_');
lines.push('');
lines.push('---');
lines.push(`_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`);

// Upsert: update existing or create new
const directiveBody = lines.join('\n');
const existingDirective = comments.find(c => c.body && c.body.includes(UPSERT_MARKER_WF002));
if (existingDirective) {
  await github.rest.issues.updateComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    comment_id: existingDirective.id,
    body: directiveBody,
  });
} else {
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    body: directiveBody,
  });
}
console.log('Session-type directives surfaced in preflight comment.');

const EXPIRED_MARKER  = 'SESSION_TIMEBOX_EXPIRED';
const SUMMARY_MARKER  = '## 🧠 Session Summary';

const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo:  context.repo.repo,
  issue_number: context.issue.number,
  per_page: 100,
});

// Find most recent SESSION_TIMEBOX_EXPIRED comment
const expiredComment = comments
  .filter(c => c.body.includes(EXPIRED_MARKER))
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))[0];

if (!expiredComment) {
  core.summary.addRaw('### ⏱ Timebox Acknowledgment Check\n\n✅ **PASS** — No `SESSION_TIMEBOX_EXPIRED` found. No acknowledgment required.\n\n');
  await core.summary.write();
  return;
}

const expiredAt = new Date(expiredComment.created_at);

// Check for Session Summary comment posted AFTER the expiry notice
const summaryAfterExpiry = comments.find(c =>
  c.body.includes(SUMMARY_MARKER) &&
  new Date(c.created_at) > expiredAt
);

if (summaryAfterExpiry) {
  const poster = summaryAfterExpiry.user.login;
  const postedAt = summaryAfterExpiry.created_at;
  core.summary.addRaw(
    `### ⏱ Timebox Acknowledgment Check\n\n` +
    `✅ **PASS** — Session Summary posted by @${poster} at ${postedAt}, after timebox expiry.\n\n`
  );
  await core.summary.write();
} else {
  core.summary.addRaw(
    `### ⏱ Timebox Acknowledgment Check\n\n` +
    `❌ **FAIL** — \`SESSION_TIMEBOX_EXPIRED\` was posted at ${expiredComment.created_at} ` +
    `but no \`## 🧠 Session Summary\` comment has been posted since then.\n\n` +
    `**Fix:** Post a PR comment containing \`## 🧠 Session Summary\` covering:\n` +
    `- Topics covered and key findings\n` +
    `- Suggested follow-up \`@copilot\` prompt for the next session\n\n` +
    `_Session activation is blocked until the Session Summary is posted._\n`
  );
  await core.summary.write();
  core.setFailed('SESSION_TIMEBOX_EXPIRED requires a "## 🧠 Session Summary" comment before reactivation.');
}

const REQUIRED_MARKER = 'BRANCH_REBASE_REQUIRED';
const RESOLVED_MARKER = 'BRANCH_REBASE_RESOLVED';
const prNumber = context.issue.number;

core.info(`REQ-10: Checking rebase status for PR #${prNumber}`);

// Helper: check whether all commits in an array are automated
// [skip ci] github-actions[bot] commits.  When true the gap
// contains only metadata updates and is safe to auto-pass.
const BOT_LOGINS = new Set([
  'github-actions[bot]',
  '41898282+github-actions[bot]',
]);
function gapIsAllBotSkipCi(commits) {
  if (!commits || commits.length === 0) return false;
  return commits.every(c => {
    const login = (c.author  && c.author.login)          || '';
    const msg   = (c.commit  && c.commit.message)        || '';
    return BOT_LOGINS.has(login) && msg.toLowerCase().includes('[skip ci]');
  });
}

// Helper: fetch commits that `base` has but `head` is missing
// (the "gap" — what the PR branch needs to absorb).
async function fetchGapCommits(base, head) {
  try {
    const { data: rev } = await github.rest.repos.compareCommitsWithBasehead({
      owner: context.repo.owner,
      repo:  context.repo.repo,
      basehead: `${head}...${base}`,   // reversed: commits in base ∖ head
    });
    return rev.commits || [];
  } catch (e) {
    core.warning(`REQ-10: could not fetch gap commits: ${e.message}`);
    return [];
  }
}

// Fetch all PR comments
const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo:  context.repo.repo,
  issue_number: prNumber,
  per_page: 100,
});

// Find the latest REQUIRED and RESOLVED markers
const required = comments.filter(c => (c.body || '').includes(REQUIRED_MARKER));
const resolved = comments.filter(c => (c.body || '').includes(RESOLVED_MARKER));

if (required.length === 0) {
  // No rebase-required marker → check live compare API as fallback
  const pr = context.payload.pull_request;
  if (pr) {
    const base = pr.base.ref;
    const head = pr.head.ref;
    try {
      const { data: cmp } = await github.rest.repos.compareCommitsWithBasehead({
        owner: context.repo.owner,
        repo:  context.repo.repo,
        basehead: `${base}...${head}`,
      });
      const status   = cmp.status;
      const behindBy = cmp.behind_by || 0;
      core.info(`Compare ${base}...${head}: status=${status}, behind_by=${behindBy}`);

      await core.summary
        .addHeading('REQ-10: Branch Rebase Check', 3)
        .addRaw(`\n\`${head}\` vs \`${base}\`: **${status}** (behind=${behindBy})\n`)
        .write();

      if (status === 'behind' || status === 'diverged') {
        // Auto-pass when the entire gap is [skip ci] bot commits.
        const gap       = await fetchGapCommits(base, head);
        const allBotGap = gapIsAllBotSkipCi(gap);
        if (allBotGap) {
          core.info(
            `REQ-10 PASS: branch is ${status} but all ${gap.length} gap ` +
            `commit(s) are [skip ci] bot metadata commits — no rebase needed.`
          );
        } else {
          core.setFailed(
            `REQ-10 FAIL: Branch '${head}' is ${behindBy} commit(s) BEHIND '${base}'. ` +
            `Rebase before starting agent work:\n  git fetch origin ${base}\n  git rebase origin/${base}\n  git push --force-with-lease`
          );
        }
      } else {
        core.info(`REQ-10 PASS: branch is ${status} (no rebase needed)`);
      }
    } catch (err) {
      core.warning(`REQ-10: Could not compare branches: ${err.message} — soft warning`);
    }
  }
  return;
}

// There is a REQUIRED marker — check if a RESOLVED marker follows it
const latestRequired = required.sort(
  (a, b) => new Date(b.updated_at) - new Date(a.updated_at)
)[0];
const latestResolved = resolved.length > 0
  ? resolved.sort((a, b) => new Date(b.updated_at) - new Date(a.updated_at))[0]
  : null;

const requiredTs = new Date(latestRequired.updated_at);
const resolvedTs = latestResolved ? new Date(latestResolved.updated_at) : null;

const markerResolved = resolvedTs && resolvedTs > requiredTs;

// Even if no RESOLVED marker, check the live branch comparison API.
// The branch may have been rebased since the REQUIRED marker was posted,
// in which case the live check should confirm it is up-to-date.
let liveResolved = false;
const pr = context.payload.pull_request;
if (!markerResolved && pr) {
  try {
    const { data: cmp } = await github.rest.repos.compareCommitsWithBasehead({
      owner: context.repo.owner,
      repo:  context.repo.repo,
      basehead: `${pr.base.ref}...${pr.head.ref}`,
    });
    const liveStatus = cmp.status;
    const behindBy   = cmp.behind_by || 0;
    core.info(`Live compare ${pr.base.ref}...${pr.head.ref}: status=${liveStatus}, behind_by=${behindBy}`);
    liveResolved = (liveStatus === 'ahead' || liveStatus === 'identical');
    if (liveResolved) {
      core.info('REQ-10: Live compare shows branch is up-to-date — treating REQUIRED marker as stale.');
    } else if (liveStatus === 'behind' || liveStatus === 'diverged') {
      // Auto-pass when the entire gap is [skip ci] bot commits.
      const gap       = await fetchGapCommits(pr.base.ref, pr.head.ref);
      const allBotGap = gapIsAllBotSkipCi(gap);
      if (allBotGap) {
        core.info(
          `REQ-10: All ${gap.length} gap commit(s) are [skip ci] bot metadata ` +
          `commits — treating REQUIRED marker as auto-resolved.`
        );
        liveResolved = true;
      }
    }
  } catch (err) {
    core.warning(`REQ-10: Could not perform live compare: ${err.message}`);
  }
}

const isResolved = markerResolved || liveResolved;

await core.summary
  .addHeading('REQ-10: Branch Rebase Check', 3)
  .addRaw(isResolved
    ? `\n✅ PASS — Branch is up-to-date (marker resolved or live compare confirms no rebase needed)\n`
    : `\n🔴 FAIL — \`BRANCH_REBASE_REQUIRED\` marker present (${requiredTs.toISOString()}) and branch still behind/diverged.\n`
  )
  .write();

if (!isResolved) {
  core.setFailed(
    'REQ-10 FAIL: A BRANCH_REBASE_REQUIRED marker is present and branch is still behind/diverged. ' +
    'The Copilot Agent MUST rebase the branch before starting work. ' +
    'See the BRANCH_REBASE_REQUIRED comment on this PR for instructions.'
  );
} else {
  core.info('REQ-10 PASS: Branch is up-to-date — rebase gate cleared.');
}

// Helper: upsert a repo variable (create if 404, patch if exists)
async function upsertVar(name, value) {
  try {
    await github.request('PATCH /repos/{owner}/{repo}/actions/variables/{name}', {
      owner: context.repo.owner,
      repo:  context.repo.repo,
      name,
      value,
    });
    core.info(`✅ PATCH ${name} = ${value}`);
  } catch (e) {
    if (e.status === 404) {
      await github.request('POST /repos/{owner}/{repo}/actions/variables', {
        owner: context.repo.owner,
        repo:  context.repo.repo,
        name,
        value,
      });
      core.info(`✅ POST (create) ${name} = ${value}`);
    } else {
      throw e;
    }
  }
}

// 1. Enable agent auth flag
await upsertVar('COPILOT_AGENT_AUTH_ENABLED', 'true');

// 2. Ensure all three delegated agent identities are present
//    (S110 Set-based exact-match pattern — no partial-name false positives)
const REQUIRED_AGENTS = [
  'copilot-swe-agent[bot]',   // GitHub Copilot coding agent
  'github-copilot[bot]',       // Copilot custom agents
  'github-actions[bot]',       // CI/AI workflow agents
];

let currentActors = 'mbaetiong,github-actions[bot]';
try {
  const resp = await github.request(
    'GET /repos/{owner}/{repo}/actions/variables/{name}',
    { owner: context.repo.owner, repo: context.repo.repo,
      name: 'COGNITIVE_BRAIN_ALLOWED_ACTORS' }
  );
  currentActors = resp.data.value || currentActors;
} catch (e) {
  core.warning(`Could not fetch COGNITIVE_BRAIN_ALLOWED_ACTORS: ${e.message}`);
}

const actorSet = new Set(
  currentActors.split(',').map(a => a.trim()).filter(a => a.length > 0)
);
for (const agent of REQUIRED_AGENTS) { actorSet.add(agent); }
const updatedActors = Array.from(actorSet).join(',');

await upsertVar('COGNITIVE_BRAIN_ALLOWED_ACTORS', updatedActors);
core.info(`✅ COGNITIVE_BRAIN_ALLOWED_ACTORS: ${updatedActors}`);

core.setOutput('updated_actors', updatedActors);

const owner = context.repo.owner;
const repo = context.repo.repo;
const prNumber = parseInt('${{ needs.detect-checkbox.outputs.pr_number }}', 10);

core.info(`Dispatching auto-approve-workflows.yml for agent token delegation (PR #${prNumber})`);

try {
  await github.rest.actions.createWorkflowDispatch({
    owner,
    repo,
    workflow_id: 'auto-approve-workflows.yml',
    ref: 'main',
    inputs: {
      approval_source: 'agent-auth-delegation',
      approval_intent: 'conditional_approve',
      target_pr: prNumber.toString(),
      approval_reason: 'Agent token delegation approval from owner',
      approval_ttl_hours: '8',
      dry_run: 'false'
    }
  });
  core.info('✅ auto-approve-workflows.yml dispatched for token delegation');
} catch (err) {
  core.warning(`Hub dispatch failed: ${err.message}`);
}

try {
  await github.rest.actions.createWorkflowDispatch({
    owner:       context.repo.owner,
    repo:        context.repo.repo,
    workflow_id: 'github-guru.yml',
    ref:         context.ref || 'main',
    inputs: {
      mode: 'pr_only',
    },
  });
  core.info('✅ GitHub Guru dispatched for maintainer variable verification');
} catch (e) {
  core.warning(`GitHub Guru dispatch skipped: ${e.message}`);
}

const prNumber = parseInt('${{ needs.detect-checkbox.outputs.pr_number }}', 10);
if (isNaN(prNumber) || prNumber <= 0) {
  core.warning('Invalid PR number for session gate — skipping lock');
  core.setOutput('acquired', 'true');
  core.setOutput('queued', 'false');
  return;
}
const multiSession = '${{ needs.detect-checkbox.outputs.multi_session }}' === 'true';
// TTL is configurable via the COPILOT_SESSION_TTL_SECONDS repo variable.
// Default: 43200 (12 h) for initial system operation; tighten to 3600 (1 h)
// once concurrency is stable by setting the repo variable.
const TTL_SECONDS = parseInt('${{ vars.COPILOT_SESSION_TTL_SECONDS }}', 10) || 43200;
const now = Math.floor(Date.now() / 1000);
const { isRateLimit } = require('./scripts/ci/github_rate_limit_helper.js');

// Helper: get repo variable (returns null if not found)
async function getVar(name) {
  try {
    const { data } = await github.request('GET /repos/{owner}/{repo}/actions/variables/{name}', {
      owner: context.repo.owner, repo: context.repo.repo, name,
    });
    return data.value || '';
  } catch (e) {
    if (e.status === 404) return '';
    if (isRateLimit(e)) {
      core.warning(`Rate limit while reading ${name}; continuing without queue mutation.`);
      return '';
    }
    throw e;
  }
}

// Helper: upsert repo variable
async function upsertVar(name, value) {
  try {
    await github.request('PATCH /repos/{owner}/{repo}/actions/variables/{name}', {
      owner: context.repo.owner, repo: context.repo.repo, name, value,
    });
  } catch (e) {
    if (e.status === 404) {
      await github.request('POST /repos/{owner}/{repo}/actions/variables', {
        owner: context.repo.owner, repo: context.repo.repo, name, value,
      });
    } else if (isRateLimit(e)) {
      core.warning(`Rate limit while writing ${name}; continuing without queue mutation.`);
    } else { throw e; }
  }
}
// GitHub API rejects empty-string variable values (422). Use DELETE to clear.
async function clearVar(name) {
  try {
    await github.request('DELETE /repos/{owner}/{repo}/actions/variables/{name}', {
      owner: context.repo.owner, repo: context.repo.repo, name,
    });
  } catch (e) {
    if (isRateLimit(e)) {
      core.warning(`Rate limit while clearing ${name}; continuing without queue mutation.`);
      return;
    }
    if (e.status !== 404) throw e;
  }
}

const activeSession = await getVar('COPILOT_ACTIVE_SESSION');

// Check if there's an active, non-expired session
let sessionBusy = false;
let activePR = '';
if (activeSession) {
  const parts = activeSession.split('|');
  activePR = parts[0] || '';
  const lockEpoch = parseInt(parts[1] || '0', 10);

  if (isNaN(lockEpoch)) {
    core.warning(`Corrupted session lock format: '${activeSession}' — clearing`);
    await clearVar('COPILOT_ACTIVE_SESSION');
    sessionBusy = false;
  } else {
    const age = now - lockEpoch;

    if (age < TTL_SECONDS && activePR !== String(prNumber)) {
      sessionBusy = true;
      core.info(`Active session on PR #${activePR} (age: ${age}s, TTL: ${TTL_SECONDS}s)`);
    } else if (age >= TTL_SECONDS) {
      core.warning(`Stale session lock cleared (PR #${activePR}, age: ${age}s > TTL ${TTL_SECONDS}s)`);
      await clearVar('COPILOT_ACTIVE_SESSION');
      sessionBusy = false;

      // S230 fix: when a stale TTL lock is cleared, also dequeue
      // and retrigger any PRs that were waiting in the queue.
      // Previously only the `session-release` job (fired on PR close)
      // processed the queue, leaving queued PRs stranded when a
      // session expired naturally (never closed).
      const staleClearedQueue = await getVar('COPILOT_SESSION_QUEUE');
      if (staleClearedQueue) {
        const staleClearedList = staleClearedQueue.split(',').filter(Boolean);
        // Peek at the first entry before mutating the array.
        const nextQueuedPR = parseInt(staleClearedList[0], 10);
        if (!isNaN(nextQueuedPR) && nextQueuedPR > 0 && nextQueuedPR !== prNumber) {
          core.info(`🔓 Stale lock cleared — retriggering queued PR #${nextQueuedPR}`);
          try {
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: nextQueuedPR,
              body: [
                '<!-- session-gate-dequeued -->',
                '## 🔓 Session Available (Stale Lock Cleared)',
                '',
                `Previous session (PR #${activePR}) exceeded the ${TTL_SECONDS / 3600}h TTL and was cleared.`,
                'This PR has been dequeued and the session is now starting.',
                '',
                '@copilot continue',
              ].join('\n'),
            });
            // Remove the dequeued PR from the queue only after the
            // comment was successfully posted (review: avoid removing
            // from queue if comment creation throws).
            staleClearedList.shift();
            await upsertVar('COPILOT_SESSION_QUEUE', staleClearedList.join(','));
            core.info(`✅ Retriggered PR #${nextQueuedPR} after stale TTL cleanup`);
          } catch (err) {
            core.warning(`Failed to retrigger PR #${nextQueuedPR} after stale lock clear: ${err.message}`);
          }
        } else if (!isNaN(nextQueuedPR) && nextQueuedPR === prNumber) {
          // Current PR is first in queue — just clear it from the queue
          staleClearedList.shift();
          await upsertVar('COPILOT_SESSION_QUEUE', staleClearedList.join(','));
          core.info(`Current PR #${prNumber} was first in queue — clearing from queue and proceeding`);
        }
      }
    } else {
      // Same PR — re-acquire is fine
      sessionBusy = false;
    }
  }
}

if (sessionBusy && !multiSession) {
  // Queue this PR — don't post @copilot continue
  core.setOutput('acquired', 'false');
  core.setOutput('queued', 'true');

  // Append to queue variable
  const queue = await getVar('COPILOT_SESSION_QUEUE');
  const queueList = queue ? queue.split(',').filter(Boolean) : [];
  if (!queueList.includes(String(prNumber))) {
    queueList.push(String(prNumber));
    await upsertVar('COPILOT_SESSION_QUEUE', queueList.join(','));
  }

  // S239: upsert the "⏳ Session Queued" comment — update it with the latest
  // queue position if it already exists, otherwise create it. This keeps
  // the queue position live so observers can see where they stand.
  // Fetches the most-recent 100 comments (GitHub max per_page). On very active PRs
  // (>100 comments) an earlier queued marker may not be found; worst case: one extra
  // notification per 100-comment boundary, which is acceptable.
  const { data: prComments } = await github.rest.issues.listComments({
    owner: context.repo.owner, repo: context.repo.repo,
    issue_number: prNumber, per_page: 100,
  });
  const queuedCommentBody = [
    '<!-- session-gate-queued -->',
    '## ⏳ Session Queued',
    '',
    `Another Copilot session is active on PR #${activePR}.`,
    'This PR has been added to the session queue and will be triggered automatically when the active session completes.',
    '',
    '| Detail | Value |',
    '|--------|-------|',
    `| Active Session | PR #${activePR} |`,
    `| Queue Position | ${queueList.length} |`,
    `| Multi-Session | \`${multiSession}\` (default: disabled) |`,
    '',
    '> To enable parallel sessions, check the **Multiple Copilot Coding Agent Sessions** checkbox in the PR body.',
    '',
    `_Session Concurrency Gate — [design](docs/plans/AUTONOMOUS_SELF_HEALING_PROPOSAL_S182.md#session-concurrency-control-design)_`,
  ].join('\n');
  const existingQueuedComment = prComments.find(c =>
    (c.body || '').includes('<!-- session-gate-queued -->')
  );
  if (existingQueuedComment) {
    // Update the existing comment with the latest queue position.
    await github.rest.issues.updateComment({
      owner: context.repo.owner, repo: context.repo.repo,
      comment_id: existingQueuedComment.id,
      body: queuedCommentBody,
    });
    core.info(`⏳ PR #${prNumber} queue position updated (position ${queueList.length}, active: PR #${activePR}).`);
  } else {
    // Post a new queued notification on the PR.
    await github.rest.issues.createComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: prNumber,
      body: queuedCommentBody,
    });
    core.info(`⏳ PR #${prNumber} queued (position ${queueList.length}, active: PR #${activePR}).`);
  }
  core.info(`⏳ PR #${prNumber} queued — active session on PR #${activePR}`);
} else {
  // Acquire the session lock
  const lockValue = `${prNumber}|${now}|${context.runId}`;
  await upsertVar('COPILOT_ACTIVE_SESSION', lockValue);
  core.setOutput('acquired', 'true');
  core.setOutput('queued', 'false');
  core.info(`🔒 Session lock acquired: ${lockValue}`);
}

const prNumber = parseInt('${{ needs.detect-checkbox.outputs.pr_number }}', 10);
if (!prNumber || prNumber <= 0) {
  core.setFailed('Invalid PR number — cannot post comment');
  return;
}
const actors    = '${{ steps.set_vars.outputs.updated_actors }}';
const runUrl    = `https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;
// Read via process.env to prevent code injection via backticks or ${...}
// in markdown content from breaking the JS template literal.
// (See review comment: cbPatterns interpolation, PR #3671.)
const cbPatterns = (process.env.CB_PATTERNS || '').trim();

const UPSERT_MARKER_DELEGATION = '<!-- agent-token-delegation-result -->';
const cbSection = cbPatterns
  ? ['', '---', '', cbPatterns, '']
  : [];
const body = [
  UPSERT_MARKER_DELEGATION,
  '## 🔐 Agent Token Delegation Activated',
  '',
  `Owner approval received ([workflow run](${runUrl})). Repo variables updated:`,
  '',
  '| Variable | Value |',
  '|----------|-------|',
  '| `COPILOT_AGENT_AUTH_ENABLED` | `true` |',
  `| \`COGNITIVE_BRAIN_ALLOWED_ACTORS\` | \`${actors}\` |`,
  '',
  '**Delegated agent coverage:**',
  '- ✅ `copilot-swe-agent[bot]` — GitHub Copilot coding agent',
  '- ✅ `github-copilot[bot]` — Copilot custom agents',
  '- ✅ `github-actions[bot]` — CI/AI workflow agents',
  '',
  '> GitHub Guru (maintainer) has been dispatched to verify variable state.',
  ...cbSection,
  '',
  '@copilot continue',
].join('\n');

// Upsert: update existing or create new
const { data: delegationComments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: prNumber,
  per_page: 100,
});
const existingDelegation = delegationComments.find(c => c.body && c.body.includes(UPSERT_MARKER_DELEGATION));
if (existingDelegation) {
  await github.rest.issues.updateComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    comment_id: existingDelegation.id,
    body,
  });
} else {
  await github.rest.issues.createComment({
    owner:        context.repo.owner,
    repo:         context.repo.repo,
    issue_number: prNumber,
    body,
  });
}
core.info(`✅ Posted @copilot continue on PR #${prNumber}`);

const closedPR = context.payload.pull_request?.number;
if (!closedPR) {
  core.info('No PR context — skipping session release');
  return;
}

const { isRateLimit } = require('./scripts/ci/github_rate_limit_helper.js');

async function getVar(name) {
  try {
    const { data } = await github.request('GET /repos/{owner}/{repo}/actions/variables/{name}', {
      owner: context.repo.owner, repo: context.repo.repo, name,
    });
    return data.value || '';
  } catch (e) {
    if (e.status === 404) return '';
    if (isRateLimit(e)) {
      core.warning(`Rate limit while reading ${name}; continuing without releasing session lock.`);
      return '';
    }
    throw e;
  }
}

// Helper: upsert repo variable
async function upsertVar(name, value) {
  try {
    await github.request('PATCH /repos/{owner}/{repo}/actions/variables/{name}', {
      owner: context.repo.owner, repo: context.repo.repo, name, value,
    });
  } catch (e) {
    if (e.status === 404) {
      await github.request('POST /repos/{owner}/{repo}/actions/variables', {
        owner: context.repo.owner, repo: context.repo.repo, name, value,
      });
    } else if (isRateLimit(e)) {
      core.warning(`Rate limit while writing ${name}; continuing without releasing session lock.`);
    } else { throw e; }
  }
}
// GitHub API rejects empty-string variable values (422). Use DELETE to clear.
async function clearVar(name) {
  try {
    await github.request('DELETE /repos/{owner}/{repo}/actions/variables/{name}', {
      owner: context.repo.owner, repo: context.repo.repo, name,
    });
  } catch (e) {
    if (isRateLimit(e)) {
      core.warning(`Rate limit while clearing ${name}; continuing without releasing session lock.`);
      return;
    }
    if (e.status !== 404) throw e;
  }
}

// Check if the closing PR holds the active session lock
const activeSession = await getVar('COPILOT_ACTIVE_SESSION');
if (!activeSession) {
  core.info('No active session lock to release');
  return;
}

const activePR = activeSession.split('|')[0];
if (activePR !== String(closedPR)) {
  core.info(`Lock held by PR #${activePR}, not closing PR #${closedPR} — skipping`);
  return;
}

// Release the lock
await clearVar('COPILOT_ACTIVE_SESSION');
core.info(`🔓 Released session lock (was: ${activeSession})`);

// Dequeue next PR
const queue = await getVar('COPILOT_SESSION_QUEUE');
if (!queue) {
  core.info('Session queue is empty — no PR to trigger');
  return;
}

const queueList = queue.split(',').filter(Boolean);
const nextPR = queueList.shift();

if (nextPR) {
  const nextPRNumber = parseInt(nextPR, 10);
  if (isNaN(nextPRNumber) || nextPRNumber <= 0) {
    core.warning(`Invalid PR number in queue: '${nextPR}' — skipping`);
    await upsertVar('COPILOT_SESSION_QUEUE', queueList.join(','));
    return;
  }

  // Post @copilot continue on the dequeued PR to trigger its session
  try {
    await github.rest.issues.createComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: nextPRNumber,
      body: [
        '<!-- session-gate-dequeued -->',
        '## 🔓 Session Available',
        '',
        `Previous session (PR #${closedPR}) has completed.`,
        'This PR has been dequeued and the session is now starting.',
        '',
        '@copilot continue',
      ].join('\n'),
    });
    // Only remove from queue after successful comment posting
    await upsertVar('COPILOT_SESSION_QUEUE', queueList.join(','));
    core.info(`✅ Dequeued PR #${nextPR} — posted @copilot continue`);

    // S239: Update the "⏳ Session Queued" comment on any remaining PRs
    // in the queue so they see their new (shifted) queue position.
    for (let i = 0; i < queueList.length; i++) {
      const waitingPR = parseInt(queueList[i], 10);
      if (isNaN(waitingPR) || waitingPR <= 0) continue;
      try {
        const { data: waitingComments } = await github.rest.issues.listComments({
          owner: context.repo.owner, repo: context.repo.repo,
          issue_number: waitingPR, per_page: 100,
        });
        const queuedComment = waitingComments.find(c =>
          (c.body || '').includes('<!-- session-gate-queued -->')
        );
        if (queuedComment) {
          const newPos = i + 1; // 1-based position
          const updatedBody = [
            '<!-- session-gate-queued -->',
            '## ⏳ Session Queued',
            '',
            `Another Copilot session is now active on PR #${nextPRNumber} (just dequeued).`,
            'This PR will be triggered automatically when that session completes.',
            '',
            '| Detail | Value |',
            '|--------|-------|',
            `| Active Session | PR #${nextPRNumber} |`,
            `| Queue Position | ${newPos} |`,
            `| Ahead in queue | ${newPos - 1} PR(s) |`,
            '',
            '> To enable parallel sessions, check the **Multiple Copilot Coding Agent Sessions** checkbox in the PR body.',
            '',
            `_Session Concurrency Gate — [design](docs/plans/AUTONOMOUS_SELF_HEALING_PROPOSAL_S182.md#session-concurrency-control-design)_`,
          ].join('\n');
          await github.rest.issues.updateComment({
            owner: context.repo.owner, repo: context.repo.repo,
            comment_id: queuedComment.id,
            body: updatedBody,
