// Only these variables can be set autonomously (security allowlist).
// Add only non-sensitive config/flag variables here — never secrets.
const ALLOWED_VAR_NAMES = [
  'COPILOT_AGENT_AUTH_ENABLED',
  'COGNITIVE_BRAIN_ALLOWED_ACTORS',
