  'CODEX_SESSION_HANDOFF_ENABLED',
  // Codespace webhook domain variant (preview.app.github.dev vs app.github.dev)
  'WEBHOOK_DOMAIN_VARIANT',
];

const pendingFile = '.codex/pending_var_updates.json';
if (!fs.existsSync(pendingFile)) {
  core.info('No pending_var_updates.json found — nothing to apply');
  core.setOutput('applied', '0');
  return;
}

const updates = JSON.parse(fs.readFileSync(pendingFile, 'utf8'));
const applied = [];
const rejected = [];

for (const [name, value] of Object.entries(updates)) {
  if (!ALLOWED_VAR_NAMES.includes(name)) {
    core.warning(`REJECTED: ${name} — not in autonomous allowlist`);
    rejected.push(name);
    continue;
  }
  try {
    await github.request('PATCH /repos/{owner}/{repo}/actions/variables/{name}', {
      owner: context.repo.owner,
      repo: context.repo.repo,
      name, value,
    });
    core.info(`✅ PATCH ${name} = ${value}`);
    applied.push({ name, value });
  } catch (e) {
    if (e.status === 404) {
      await github.request('POST /repos/{owner}/{repo}/actions/variables', {
        owner: context.repo.owner,
        repo: context.repo.repo,
        name, value,
      });
      core.info(`✅ POST (create) ${name} = ${value}`);
      applied.push({ name, value });
    } else {
      core.error(`Failed to set ${name}: ${e.message}`);
      rejected.push(name);
    }
  }
}

