const applied = '${{ steps.apply_vars.outputs.applied }}' || '0';
const rejected = '${{ steps.apply_vars.outputs.rejected }}' || '0';
const runUrl  = `https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

const MARKER = '<!-- agent-var-writer-result -->';
let body;
if (valid !== 'true') {
