    '## ✅ Agent Variable Writer — Provenance-Chain Update Applied',
    '',
    `| Metric | Value |`,
    `|--------|-------|`,
    `| Variables applied | ${applied} |`,
    `| Variables rejected (not in allowlist) | ${rejected} |`,
    `| Audit log | \`.codex/evidence/var_write_audit.jsonl\` |`,
    '',
    `_[🔗 Workflow run](${runUrl})_`,
  ].join('\n');
}

const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner, repo: context.repo.repo,
  issue_number: context.issue.number, per_page: 100,
});
const existing = comments.find(c => c.body && c.body.includes(MARKER));
if (existing) {
  await github.rest.issues.updateComment({
    owner: context.repo.owner, repo: context.repo.repo,
    comment_id: existing.id, body,
  });
} else {
  await github.rest.issues.createComment({
    owner:        context.repo.owner,
    repo:         context.repo.repo,
    issue_number: context.issue.number,
    body,
  });
}

const issue_body = `## ⚠️ Artifact Monitoring Workflow Failed

The automated artifact monitoring workflow has failed.

**Run**: [#${context.runId}](${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})
**Workflow**: ${context.workflow}
**Event**: ${context.eventName}
**Time**: ${new Date().toISOString()}

This is a meta-failure - the monitoring system itself has encountered an error.
