---

**Auto-generated by Artifact Monitoring Workflow**
`;

// Only create issue if not in dry-run mode
const isDryRun = '${{ github.event.inputs.dry_run }}' === 'true';
if (!isDryRun) {
  await github.rest.issues.create({
    owner: context.repo.owner,
    repo: context.repo.repo,
    title: '[META-MONITOR] Artifact Monitoring Workflow Failed',
    body: issue_body,
    labels: ['automated', 'monitoring-failure', 'critical']
  });
}

const [owner, repo] = process.env.REPO.split('/');
const dryRun        = process.env.DRY_RUN === 'true';
const mode          = process.env.MODE;
const highVolumeThreshold = parseInt(process.env.HIGH_VOLUME_THRESHOLD || '10', 10);
const configuredMaxPasses = parseInt(process.env.HIGH_VOLUME_MAX_PASSES || '6', 10);
const passDelayMs = parseInt(process.env.PASS_DELAY_MS || '12000', 10);
const activeAgentHint = (process.env.ACTIVE_AGENT_HINT || '').toLowerCase();

// ── Helpers ──────────────────────────────────────────────────────
// ALWAYS-ON: Copilot is mandated to approve on behalf of the human admin.
// No opt-in labels or PR body checkboxes are required.
async function isEnabled(_prNum) {
  return true;
}

async function getHeadSha(prNum) {
  const { data: pr } = await github.rest.pulls.get({
    owner, repo, pull_number: parseInt(prNum),
  });
  return pr.head.sha;
}

async function listActionRequiredRuns(headSha) {
  let allRuns = [], page = 1;
  while (true) {
    const { data } = await github.rest.actions.listWorkflowRunsForRepo({
      owner, repo, status: 'action_required',
      head_sha: headSha, per_page: 100, page,
    });
    allRuns = allRuns.concat(data.workflow_runs);
    if (data.workflow_runs.length < 100) break;
    page++;
  }
  return allRuns;
}

async function approvePR(prNum, headSha) {
  core.info(`\n── PR #${prNum} @ ${headSha.slice(0,12)} ──────────────────────`);

  // Enumerate action_required runs for this SHA
  let allRuns = await listActionRequiredRuns(headSha);

  core.info(`   Found ${allRuns.length} run(s) with status=action_required`);
  if (allRuns.length === 0) {
    core.info('   Nothing to approve.');
    return { prNum, headSha, approved: 0, skipped: 0, errors: 0, results: [] };
  }

  let approved = 0, skipped = 0, errors = 0;
  const results = [];

  const activeCopilotSession = activeAgentHint === 'requested' || activeAgentHint === 'in_progress';
  const maxPasses = (allRuns.length >= highVolumeThreshold || activeCopilotSession)
    ? Math.max(2, configuredMaxPasses)
    : 1;
  if (maxPasses > 1) {
    if (activeCopilotSession) {
      core.info(`   Active Copilot agent session detected (${activeAgentHint}). Running up to ${maxPasses} approval passes.`);
    } else {
      core.info(`   High-volume queue detected (>=${highVolumeThreshold}). Running up to ${maxPasses} approval passes.`);
    }
  }

  const processedRunIds = new Set();
  for (let pass = 1; pass <= maxPasses; pass++) {
    if (pass > 1) {
      await new Promise(resolve => setTimeout(resolve, passDelayMs));
      allRuns = await listActionRequiredRuns(headSha);
      core.info(`   Pass ${pass}/${maxPasses}: found ${allRuns.length} remaining action_required run(s).`);
      if (allRuns.length === 0) break;
    }

    for (const run of allRuns) {
      if (processedRunIds.has(run.id)) continue;
      processedRunIds.add(run.id);

      const label = `${run.name || run.workflow_id} (run #${run.id})`;
      if (dryRun) {
        core.info(`[DRY] Would approve: ${label}`);
        results.push({ label, status: '🔍 dry-run' });
        approved++;
        continue;
      }
      try {
        await github.rest.actions.approveWorkflowRun({ owner, repo, run_id: run.id });
        core.info(`✅ Approved: ${label}`);
        results.push({ label, status: '✅ approved' });
        approved++;
      } catch (e) {
        if (e.status === 422 || e.status === 409) {
          core.info(`⏭️  Already processed: ${label}`);
          results.push({ label, status: '⏭️ already processed' });
          skipped++;
        } else if (e.message && e.message.includes('not from a fork pull request')) {
          // Same-repo PRs: approveWorkflowRun may return this message.
          // Fallback: re-run the workflow run via REST using the same token.
          core.info(`🔄 Same-repo PR — using REST rerun fallback for: ${label}`);
          try {
            await github.request('POST /repos/{owner}/{repo}/actions/runs/{run_id}/rerun', {
              owner,
              repo,
              run_id: run.id,
            });
            core.info(`✅ REST rerun requested: ${label}`);
            results.push({ label, status: '✅ rerun (same-repo)' });
            approved++;
          } catch (rerunErr) {
            core.info(`⏭️  REST rerun skipped (may already be approved): ${label}`);
            results.push({ label, status: '⏭️ rerun skipped' });
            skipped++;
          }
        } else {
          core.warning(`❌ Failed to approve ${label}: ${e.message}`);
          results.push({ label, status: `❌ error: ${e.message}` });
          errors++;
        }
      }
    }
  }
  return { prNum, headSha, approved, skipped, errors, results };
}

// ── Build target list ─────────────────────────────────────────────
let targets = [];  // [{prNum, headSha}]
if (mode === 'schedule') {
  const prNums = process.env.PR_LIST.trim().split(/\s+/).filter(Boolean);
  core.info(`⏰ Schedule sweep (always-on): ${prNums.length} open PR(s) — ${prNums.join(', ')}`);
  for (const prNum of prNums) {
    // For schedule, label presence already confirmed — skip re-check
    try {
      const headSha = await getHeadSha(prNum);
      targets.push({ prNum, headSha });
    } catch (e) {
      core.warning(`⚠️ Could not resolve head SHA for PR #${prNum} (${e?.message || String(e)}) — skipping`);
    }
  }
} else {
  const prNum  = process.env.PR_NUMBER;
  const headSha = process.env.HEAD_SHA;
  // Always-on: no opt-in gate — Copilot approves on behalf of human admin.
  targets.push({ prNum, headSha });
}

// ── Approve all targets ───────────────────────────────────────────
const allResults = [];
let totalErrors = 0;
for (const { prNum, headSha } of targets) {
  const r = await approvePR(prNum, headSha);
  allResults.push(r);
  totalErrors += r.errors;
}

// ── Job summary ───────────────────────────────────────────────────
const lines = [
  `## ⚡ Auto-Approve — ${targets.length > 1 ? `${targets.length} PRs` : `PR #${targets[0].prNum}`}`,
  '',
  `| PR | HEAD SHA | Approved | Skipped | Errors |`,
  `|----|---------|---------|---------|--------|`,
];
for (const r of allResults) {
  lines.push(`| #${r.prNum} | \`${r.headSha.slice(0,12)}\` | **${r.approved}** | ${r.skipped} | ${r.errors} |`);
}
lines.push('');
lines.push(`_Mode: ${dryRun ? '🔍 DRY RUN' : '🚀 LIVE'} · Trigger: ${context.eventName} · ${new Date().toISOString()}_`);
core.summary.addRaw('\n' + lines.join('\n') + '\n');
await core.summary.write();

if (totalErrors > 0) {
  core.setFailed(`${totalErrors} run(s) failed to be approved — check the logs above`);
}

const MARKER = '<!-- auto-fix-ci-issues -->';
const message = `${MARKER}\n## ❌ Auto-Fixable CI Issues Detected

The auto-fix script detected issues that can be automatically fixed:

| Pattern | Description | Auto-Fix | Causes CI Failure |
