const fs = require('fs');
const prNumber = context.issue.number;
const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

// Read diagnostic report
let report = {};
try {
  report = JSON.parse(fs.readFileSync('.codex/diagnostic-report.json', 'utf8'));
} catch (error) {
  console.log('Could not read diagnostic report:', error);
  return; // Exit if we can't read the report
}

// Build summary table
const groupedIssues = {};
report.issues.forEach(issue => {
  const key = `${issue.pattern}-${issue.pattern_name}`;
  if (!groupedIssues[key]) {
    groupedIssues[key] = {
      pattern: issue.pattern,
      name: issue.pattern_name,
      count: 0,
      autoFix: issue.auto_fix_available,
      severity: issue.severity
    };
  }
  groupedIssues[key].count++;
});

let summaryTable = '| Pattern | Type | Count | Auto-Fix | Severity |\n';
summaryTable += '|---------|------|-------|----------|----------|\n';

Object.values(groupedIssues).forEach(group => {
  summaryTable += `| ${group.pattern} | ${group.name} | ${group.count} | ${group.autoFix ? '✅ Yes' : '⚠️ Manual'} | ${group.severity === 'error' ? '🔴 Error' : '⚠️ Warning'} |\n`;
});

// Build critical issues section
const autoFixableIssues = report.issues.filter(i => i.auto_fix_available);
let criticalIssues = '#### 🔴 Auto-Fixable Issues (Must Fix Before Merge)\n\n';
if (autoFixableIssues.length === 0) {
  criticalIssues += '_No auto-fixable issues detected._\n\n';
} else {
  autoFixableIssues.slice(0, 10).forEach(issue => {
    criticalIssues += `- **${issue.file}${issue.line ? ':' + issue.line : ''}**\n`;
    criticalIssues += `  - Pattern ${issue.pattern}: ${issue.pattern_name}\n`;
    criticalIssues += `  - ${issue.message}\n\n`;
  });
  if (autoFixableIssues.length > 10) {
    criticalIssues += `_... and ${autoFixableIssues.length - 10} more issues_\n\n`;
  }
}

// Build manual review section
const manualReviewIssues = report.issues.filter(i => !i.auto_fix_available);
let manualIssues = '#### ⚠️ Manual Review Needed (Informational Only)\n\n';
if (manualReviewIssues.length === 0) {
  manualIssues += '_No manual review issues detected._\n\n';
} else {
  manualReviewIssues.slice(0, 5).forEach(issue => {
    manualIssues += `- **${issue.file}${issue.line ? ':' + issue.line : ''}**: ${issue.message}\n`;
  });
  if (manualReviewIssues.length > 5) {
    manualIssues += `_... and ${manualReviewIssues.length - 5} more informational warnings_\n\n`;
  }
}

// Build complete comment
const comment = `## 🤖 Copilot Agent: Auto-Fix Instructions

### 📊 Diagnostic Summary

${summaryTable}

**Total Issues**: ${report.total_issues} | **Auto-Fixable**: ${report.auto_fixable} | **Manual Review**: ${report.manual_review}

---

${criticalIssues}

${manualIssues}

---

