with.script:
github.rest.issues.create({
  owner: context.repo.owner,
  repo: context.repo.repo,
  title: 'Deployment Verification Failed - ${{ github.event.inputs.environment }}',
  body: 'Post-deployment verification failed. Check workflow run for details: ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}',
  labels: ['deployment', 'verification-failed']
});

const maxRuns = Number('${{ inputs.max_runs || 5 }}') || 5;
const lookbackHours = 25;  // slightly more than 1h schedule to avoid gaps
const cutoff = new Date(Date.now() - lookbackHours * 60 * 60 * 1000);
const failuresFile = 'ci-triage-failures.json';

console.log(`Fetching failed workflow runs since ${cutoff.toISOString()} (last ${lookbackHours}h)`);

// Get all workflows with rate-limit guard on paginate
let workflows = [];
try {
  // Check rate limit before paginating
  const rlPre = await github.rest.rateLimit.get();
  const preRemaining = rlPre.data?.resources?.core?.remaining ?? 999;
  if (preRemaining < 50) {
    core.warning(`Rate limit low before workflow list (${preRemaining} remaining) — aborting triage`);
    return;
  }
  workflows = await github.paginate(
    github.rest.actions.listRepoWorkflows,
    { owner: context.repo.owner, repo: context.repo.repo, per_page: 100 }
  );
} catch (e) {
  core.warning(`Could not fetch workflow list: ${e.message}`);
  return;
}
console.log(`Found ${workflows.length} workflows`);

const failures = [];
let activeWorkflowsScanned = 0;
let wfIdx = 0;

for (const wf of workflows) {
  // Skip disabled or this very workflow to avoid self-loops
  if (wf.state !== 'active') continue;
  if (wf.name.includes('Batch CI Failure Triage')) continue;
  activeWorkflowsScanned++;

  // Circuit-break every 10 workflows — check rate limit remaining
  wfIdx++;
  if (wfIdx % 10 === 0) {
    try {
      const rl = await github.rest.rateLimit.get();
      const remaining = rl.data?.resources?.core?.remaining ?? 999;
      if (remaining < 30) {
        core.warning(`Rate limit low (${remaining} remaining) after ${wfIdx} workflows — stopping triage early`);
        break;
      }
    } catch (_) { /* non-fatal */ }
  }

  let runs;
  try {
    const resp = await github.rest.actions.listWorkflowRuns({
      owner: context.repo.owner,
      repo: context.repo.repo,
      workflow_id: wf.id,
      status: 'failure',
      per_page: maxRuns,
    });
    runs = resp.data.workflow_runs || [];
  } catch (e) {
    console.warn(`Could not fetch runs for ${wf.name}: ${e.message}`);
    continue;
  }

  for (const run of runs) {
    // Only report on runs that are newer than the lookback window
    const runDate = new Date(run.created_at);
    if (runDate < cutoff && workflows.length > 20) continue;  // prune old for large repos

    // Get failed jobs for this run
    let failedJobs = [];
    try {
      const jobsResp = await github.rest.actions.listJobsForWorkflowRun({
        owner: context.repo.owner,
        repo: context.repo.repo,
        run_id: run.id,
        filter: 'latest',
        per_page: 30,
      });
      failedJobs = (jobsResp.data.jobs || []).filter(j => j.conclusion === 'failure');
    } catch (e) {
      console.warn(`Could not fetch jobs for run ${run.id}: ${e.message}`);
    }

    if (run.conclusion !== 'failure' && failedJobs.length === 0) continue;

    // Determine failing step names
    const failingSteps = failedJobs.flatMap(j =>
      (j.steps || []).filter(s => s.conclusion === 'failure').map(s => `${j.name} › ${s.name}`)
    );

    failures.push({
      workflow_name: wf.name,
      workflow_file: wf.path.replace('.github/workflows/', ''),
      run_id: run.id,
      run_url: run.html_url,
      run_number: run.run_number,
      created_at: run.created_at,
      head_branch: run.head_branch,
      head_sha: run.head_sha ? run.head_sha.substring(0, 8) : 'unknown',
      pr_number: run.pull_requests && run.pull_requests.length > 0
        ? run.pull_requests[0].number : null,
      failed_jobs: failedJobs.map(j => j.name),
      failing_steps: failingSteps,
      logs_url: run.logs_url,
    });
  }
}

console.log(`Total recent failures found: ${failures.length}`);
require('fs').writeFileSync(failuresFile, JSON.stringify(failures));
core.setOutput('failure_count', failures.length);
core.setOutput('failures_path', failuresFile);
core.setOutput('active_workflows_scanned', activeWorkflowsScanned);

const fs = require('fs');
const failuresPath = process.env.FAILURES_PATH || 'ci-triage-failures.json';
const failures = fs.existsSync(failuresPath)
  ? JSON.parse(fs.readFileSync(failuresPath, 'utf8') || '[]')
  : [];
const activeWorkflowsScanned = Number(process.env.ACTIVE_WORKFLOWS_SCANNED || 0);
const now = new Date().toISOString();
const repoUrl = context.payload.repository.html_url;
const runUrl = `${repoUrl}/actions/runs/${context.runId}`;

if (failures.length === 0) {
  const body = `# ✅ CI Failure Triage Report\n\n` +
    `**Generated:** ${now}\n` +
    `**Status:** No failed workflow runs detected in the last 25 hours.\n\n` +
    `---\n*Triage run: ${runUrl}*`;
  core.setOutput('report_body', body);
  core.setOutput('has_failures', 'false');
  return;
}

// Group by workflow name
const byWorkflow = {};
for (const f of failures) {
  if (!byWorkflow[f.workflow_name]) byWorkflow[f.workflow_name] = [];
  byWorkflow[f.workflow_name].push(f);
}

let body = `# 🔴 CI Failure Triage Report\n\n`;
body += `**Generated:** ${now}\n`;
body += `**Repository:** ${context.repo.owner}/${context.repo.repo}\n`;
body += `**Total Recent Failures:** ${failures.length}\n`;
body += `**Affected Workflows:** ${Object.keys(byWorkflow).length}\n\n`;
body += `**Active Workflows Scanned:** ${activeWorkflowsScanned} (excluding triage workflow)\n\n`;

// Executive summary table
body += `## Summary\n\n`;
body += `| Workflow | Failures | Most Recent Run | Branch | PR |\n`;
body += `|----------|----------|----------------|--------|----|\n`;
for (const [wfName, runs] of Object.entries(byWorkflow)) {
  const latest = runs.sort((a, b) => new Date(b.created_at) - new Date(a.created_at))[0];
  const prLink = latest.pr_number
    ? `[#${latest.pr_number}](${context.payload.repository.html_url}/pull/${latest.pr_number})`
    : 'N/A';
  body += `| ${wfName} | ${runs.length} | [#${latest.run_number}](${latest.run_url}) (${latest.created_at.split('T')[0]}) | \`${latest.head_branch}\` | ${prLink} |\n`;
}

body += `\n---\n\n## Detailed Failure Analysis\n\n`;

for (const [wfName, runs] of Object.entries(byWorkflow)) {
  const latestRun = runs.sort((a, b) => new Date(b.created_at) - new Date(a.created_at))[0];
  body += `### 🔴 ${wfName}\n\n`;
  body += `> **Most recent failure:** [Run #${latestRun.run_number}](${latestRun.run_url}) on branch \`${latestRun.head_branch}\` (commit \`${latestRun.head_sha}\`)\n\n`;

  if (latestRun.failed_jobs.length > 0) {
    body += `**Failed Jobs:**\n`;
    for (const job of latestRun.failed_jobs) {
      body += `- ❌ \`${job}\`\n`;
    }
    body += `\n`;
  }

  if (latestRun.failing_steps.length > 0) {
    body += `**Failing Steps:**\n`;
    for (const step of latestRun.failing_steps.slice(0, 10)) {
      body += `- \`${step}\`\n`;
    }
    body += `\n`;
  }

  body += `**Copilot Resolution Prompt:**\n`;
  body += `\`\`\`\n`;
  body += `@copilot Fix the failing CI workflow "${wfName}" (run #${latestRun.run_number}).\n\n`;
  body += `**Workflow Context:**\n`;
  body += `- Workflow file: .github/workflows/${latestRun.workflow_file}\n`;
  body += `- Branch: ${latestRun.head_branch}\n`;
  body += `- Commit: ${latestRun.head_sha}\n`;
  body += `- Run URL: ${latestRun.run_url}\n`;
  if (latestRun.pr_number) {
    body += `- Associated PR: ${context.payload.repository.html_url}/pull/${latestRun.pr_number}\n`;
  }
  body += `\n**Failure Details:**\n`;
  body += `- Failed jobs: ${latestRun.failed_jobs.join(', ') || 'see run'}\n`;
  if (latestRun.failing_steps.length > 0) {
    body += `- Failing steps: ${latestRun.failing_steps.slice(0, 5).join('; ')}\n`;
  }
  body += `\n**Analysis Instructions:**\n`;
  body += `1. Examine the workflow file and job logs\n`;
  body += `2. Identify root cause (dependency, environment, configuration)\n`;
  body += `3. Check if this pattern matches known CI failure patterns (see #5041)\n`;
  body += `4. Apply fix and validate with local test if possible\n`;
  body += `5. If auto-fixable: commit with [skip ci] and reference this issue\n`;
  body += `6. If manual: create actionable remediation steps\n`;
  body += `\n**Note:** This failure may be part of a recurring pattern. Check the CI Failure Triage Report (#5041) for similar issues.\n`;
  body += `\`\`\`\n\n`;

  if (runs.length > 1) {
    body += `<details><summary>Previous failures (${runs.length - 1} more)</summary>\n\n`;
    for (const run of runs.slice(1)) {
      body += `- [Run #${run.run_number}](${run.run_url}) — ${run.created_at} — branch \`${run.head_branch}\`\n`;
    }
    body += `\n</details>\n\n`;
  }

  body += `---\n\n`;
}

body += `\n*Triage run: ${runUrl} — Refresh by re-running [this workflow](${repoUrl}/actions/workflows/batch-ci-triage.yml)*\n`;

// Truncate if too long for GitHub API (65535 char limit)
if (body.length > 60000) {
  body = body.substring(0, 60000) + '\n\n... *(truncated — see workflow artifact for full report)*';
}

core.setOutput('report_body', body);
core.setOutput('has_failures', failures.length > 0 ? 'true' : 'false');

const fs = require('fs');
const now = new Date().toISOString();
const runUrl = `${context.payload.repository.html_url}/actions/runs/${context.runId}`;
const failuresPath = process.env.FAILURES_PATH || 'ci-triage-failures.json';

// Read failures from file
let failures = [];
try {
  if (fs.existsSync(failuresPath)) {
    const fileContent = fs.readFileSync(failuresPath, 'utf8');
    failures = JSON.parse(fileContent);
  }
} catch (e) {
  console.warn(`Could not read failures from ${failuresPath}:`, e);
}

// Group by pattern/severity
const byPattern = {};
for (const f of failures) {
  const key = f.failure_pattern || 'unknown';
  if (!byPattern[key]) byPattern[key] = [];
  byPattern[key].push(f);
}

const report = {
  timestamp: now,
  repository: `${context.repo.owner}/${context.repo.repo}`,
  total_failures: failures.length,
  affected_workflows: new Set(failures.map(f => f.workflow_name)).size,
  failures_by_pattern: byPattern,
  triage_run_url: runUrl,
  recommendations: {
    immediate: [],
    short_term: [],
    long_term: []
  }
};

// Add recommendations based on patterns
if (failures.length === 0) {
  report.recommendations.immediate.push('No failures detected — CI health is good');
} else if (failures.length > 10) {
  report.recommendations.immediate.push('High failure rate detected — escalate for investigation');
  report.recommendations.short_term.push('Run ci-pattern-healer workflow to auto-fix common patterns');
}

// Auto-fix eligible patterns
const autoFixable = failures.filter(f =>
  ['secrets-pragma', 'pyyaml-dependency', 'unused-imports', 'coverage-threshold'].includes(f.failure_pattern)
);
if (autoFixable.length > 0) {
  report.recommendations.short_term.push(`${autoFixable.length} failures are auto-fixable — run orchestrator`);
}

// Write JSON report
require('fs').writeFileSync('ci-triage-report.json', JSON.stringify(report, null, 2));
core.setOutput('json_report', JSON.stringify(report));
console.log('Generated structured JSON report with', failures.length, 'failures');

const body = process.env.REPORT_BODY || '*(no report generated)*';
const hasFailures = process.env.HAS_FAILURES === 'true';
const TRIAGE_LABEL = 'ci-triage';
const TRIAGE_TITLE_PREFIX = '📊 CI Failure Triage Report';

// Search for an existing OPEN triage issue to update
const existingIssues = await github.rest.issues.listForRepo({
  owner: context.repo.owner,
  repo: context.repo.repo,
  labels: TRIAGE_LABEL,
  state: 'open',
  per_page: 10,
});

const triageIssue = (existingIssues.data || [])
  .find(i => i.title.startsWith(TRIAGE_TITLE_PREFIX) && !i.pull_request);

const title = `${TRIAGE_TITLE_PREFIX} — updated ${new Date().toISOString().split('T')[0]}`;

if (triageIssue) {
  // Update the existing issue body and title so there's only ever one
  await github.rest.issues.update({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: triageIssue.number,
    title: title,
    body: body,
    labels: hasFailures
      ? [TRIAGE_LABEL, 'automated', 'batch-analysis']
      : [TRIAGE_LABEL, 'automated'],
  });
  console.log(`Updated existing triage issue #${triageIssue.number}`);
  core.setOutput('issue_number', triageIssue.number);
} else {
  // No existing issue — create one
  const issue = await github.rest.issues.create({
    owner: context.repo.owner,
    repo: context.repo.repo,
    title: title,
    body: body,
    labels: hasFailures
      ? [TRIAGE_LABEL, 'automated', 'batch-analysis']
      : [TRIAGE_LABEL, 'automated'],
  });
  console.log(`Created new triage issue #${issue.data.number}`);
  core.setOutput('issue_number', issue.data.number);
}

const required = [
  { name: 'branch-divergence', color: 'e4e669', description: 'Branch divergence tracking between 0D_base_ and main' },
  { name: 'automated',         color: '0075ca', description: 'Automated by GitHub Actions'                           },
  { name: 'ci-triage',         color: 'd93f0b', description: 'CI / pipeline triage required'                        },
];
for (const label of required) {
  try {
    await github.rest.issues.getLabel({
      owner: context.repo.owner,
      repo: context.repo.repo,
      name: label.name,
    });
  } catch (err) {
    if (err.status === 404) {
      await github.rest.issues.createLabel({
        owner: context.repo.owner,
        repo: context.repo.repo,
        name: label.name,
        color: label.color,
        description: label.description,
      });
      console.log(`Created label: ${label.name}`);
    } else {
      throw err;
    }
  }
}

const behind        = parseInt(process.env.BEHIND_COUNT)         || 0;
const ahead         = parseInt(process.env.AHEAD_COUNT)          || 0;
const autogen       = parseInt(process.env.AUTOGEN_COUNT)        || 0;
const pipelineMerge = parseInt(process.env.PIPELINE_MERGE_COUNT) || 0;
const agentCommit   = parseInt(process.env.AGENT_COMMIT_COUNT)   || 0;
const absorbers     = pipelineMerge + agentCommit;
const codeleak      = parseInt(process.env.CODELEAK_COUNT)       || 0;
const severity      = process.env.SEVERITY;
const mergeBase     = process.env.MERGE_BASE;
const acResult      = process.env.AUTO_CORRECT_RESULT;
const dryRun        = process.env.DRY_RUN === 'true';
const now           = new Date().toISOString();

const MARKER = '<!-- branch-divergence-monitor -->';

const severityEmoji = {
  healthy: '✅', low: '🟡', high: '🔴', critical: '🚨'
}[severity] || '⚠️';

// Status of auto-correction
let correctionStatus = '';
if (dryRun) {
  correctionStatus = '> ⚠️ **Dry-run mode** — auto-correction was skipped.\n';
} else if (autogen > 0 || pipelineMerge > 0 || agentCommit > 0) {
  if (acResult === 'success') {
    correctionStatus = '> ✅ **Auto-correction applied** — auto-gen files forwarded to `0D_base_`';
    if (pipelineMerge > 0) correctionStatus += ' + pipeline-merge commit(s) fast-forwarded';
    if (agentCommit > 0)   correctionStatus += ` + ${agentCommit} agent-commit(s) absorbed`;
    correctionStatus += '.\n';
  } else {
    correctionStatus = '> ❌ **Auto-correction FAILED** — see [workflow run](' +
      `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}) for details.\n`;
  }
}

// Copilot escalation for code leaks
// When PIPELINE-MERGE or AGENT-COMMIT is also present, auto-correct absorbs
// the code-leaks by fast-forwarding 0D_base_ to all of main — no @copilot needed.
let copilotSection = '';
if (codeleak > 0 && absorbers === 0) {
  copilotSection = `
## 🚨 Human/Code commits detected on \`main\` — @copilot intervention required

${codeleak} commit(s) on \`main\` were authored by a human or contain code changes
that were NOT routed through \`0D_base_\`. These cannot be auto-corrected and require
a Copilot agent session to investigate and resolve.

**Resolution steps:**
1. Identify which PR/branch the commit(s) came from
2. Cherry-pick or re-apply those changes onto \`0D_base_\`
3. If the commit should be reverted from \`main\`, do so in a new sub-PR

@copilot Investigate the branch divergence between \`main\` and \`0D_base_\`.
\`main\` has ${codeleak} non-auto-gen commit(s) that are not in \`0D_base_\`.
Merge base: \`${mergeBase}\`. Run \`branch-divergence-monitor.yml\` with
\`dry_run=true\` to see the full list, then propose a resolution plan.

> **⚠️ GitHub Copilot no-auto-PR policy:** Sessions no longer create pull requests
> by default. After implementing the fix, **explicitly open a pull request targeting
> \`0D_base_\`** with your changes (use \`gh pr create --base 0D_base_ --title "..."\`).
> Do NOT leave changes on a branch without a PR.
`;
}

const body = `${MARKER}
# ${severityEmoji} Branch Divergence Report — \`0D_base_\` ↔ \`main\`

**Updated:** ${now}
**Run:** [#${context.runId}](${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})

${correctionStatus}
## Summary

| Metric | Value |
|--------|-------|
| Merge base | \`${mergeBase.slice(0,12)}\` |
| **0D_base_ AHEAD** (staged work) | ${ahead} commit(s) — ✅ expected |
| **main AHEAD** (potential leaks) | ${behind} commit(s) |
| → Auto-gen leaks (self-corrected) | ${autogen} |
| → Pipeline-merge (auto-fwd to 0D_base_) | ${pipelineMerge} |
| → Agent-commits (Copilot PR work, auto-absorbed) | ${agentCommit} |
| → Code leaks (need @copilot) | ${codeleak} |
| Severity | **${severity.toUpperCase()}** ${severityEmoji} |

## What to do

| Situation | Corrective Action |
|-----------|------------------|
| Only auto-gen leaks | Re-run \`branch-divergence-monitor.yml\` or \`forward-sync-autogen.yml\` |
| Only pipeline-merge leaks | Re-run \`branch-divergence-monitor.yml\` — auto-correct fast-forwards 0D_base_ |
| Only agent-commits | Re-run \`branch-divergence-monitor.yml\` — auto-correct absorbs via fast-forward |
| Code leaks on \`main\` (no absorbers) | Open a @copilot session on the \`0D_base_\` → \`main\` PR |
| Behind > 10 for >24 h | Accelerate staging-gate merge (PR #3630 or equivalent) |

${copilotSection}
${absorbers > 0 && codeleak > 0 ? `
## ℹ️ Pipeline-merge / Agent-commits + Code commits — auto-correct will absorb

A staging-gate merge commit or Copilot agent commit was detected alongside
${codeleak} code commit(s). The **auto-correct job** will fast-forward
\`0D_base_\` to include **all** of \`main\`'s history, effectively absorbing
the code commits. No @copilot session is needed — the next scheduled run
should show \`severity=healthy\`.
` : ''}

---
*Auto-generated by [branch-divergence-monitor.yml](${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/blob/main/.github/workflows/branch-divergence-monitor.yml)*
*See runbook: [BRANCH_DIVERGENCE_PREVENTION.md](.codex/docs/BRANCH_DIVERGENCE_PREVENTION.md)*
`;

// Upsert: find open issue with our marker, update it, or create new
const issues = await github.rest.issues.listForRepo({
  owner: context.repo.owner,
  repo: context.repo.repo,
  state: 'open',
  labels: 'branch-divergence',
});

const existing = issues.data.find(i => i.body && i.body.includes(MARKER));

const title = `${severityEmoji} Branch Divergence: 0D_base_ ${ahead}↑ ${behind}↓ main — ${severity.toUpperCase()}`;

if (existing) {
  await github.rest.issues.update({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: existing.number,
    title,
    body,
  });
  console.log(`Updated divergence issue #${existing.number}`);
} else {
  const created = await github.rest.issues.create({
    owner: context.repo.owner,
    repo: context.repo.repo,
    title,
    body,
    labels: ['branch-divergence', 'automated', 'ci-triage'],
  });
  console.log(`Created divergence issue #${created.data.number}`);
}

const owner = context.repo.owner;
const repo  = context.repo.repo;
const maxAgeDays  = parseInt('${{ inputs.max_age_days || 7 }}', 10);
const dryRun      = ('${{ inputs.dry_run }}' === 'true');
const maxAgeMs    = maxAgeDays * 24 * 60 * 60 * 1000;
const now         = Date.now();

console.log(`Pruning caches last accessed > ${maxAgeDays} days ago`);
console.log(`Dry run: ${dryRun}`);

let page       = 1;
let totalBytes = 0;
let deleted    = 0;
let kept       = 0;
const toDelete = [];

// Collect all caches (paginate with rate-limit guard)
while (true) {
  // Circuit-break if REST rate limit is low
  try {
    const rl = await github.rest.rateLimit.get();
    const remaining = rl.data?.resources?.core?.remaining ?? 999;
    if (remaining < 20) {
      core.warning(`Rate limit low (${remaining} remaining) — stopping cache pagination at page ${page}`);
      break;
    }
  } catch (_) { /* non-fatal — proceed */ }

  const resp = await github.rest.actions.getActionsCacheList({
    owner, repo, per_page: 100, page
  });
  const caches = resp.data.actions_caches;
  if (!caches || caches.length === 0) break;

  for (const cache of caches) {
    const ageMs = now - new Date(cache.last_accessed_at).getTime();
    if (ageMs > maxAgeMs) {
      toDelete.push(cache);
      totalBytes += cache.size_in_bytes || 0;
    } else {
      kept++;
    }
  }
  if (caches.length < 100) break;
  page++;
}

console.log(`\nFound ${toDelete.length} cache(s) to delete, ${kept} to keep.`);
const freedMB = (totalBytes / 1024 / 1024).toFixed(1);

if (!dryRun) {
  for (const cache of toDelete) {
    console.log(`  Deleting: ${cache.key} (id=${cache.id}, last_accessed=${cache.last_accessed_at})`);
    try {
      await github.rest.actions.deleteActionsCacheById({ owner, repo, cache_id: cache.id });
      deleted++;
    } catch (err) {
      console.warn(`  ⚠️  Failed to delete cache ${cache.id}: ${err.message}`);
    }
  }
  console.log(`\n✅ Deleted ${deleted} cache(s), freed ~${freedMB} MB`);
} else {
  for (const cache of toDelete) {
    console.log(`  [DRY RUN] Would delete: ${cache.key} (id=${cache.id})`);
  }
  console.log(`\n[DRY RUN] Would free ~${freedMB} MB across ${toDelete.length} cache(s)`);
}

// Post job summary
const action  = dryRun ? 'Would delete' : 'Deleted';
const summary = [
  `## 🗑️ Cache Pruning Summary`,
  ``,
  `| Metric | Value |`,
  `|--------|-------|`,
  `| Max cache age | ${maxAgeDays} days |`,
  `| Dry run | ${dryRun} |`,
  `| Caches examined | ${toDelete.length + kept} |`,
  `| ${action} | ${dryRun ? toDelete.length : deleted} |`,
  `| Kept | ${kept} |`,
  `| Space freed | ~${freedMB} MB |`,
].join('\n');
await core.summary.addRaw(summary).write();

const prNumber = parseInt(process.env.PR_NUMBER, 10);
const EXPIRED_MARKER = 'SESSION_TIMEBOX_EXPIRED';
const SUMMARY_MARKER = '## 🧠 Session Summary';

const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: prNumber,
  per_page: 100,
});

// Find most recent SESSION_TIMEBOX_EXPIRED comment
const expiredComment = comments
  .filter(c => c.body.includes(EXPIRED_MARKER))
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))[0];

if (!expiredComment) {
  core.setOutput('blocked', 'false');
  return;
}

const expiredAt = new Date(expiredComment.created_at);

// Check for Session Summary posted AFTER the expiry
const summaryAfterExpiry = comments.find(c =>
  c.body.includes(SUMMARY_MARKER) &&
  new Date(c.created_at) > expiredAt
);

if (summaryAfterExpiry) {
  core.setOutput('blocked', 'false');
} else {
  core.setOutput('blocked', 'true');
  // Post rejection comment
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: prNumber,
    body: [
      '⛔ **Chat-Ops: Session Summary Required**',
      '',
      `\`SESSION_TIMEBOX_EXPIRED\` was posted at ${expiredComment.created_at} but no \`## 🧠 Session Summary\` has been posted since.`,
      '',
      '**Action required:** Post a PR comment containing `## 🧠 Session Summary` with:',
      '- Topics covered and key findings',
      '- Suggested follow-up `@copilot` prompt for the next session',
      '',
      'Once posted, re-run `/copilot continue`.',
      '',
      '_chatops session-summary gate | Tier-1 enforcement | [GROUNDED_VS_SOFT_ENFORCEMENT.md](.codex/docs/GROUNDED_VS_SOFT_ENFORCEMENT.md)_',
      '',
      '---',
      `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
    ].join('\n'),
  });
}

