with.script:
const wfName = context.payload.workflow_run.name;
const wfSlug = wfName.toLowerCase()
                 .replace(/[^a-z0-9]+/g, '-')
                 .replace(/^-+|-+$/g, '');

// Critical patterns — first match wins
const CRITICAL = [
  { re: /security|codeql|semgrep|vuln/i,
    extra: ['security-risk'],   badge: '🔐 Security Risk'   },
  { re: /build|docker|deploy|publish|release/i,
    extra: ['build-break'],     badge: '🏗️ Build Break'     },
  { re: /test|pytest|auth|critical.path/i,
    extra: ['test-regression'], badge: '🧪 Test Regression' },
];

let severity = 'normal', extraLabels = [], badge = '';
for (const p of CRITICAL) {
  if (p.re.test(wfName)) {
    severity   = 'critical';
    extraLabels = p.extra;
    badge       = p.badge;
    break;
  }
}

const baseLabels = severity === 'critical'
  ? ['ci-failure', 'priority-critical', ...extraLabels]
  : ['ci-failure', 'priority-medium', 'needs-investigation'];

core.setOutput('severity',    severity);
core.setOutput('labels_json', JSON.stringify(baseLabels));
core.setOutput('wf_slug',     wfSlug);
core.setOutput('badge',       badge);
core.info(`"${wfName}" → severity=${severity} labels=${JSON.stringify(baseLabels)}`);

const { data } = await github.rest.actions.listJobsForWorkflowRun({
  owner: context.repo.owner,
  repo: context.repo.repo,
  run_id: context.payload.workflow_run.id,
  filter: 'latest',
});
const failed = data.jobs.filter(j => j.conclusion === 'failure');
const md = failed.length
  ? failed.map(j => {
      const steps = (j.steps || [])
        .filter(s => s.conclusion === 'failure')
        .map(s => `  - Step \`${s.name}\``).join('\n');
      return `**❌ ${j.name}**\n${steps || '  _(no step-level detail)_'}`;
    }).join('\n\n')
  : '_No individual job failures found — see run for details._';
const first = failed[0];
core.setOutput('failed_jobs_md',  md);
core.setOutput('failed_job_count', failed.length.toString());
core.setOutput('first_job_url',   first?.html_url || '');
core.setOutput('first_job_name',  first?.name     || '');

const wfSlug = '${{ steps.classify.outputs.wf_slug }}';
const owner  = context.repo.owner;
const repo   = context.repo.repo;

// L1 — open issue already tracking this workflow slug
const { data: openIssues } = await github.rest.issues.listForRepo({
  owner, repo, state: 'open', labels: 'ci-failure', per_page: 50,
});
const existingIssue = openIssues.find(i =>
  i.title.toLowerCase().includes(wfSlug.replace(/-/g, ' ')) ||
  i.title.toLowerCase().includes(wfSlug) ||
  (i.body || '').includes(`<!-- CI_FAILURE_TRACKER:${wfSlug.substring(0,60)} -->`)
);
if (existingIssue) {
  core.info(`L1: issue #${existingIssue.number} already tracks "${wfSlug}" — skip`);
  core.setOutput('action',         'skip');
  core.setOutput('existing_issue', existingIssue.number.toString());
  return;
}

// L2 — scan ALL branches for ANY active fix branch.
// Because this job holds the global concurrency lock the scan is
// race-free: no other instance of this workflow can create a branch
// between this check and our own branch creation.
const FIX_PREFIXES = ['fix/ci-', 'copilot/fix-ci-', 'hotfix/ci-', 'fix/main-ci-'];
let activeBranch = '', activePR = '';
let page = 1;
while (!activeBranch) {
  const { data: branches } = await github.rest.repos.listBranches({
    owner, repo, per_page: 100, page,
  });
  for (const b of branches) {
    if (FIX_PREFIXES.some(p => b.name.toLowerCase().startsWith(p))) {
      activeBranch = b.name;
      break;
    }
  }
  if (branches.length < 100 || activeBranch) break;
  page++;
}

if (activeBranch) {
  const { data: prs } = await github.rest.pulls.list({
    owner, repo, state: 'open',
    head: `${owner}:${activeBranch}`, per_page: 5,
  });
  activePR = prs[0]?.html_url || '';
  core.info(`L2: fix branch "${activeBranch}" active — queue new failure`);
  core.setOutput('action',            'queue');
  core.setOutput('active_fix_branch', activeBranch);
  core.setOutput('active_fix_pr',     activePR);
  return;
}

core.info(`No existing tracker — will create issue`);
core.setOutput('action', 'new_issue');

const run          = context.payload.workflow_run;
const wfName       = run.name;
const wfSlug       = '${{ needs.triage.outputs.wf_slug }}';
const severity     = '${{ needs.triage.outputs.severity }}';
const labels       = JSON.parse('${{ needs.triage.outputs.labels_json }}');
const action       = '${{ needs.triage.outputs.action }}';
const activeBranch = '${{ needs.triage.outputs.active_fix_branch }}';
const activePR     = '${{ needs.triage.outputs.active_fix_pr }}';
