SHA: ${{ github.event.workflow_run.head_sha }}
Run URL: ${{ github.event.workflow_run.html_url }}

Classify this failure against the known pattern library.
If it matches a known pattern, return that pattern_id.
If it's novel, propose a new pattern_id (P-047, P-048, etc.).

run_commands.command:
python3 - << 'EOF'
import re
from pathlib import Path

def validate_heading_hierarchy(file_path):
    """Validate that headings follow proper hierarchy (no skips)."""
    issues = []
    last_level = 0

    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    for line_num, line in enumerate(lines, 1):
        match = re.match(r'^(#+)\s+(.+)$', line.strip())
        if match:
            level = len(match.group(1))

            # Check if first heading is H1
            if last_level == 0 and level != 1:
                issues.append((line_num, level, f"First heading should be H1, got H{level}"))

            # Check for hierarchy jumps (e.g., H1 to H3 without H2)
            if last_level > 0 and level > last_level + 1:
                issues.append((line_num, level, f"Hierarchy jump from H{last_level} to H{level}"))

            last_level = level

    return issues

all_issues = {}
md_files = list(Path('docs').rglob('*.md')) + list(Path('.').glob('*.md'))

for md_file in sorted(set(md_files)):
    if any(skip in str(md_file) for skip in ['node_modules', '.git', '.venv']):
        continue

    issues = validate_heading_hierarchy(md_file)
    if issues:
        all_issues[md_file] = issues

if all_issues:
    print("## ⚠️ Heading Hierarchy Issues Found\n")
    for file_path, issues in all_issues.items():
        print(f"\n### {file_path}")
        for line, level, message in issues:
            print(f"  Line {line}: {message}")
    exit(1)
else:
    print("## ✅ All heading hierarchies are valid!")
    exit(0)
EOF

