const q2 = dynamicQ2 || FALLBACK_Q2;
const q3 = dynamicQ3 || FALLBACK_Q3;

// ── Resolve Discussion node ID ──────────────────────────────────
let discussionId;
try {
  const res = await github.graphql(`
    query($owner: String!, $name: String!, $number: Int!) {
      repository(owner: $owner, name: $name) {
        discussion(number: $number) { id title }
      }
    }`, {
    owner: context.repo.owner,
    name:  context.repo.repo,
    number: DISCUSSION_NUMBER,
  });
  discussionId = res.repository.discussion.id;
  core.info(`Resolved Discussion #${DISCUSSION_NUMBER}: ${res.repository.discussion.title}`);
} catch(e) {
  core.warning(`Could not resolve Discussion #${DISCUSSION_NUMBER}: ${e.message}`);
  return;
}

// ── Helper: upsert (create-or-update) a discussion comment ─────
async function upsertComment(marker, body) {
  if (dryRun) {
    core.info(`[DRY RUN] Would upsert comment with marker: ${marker.slice(0, 60)}`);
    core.info(`[DRY RUN] Body preview (first 200 chars):\n${body.slice(0, 200)}`);
    return;
  }
  // Check if a comment with this marker already exists — paginate all
  // comments so dedup works even when the discussion has >50 replies.
  // Includes GraphQL rateLimit circuit-breaker: stops if remaining < 20.
  let existingId = null;
  try {
    let cursor = null;
    let hasNextPage = true;
    paginateLoop: while (hasNextPage) {
      const existing = await github.graphql(`
        query($id: ID!, $cursor: String) {
          rateLimit { remaining resetAt }
          node(id: $id) {
            ... on Discussion {
              comments(first: 50, after: $cursor) {
                nodes { id body }
                pageInfo { hasNextPage endCursor }
              }
            }
          }
        }`, { id: discussionId, cursor });
      const rlRemaining = existing?.rateLimit?.remaining ?? 999;
      if (rlRemaining < 20) {
        core.warning(`GraphQL rate limit low (${rlRemaining} remaining) — stopping discussion paginate`);
        break paginateLoop;
      }
      const page      = existing?.node?.comments || {};
      const nodes     = page.nodes || [];
      const pageInfo  = page.pageInfo || {};
      const found     = nodes.find(c => (c.body || '').includes(marker));
      if (found) { existingId = found.id; break paginateLoop; }
      hasNextPage = pageInfo.hasNextPage || false;
      cursor      = pageInfo.endCursor   || null;
    }
  } catch(e) {
    core.warning(`Could not check existing comments: ${e.message}`);
  }

  if (existingId) {
    // Update existing comment
    await github.graphql(`
      mutation($id: ID!, $body: String!) {
        updateDiscussionComment(input: { commentId: $id, body: $body }) {
          comment { id url }
        }
      }`, { id: existingId, body });
    core.info(`Updated existing comment (marker: ${marker.slice(0, 50)})`);
  } else {
    // Create new comment
    const r = await github.graphql(`
      mutation($discussionId: ID!, $body: String!) {
        addDiscussionComment(input: { discussionId: $discussionId, body: $body }) {
          comment { id url }
        }
      }`, { discussionId, body });
    const url = r?.addDiscussionComment?.comment?.url || '(no url)';
    core.info(`Posted new comment: ${url}`);
  }
}

