  `---`,
  ``,
  `_This comment is updated (not duplicated) per session. Previous session research is`,
  `replaced with the current session's findings._`,
  ``,
  `> 💡 **To respond:** Reply to individual topics in this thread or add a ✅ reaction`,
  `> to indicate a topic has been addressed. The agent polls for responses at session close.`,
].join('\n');

// ── Build open check-in body ────────────────────────────────────
const openMarker = `<!-- agent-checkin-open:${sessionId} -->`;
const openBody = [
  openMarker,
  `## 🤖 Agent Check-In — Session Open: ${sessionId} (${now})`,
  ``,
  `> **Session:** \`${sessionId}\` | **Commit:** \`${sha}\` | **Branch:** \`${ref}\``,
  `> **Cognitive Brain:** [Dashboard](https://aries-serpent.github.io/_codex_/) · [App](https://aries-serpent.github.io/_codex_/cognitive_app/)`,
  ``,
  `---`,
  ``,
  `### ❓ Questions for Maintainer/Admin`,
  ``,
  `The following questions arise from deep codebase analysis and are for review by`,
  `maintainers/admins with 🔐 Agent Token Delegation and 💰 Cost Governance approval.`,
  `Please respond in this thread or react with ✅ to indicate resolution.`,
  ``,
  // S300: Use dynamic Q1/Q2/Q3 from PDA pattern library (set by gen_questions step)
  q1,
  ``,
  q2,
  ``,
  q3,
  ``,
  `---`,
  ``,
  `### 🧠 Deep Reflection Question (Cognitive Brain)`,
  ``,
  `> *This question leverages the [Cognitive Brain](https://aries-serpent.github.io/_codex_/)`,
  `> to generate a reflective, high-insight inquiry. Increased hallucination is intentional —`,
  `> the goal is speculative, cross-domain thinking for systemic improvement.*`,
  ``,
  `**Reflective Question:**`,
  ``,
  `*"Given the current trajectory of this autonomous CI self-healing system (S195→S214,`,
  `27%→95% RAG coverage, rescue comment scaffolding, agent-auth-delegation repair,`,
  `session re-trigger mechanism, and cognitive brain integration), what is the`,
  `**single most likely systemic failure mode** that will cause this system to degrade`,
  `over the next 30 days if left unaddressed? Specifically: the self-healing loop`,
  `depends on \`CODEX_MASTER_KEY\` appearing as \`@mbaetiong\` for Copilot to respond.`,
  `What happens when that token expires or its scope is reduced? Is the fallback chain`,
  `(\`CODEX_BACKUP_KEY → GITHUB_TOKEN\`) sufficient to keep the loop alive, or does the`,
  `system silently degrade? What is the minimal structural change that would make this`,
  `resilient to credential rotation without human intervention?"*`,
  ``,
  `---`,
  ``,
  `_Copilot Coding Agent will poll for responses before concluding this session._`,
].join('\n');

// ── Post both comments ──────────────────────────────────────────
try {
  await upsertComment(researchMarker, researchBody);
  core.info('✅ Research topics posted to Discussion #3756');
} catch(e) {
  core.warning(`Failed to post research topics: ${e.message}`);
}

try {
  await upsertComment(openMarker, openBody);
  core.info('✅ Open check-in posted to Discussion #3756');
} catch(e) {
  core.warning(`Failed to post open check-in: ${e.message}`);
}

if (dryRun) {
  core.info('[DRY RUN] dry_run=true — would have posted the above bodies. No GraphQL mutations executed.');
}

// Missed-trigger guard (S221 AfterMath fix):
// When Copilot reacts 👀 to a rescue comment but no session starts
// (e.g., a push invalidates the queued session before it can begin),
// session-done PATH A never fires. This step fires on every push and
// independently scans for unanswered rescue comments.
const dryRun = (process.env.DRY_RUN || 'false') === 'true';

// S144 fix: If this push was made by a Copilot agent bot, the session
// is actively running. The session will post "Resolved at SHA" when it
// finishes. Firing a retrigger mid-session creates competing sessions.
// Human approval is pre-granted via COPILOT_AGENT_AUTH_ENABLED=true and
// 💰 Cost Proposal Approved — sessions start immediately, no gate needed.
const COPILOT_PUSH_ACTORS = new Set([
  'copilot-swe-agent[bot]', 'github-copilot[bot]', 'copilot[bot]',
]);
if (COPILOT_PUSH_ACTORS.has(context.actor)) {
  core.info(`Push actor is Copilot agent (${context.actor}) — session is active. Skipping missed-trigger guard to avoid competing retriggers. Pre-approval: COPILOT_AGENT_AUTH_ENABLED=true.`);
  return;
}

// Find the open PR for this branch
let prNumber = parseInt(process.env.PR_NUMBER || '0', 10);
if (!prNumber) {
  try {
    const branchName = context.ref_name
        || (context.payload.ref || '').replace('refs/heads/', '')
        || '';
    const prs = await github.rest.pulls.list({
      owner: context.repo.owner,
      repo: context.repo.repo,
      state: 'open',
      head: `${context.repo.owner}:${branchName}`,
      per_page: 1,
    });
    prNumber = prs.data[0]?.number || 0;
  } catch(e) {
    core.info(`Could not find open PR: ${e.message}`);
    return;
  }
}
if (!prNumber) {
  core.info('No open PR found for this push — skipping missed-trigger guard.');
  return;
}

// S226 fix: use GraphQL `last: 100` to get the NEWEST 100 comments.
// The prior REST issues.listComments(per_page: 30) returned the OLDEST
// 30 comments (ascending order), causing dedup to miss retrigger markers
// and Copilot "Fixed in" responses that accumulated in newer comments.
// This caused the guard to re-post the same retrigger on every push.
let comments = [];
try {
  const gql = await github.graphql(
    `query($owner: String!, $repo: String!, $pr: Int!) {
      repository(owner: $owner, name: $repo) {
        pullRequest(number: $pr) {
          comments(last: 100) {
            nodes {
              databaseId
              createdAt
              url
              body
              author { login }
            }
          }
        }
      }
    }`,
    {
      owner: context.repo.owner,
      repo:  context.repo.repo,
      pr:    prNumber,
    }
  );
  comments = gql?.repository?.pullRequest?.comments?.nodes || [];
} catch(e) {
  core.info(`Could not fetch PR comments: ${e.message}`);
  return;
}

// Find unanswered rescue comments.
// Unified marker format (S294): <!-- ci-rescue-sha:{pr_number}:{sha12} -->
//   All workflows now use this single canonical format.
//   Posted by scripts/ci/post_rescue_comment.py — called by every
//   rescue-comment job via actions/checkout@v7 + python step.
//   SHA-scoped: multiple workflows failing on the same commit APPEND
//   to the same comment rather than posting new threads.
//
// Legacy formats (still recognised for backward compat with older comments):
//   <!-- ci-rescue:NNN -->              (pre-S294 PR-scoped)
//   <!-- ci-rescue:NNN:sha12chars -->    (pre-S294 SHA-scoped)
//
// An "answered" rescue comment already has:
//   (a) a <!-- session-done-retrigger --> dedup marker for its rescue ID, OR
//   (b) a Copilot agent reply containing resolution language after it.
// Matches unified and all legacy formats:
//   <!-- ci-rescue-sha:3854:abc123def456 --> (S294 canonical — validate.yml et al)
//   <!-- ci-rescue:3854 -->                  (legacy PR-scoped)
//   <!-- ci-rescue:3854:abc123def456 -->      (legacy SHA-scoped)
const rescueMarkerRe   = /<!--\s*ci-rescue(?:-sha)?:\d+(?::[0-9a-f]+)?\s*-->/;
const retriggerMarkerRe = /<!--\s*session-done-retrigger\s*-->/;
// Only match actual Copilot agent logins — NOT github-actions[bot], which
// posts the rescue comments themselves (matching it gave false-positive hasResponse).
const COPILOT_AGENT_LOGINS = new Set([
  'copilot-swe-agent[bot]', 'github-copilot[bot]', 'copilot[bot]', 'copilot',
]);

// S239 fix: find the LATEST rescue comment regardless of previous retriggers.
// The old approach (retriggerMarkers set) permanently blocked re-triggering
// the same rescue ID — even when GitHub silently dropped the queued session
// after a new commit was pushed. Now we let hasResponse and the
// Copilot-acted-after-retrigger check handle deduplication correctly.
let latestRescue = null;
for (const c of comments) {
  const body = c.body || '';
  if (rescueMarkerRe.test(body)) {
    // Extract rescue ID from PR-scoped, SHA-scoped, or -sha-suffixed marker.
    const markerMatch = body.match(/<!--\s*ci-rescue(?:-sha)?:(\d+(?::[0-9a-f]+)?)\s*-->/);
    const rescueId = markerMatch ? markerMatch[1] : String(c.databaseId);
    // Always update latestRescue — we want the LAST rescue comment in the list.
    latestRescue = { id: rescueId, commentId: c.databaseId, url: c.url || '', createdAt: c.createdAt || null, body };
  }
}

if (!latestRescue) {
  core.info('No rescue comments found — missed-trigger guard: nothing to do.');
  return;
}

// S244 dedup: if the latest rescue comment is an RCA comment (Channel B,
// SHA-scoped) that already contains a direct @copilot invocation, the RCA
// itself IS the trigger — no additional retrigger is needed.
// Allow a retrigger only if the RCA is older than 45 minutes AND still has
// no Copilot response (session was permanently dropped by GitHub).
const rcaHasCopilotCall = /@copilot(?:\+[a-z0-9.\-]+)?/i.test(latestRescue.body);
if (rcaHasCopilotCall) {
  // createdAt is now populated by the GraphQL query (was missing before this fix,
  // so ageMs was always Infinity and the grace period never triggered).
  const createdAt = latestRescue.createdAt ? new Date(latestRescue.createdAt) : null;
  const ageMs = createdAt ? Date.now() - createdAt.getTime() : Infinity;
  const GRACE_MS = 45 * 60 * 1000; // 45 minutes
  if (ageMs < GRACE_MS) {
    core.info(
      `Latest rescue comment already invokes @copilot directly and is only ` +
      `${Math.round(ageMs / 60000)} min old — deferring retrigger (RCA is still live).`
    );
    return;
  }
  core.info(
    `Latest rescue comment invokes @copilot but is ${Math.round(ageMs / 60000)} min old ` +
    `(>${Math.round(GRACE_MS / 60000)} min grace period) — checking if session responded.`
  );
}

// Check if there is a Copilot agent response AFTER the rescue comment that
// explicitly resolves it. Accept both "X in SHA" and "X at SHA" forms since
// Copilot responses vary between "Fixed in <commit>" and "Fixed at <commit>".
// Using COPILOT_AGENT_LOGINS avoids false-positives from github-actions[bot]
// CI update comments that are not resolution responses.
const rescueIndex = comments.findIndex(c => c.databaseId === latestRescue.commentId);
const hasResponse = rescueIndex >= 0 && comments.slice(rescueIndex + 1).some(c => {
  const login = c.author?.login || '';
  const body  = (c.body || '').toLowerCase();
  return (
    COPILOT_AGENT_LOGINS.has(login) &&
    (
      body.includes('fixed in')    || body.includes('fixed at')    ||
      body.includes('addressed in') || body.includes('addressed at') ||
      body.includes('resolved in')  || body.includes('resolved at')
    )
  );
});

if (hasResponse) {
  core.info(`Rescue comment ${latestRescue.id} already has a Copilot resolution response — skipping.`);
  return;
}

// S221-R1: Commit-resolution check.
// If a Copilot-agent commit was pushed to this PR branch AFTER the rescue
// comment was created, a session ran and addressed the issue.  Skip the
// retrigger to avoid waking a new session for an already-resolved problem.
// This closes the gap where Copilot pushes a fix commit but the closing
// comment uses language not covered by the "fixed in/at" regex above.
if (latestRescue.createdAt) {
  let prCommits = [];
  try {
    const commitsResp = await github.rest.pulls.listCommits({
      owner: context.repo.owner,
      repo:  context.repo.repo,
      pull_number: prNumber,
      per_page: 30,
    });
    prCommits = commitsResp.data || [];
  } catch(e) {
    core.info(`Could not fetch PR commits for commit-resolution check: ${e.message}`);
  }
  const rescueCreatedAt = new Date(latestRescue.createdAt);
  const resolvedByCommit = prCommits.some(c => {
    // Check both the GitHub author login and the git committer date.
    const authorLogin    = c.author?.login    || '';
    const committerLogin = c.committer?.login || '';
    const committedAt    = c.commit?.committer?.date
      ? new Date(c.commit.committer.date) : null;
    return (
      (COPILOT_AGENT_LOGINS.has(authorLogin) || COPILOT_AGENT_LOGINS.has(committerLogin)) &&
      committedAt !== null &&
      committedAt > rescueCreatedAt
    );
  });
  if (resolvedByCommit) {
    core.info(
      `Rescue ${latestRescue.id}: a Copilot-agent commit was pushed after ` +
      `${latestRescue.createdAt} — treating as resolved, skipping retrigger.`
    );
    return;
  }
}

// Dedup: if a retrigger was already posted for this rescue, only skip posting
// ANOTHER retrigger if Copilot has taken some action (posted any comment) after
// that retrigger. If Copilot has NOT acted after the retrigger, the queued
// session was silently dropped (e.g. a new commit push invalidated it), so we
// allow a re-fire. This prevents the "permanently blocked" bug where a single
// retrigger post caused the guard to never fire again for the same rescue.
const commentsAfterRescue = rescueIndex >= 0 ? comments.slice(rescueIndex + 1) : [];
const retriggersForRescue = commentsAfterRescue.filter(c => {
  const body = c.body || '';
  return retriggerMarkerRe.test(body) && body.includes(`rescue \`${latestRescue.id}\``);
});

if (retriggersForRescue.length > 0) {
  const lastRetrigger = retriggersForRescue[retriggersForRescue.length - 1];
  const lastRetriggerDbId = lastRetrigger.databaseId;
  const lastRetriggerIndex = comments.findIndex(c => c.databaseId === lastRetriggerDbId);
  // Check if any Copilot agent comment appeared AFTER the last retrigger.
  // If yes, Copilot is actively handling it — don't spam another retrigger.
  const copilotActedAfterRetrigger = lastRetriggerIndex >= 0 &&
    comments.slice(lastRetriggerIndex + 1).some(c =>
      COPILOT_AGENT_LOGINS.has(c.author?.login || '')
    );
  if (copilotActedAfterRetrigger) {
    core.info(`Retrigger already posted for rescue ${latestRescue.id} and Copilot has acted since — not re-triggering.`);
    return;
  }
  // S144 fix: Safety cap — if ≥3 retriggers already posted for this rescue ID,
  // halt to prevent infinite loops. The pre-approval (COPILOT_AGENT_AUTH_ENABLED=true,
  // 💰 Cost Proposal Approved) is in effect; operator review needed if sessions
  // are still not starting after 3 retriggers.
  if (retriggersForRescue.length >= 3) {
    core.warning(`Safety cap: ${retriggersForRescue.length} retriggers already posted for rescue ${latestRescue.id} — halting. Pre-approval is active; operator review needed if sessions are not starting.`);
    return;
  }
  // No Copilot action after the retrigger — session was silently dropped.
  core.info(`Previous retrigger for rescue ${latestRescue.id} had no Copilot action — re-firing (session was dropped).`);
}

// Post re-trigger comment — dynamic format: link + quote, not static boilerplate.
// Rationale: the rescue comment already contains all the relevant details (which
// workflow failed, run ID, steps to resolve). Repeating them statically here
// causes information drift if the rescue comment is later updated (upsert model).
// Instead: extract a compact preview of the rescue body, build the URL from the
// databaseId, and bump Copilot with a direct link rather than a duplication.

// Build a URL for the rescue comment (GitHub format: /pull/{pr}#issuecomment-{id})
const rescueUrl = latestRescue.url ||
  `https://github.com/${context.repo.owner}/${context.repo.repo}/pull/${prNumber}#issuecomment-${latestRescue.commentId}`;

// Build a short preview of the rescue body (skip HTML comment markers, take first
// non-empty lines, limit to ~600 chars so the bump stays concise).
const rescuePreviewLines = (latestRescue.body || '')
  .split('\n')
  .filter(l => !l.trim().startsWith('<!--') && l.trim().length > 0)
  .slice(0, 8)
  .join('\n');
const rescuePreview = rescuePreviewLines.length > 600
  ? rescuePreviewLines.slice(0, 597) + '…'
  : rescuePreviewLines;
const quotedPreview = rescuePreview.split('\n').map(l => `> ${l}`).join('\n');

// Age of rescue comment (createdAt now populated by GraphQL query)
// Display as "Xd Yh ago" for ages >= 24h, "Xh Ym ago" for >= 60 min, "X min ago" for shorter.
function formatAge(ms) {
  const totalMin = Math.round(ms / 60000);
  if (totalMin < 60) return `${totalMin} min ago`;
  const h = Math.floor(totalMin / 60);
  if (h < 24) {
    const m = totalMin % 60;
    return m > 0 ? `${h}h ${m}m ago` : `${h}h ago`;
  }
  const d = Math.floor(h / 24);
  const rem = h % 24;
  return rem > 0 ? `${d}d ${rem}h ago` : `${d}d ago`;
}
const rescueAge = latestRescue.createdAt
  ? formatAge(Date.now() - new Date(latestRescue.createdAt).getTime())
  : 'unknown age';

// Scan table from the preceding scan-failing step (may be empty if scan unavailable)
const scanTable = (process.env.SCAN_TABLE || '').trim();
// S300: include blocking-comments count in retrigger for agent context
const blockingCountS221 = parseInt(process.env.BLOCKING_COUNT || '0', 10);
const blockingNote = blockingCountS221 > 0
  ? `⚠️ **${blockingCountS221} blocking/warning comment(s)** still unaddressed on this PR.`
  : `✅ No blocking comments detected on this PR.`;

const retriggerBody = [
  `<!-- session-done-retrigger -->`,
  `## 🔄 Missed-Trigger Recovery (S221 guard)`,
  ``,
  `**Rescue ID:** \`${latestRescue.id}\` · **Unanswered:** ${rescueAge}`,
  `**Branch:** \`${context.ref_name || 'branch'}\` · **[↗ View rescue comment](${rescueUrl})**`,
  ``,
  `> ✅ **Pre-authorized.** \`COPILOT_AGENT_AUTH_ENABLED=true\` · \`💰 Cost Proposal Approved\` — start immediately.`,
  `> ${blockingNote}`,
  ``,
  `@copilot+claude-haiku-4.5 /plan\n\nThe rescue comment linked above has not been addressed. Please load \`.codex/CODEBASE_AGENCY_POLICY.md\` and fix the failing check(s).\n\n> **💡 Parallel execution:** Use the \`task\` tool to delegate independent subtasks to Custom Agents (e.g. \`ci-auto-healer-agent\`, \`ci-testing-agent\`, \`unified-coverage-agent\`) to work in parallel.`,
  ``,
  ...(scanTable ? [
    `<details><summary>🔍 Current workflow status (HEAD SHA scan)</summary>`,
    ``,
    scanTable,
    ``,
    `</details>`,
    ``,
  ] : []),
  `<details><summary>📋 Rescue comment preview</summary>`,
  ``,
  quotedPreview,
  ``,
  `</details>`,
  ``,
  `---`,
  `*Auto-posted by \`copilot-agent-checkin.yml\` missed-trigger-guard · rescue \`${latestRescue.id}\`*`,
  `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
].join('\n');

if (dryRun) {
  core.info(`[DRY RUN] Would post retrigger for rescue ${latestRescue.id}`);
  core.info(`[DRY RUN] Body preview:\n${retriggerBody.slice(0, 300)}`);
  return;
}

try {
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: prNumber,
    body: retriggerBody,
  });
  core.info(`✅ Missed-trigger guard: posted re-trigger for rescue ${latestRescue.id}`);
} catch(e) {
  core.warning(`Missed-trigger guard: failed to post re-trigger: ${e.message}`);
}

const dryRun = (process.env.DRY_RUN || 'false') === 'true';

// S144 fix: If this push was made by a Copilot agent bot, the session is
// actively running. Skip the incomplete-session guard to avoid competing
// retriggers. Human approval is pre-granted via COPILOT_AGENT_AUTH_ENABLED=true
// and 💰 Cost Proposal Approved — bot-posted @copilot requests start immediately,
// never require an additional approval gate, and must never be cancelled.
const COPILOT_PUSH_ACTORS_INCOMPLETE = new Set([
  'copilot-swe-agent[bot]', 'github-copilot[bot]', 'copilot[bot]',
]);
if (COPILOT_PUSH_ACTORS_INCOMPLETE.has(context.actor)) {
  core.info(`Push actor is Copilot agent (${context.actor}) — session is active. Skipping incomplete-session guard. Pre-approval: COPILOT_AGENT_AUTH_ENABLED=true.`);
  return;
}

const COPILOT_AGENT_LOGINS = new Set([
  'copilot-swe-agent[bot]', 'github-copilot[bot]', 'copilot[bot]', 'copilot',
]);
const ATTESTATION_MARKER = '<!-- session-completion-attestation -->';
const INCOMPLETE_MARKER  = '<!-- incomplete-session-retrigger -->';

// Find open PR
let prNumber = parseInt(process.env.PR_NUMBER || '0', 10);
if (!prNumber) {
  try {
    const branchName = context.ref_name
        || (context.payload.ref || '').replace('refs/heads/', '')
        || '';
    const prs = await github.rest.pulls.list({
      owner: context.repo.owner, repo: context.repo.repo,
      state: 'open', head: `${context.repo.owner}:${branchName}`, per_page: 1,
    });
    prNumber = prs.data[0]?.number || 0;
  } catch(e) { core.info(`Could not find open PR: ${e.message}`); return; }
}
if (!prNumber) return;

// Fetch last 100 comments (newest first via GraphQL)
let comments = [];
try {
  const gql = await github.graphql(
    `query($owner: String!, $repo: String!, $pr: Int!) {
      repository(owner: $owner, name: $repo) {
        pullRequest(number: $pr) {
          comments(last: 100) {
            nodes { databaseId body author { login } }
          }
        }
      }
    }`,
    { owner: context.repo.owner, repo: context.repo.repo, pr: prNumber }
  );
  comments = gql?.repository?.pullRequest?.comments?.nodes || [];
} catch(e) { core.info(`Could not fetch comments: ${e.message}`); return; }

// Find the last Copilot agent comment
const copilotComments = comments.filter(c => COPILOT_AGENT_LOGINS.has(c.author?.login || ''));
if (copilotComments.length === 0) {
  core.info('No Copilot agent comments yet — incomplete-session guard: nothing to do.');
  return;
}
const lastCopilot = copilotComments[copilotComments.length - 1];

// If it already has the attestation, the session completed correctly.
if ((lastCopilot.body || '').includes(ATTESTATION_MARKER)) {
  core.info('Last Copilot comment contains session-completion-attestation — session complete ✅');
  return;
}

// If an INCOMPLETE_SESSION retrigger was already posted recently (after the
// last Copilot comment), don't spam another one.
const lastCopilotIndex = comments.findIndex(c => c.databaseId === lastCopilot.databaseId);
const alreadyRetriggered = comments.slice(lastCopilotIndex + 1).some(c =>
  (c.body || '').includes(INCOMPLETE_MARKER)
);
if (alreadyRetriggered) {
  core.info('Incomplete-session retrigger already posted — waiting for agent response.');
  return;
}

// Post INCOMPLETE_SESSION retrigger
const incompleteBody = [
  INCOMPLETE_MARKER,
  '## ⚠️ Incomplete Session Detected (§ARLOOP enforcement)',
  '',
  '**Trigger:** A push to this branch detected that the previous Copilot agent',
  'session ended without posting a `<!-- session-completion-attestation -->`',
  'comment — meaning the §ARLOOP PR Completion Sweep was not completed.',
  '',
  '> ✅ **Pre-authorized — no human approval needed.** `COPILOT_AGENT_AUTH_ENABLED=true` · `💰 Cost Proposal Approved` are both active on this PR. This bot-posted request is pre-approved and must be queued for immediate action. Session must start without any additional approval gate and must NOT be cancelled.',
  '',
  '**Required action:**',
  '@copilot+claude-haiku-4.5 /plan\n\nPlease resume this session immediately:',
  '',
  '1. Run the full **§ARLOOP PR Completion Sweep** (`.codex/CODEBASE_AGENCY_POLICY.md §ARLOOP`)',
  '2. Address any outstanding CI failures, review threads, and continuation tasks',
  '3. Post the **Session Completion Attestation** comment when the sweep is clean',
  '4. Declare: `✅ This PR is ready to be merged.`',
  '',
  '> **💡 Parallel execution:** Use the `task` tool to delegate independent subtasks to Custom Agents (e.g. `ci-auto-healer-agent`, `unified-coverage-agent`, `ci-testing-agent`) to work in parallel.',
  '---',
  '*Auto-posted by `copilot-agent-checkin.yml` incomplete-session-guard · §ARLOOP Step 5 (S242)*',
  '',
  '---',
  `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
].join('\n');

if (dryRun) {
  core.info(`[DRY RUN] Would post incomplete-session retrigger for PR #${prNumber}`);
  return;
}
try {
  await github.rest.issues.createComment({
    owner: context.repo.owner, repo: context.repo.repo,
    issue_number: prNumber, body: incompleteBody,
  });
  core.info(`✅ Incomplete-session guard: re-trigger posted for PR #${prNumber}`);
} catch(e) {
  core.warning(`Incomplete-session guard: failed to post retrigger: ${e.message}`);
}

// Gate check: proceed if EITHER the WEC checkbox is checked OR COPILOT_AGENT_AUTH_ENABLED is set.
// This ensures the workflow always posts @copilot review when the user explicitly selects
// `- [x] copilot-agent-session-done.yml` in the PR Workflow Execution Checklist,
// even when COPILOT_AGENT_AUTH_ENABLED is unset (e.g. token unavailable environment).

// When triggered by CodeQL completion, skip the @copilot review post entirely.
// The auto-approve-pending-runs and compile-bot-feedback jobs handle CodeQL triggers.
const triggeringWorkflow = context.payload.workflow_run.name;
if (triggeringWorkflow === 'CodeQL') {
  console.log(`Triggered by "${triggeringWorkflow}" — skipping @copilot review post (auto-approve + compile-bot-feedback handle this trigger).`);
  return;
}

const authEnabled = '${{ vars.COPILOT_AGENT_AUTH_ENABLED }}';
const owner = context.repo.owner;
const repo  = context.repo.repo;
const prs   = context.payload.workflow_run.pull_requests;
if (!prs || prs.length === 0) {
  console.log('No associated PRs — skipping.');
  return;
}
const pr = prs[0].number;

// Fetch PR body to check the WEC checkbox for copilot-agent-session-done.yml
let wecChecked = false;
try {
  const { data: prDataForWec } = await github.rest.pulls.get({ owner, repo, pull_number: pr });
  const prBody = prDataForWec.body || '';
  // Match: `- [x] copilot-agent-session-done.yml` (case-insensitive, optional leading spaces)
  wecChecked = /[-*]\s*\[x\]\s*copilot-agent-session-done\.yml/i.test(prBody);
  console.log(`WEC checkbox (copilot-agent-session-done.yml): ${wecChecked}`);
} catch (e) {
  console.log(`Could not fetch PR body for WEC check (non-fatal): ${e.message}`);
}

if (!wecChecked && authEnabled !== 'true' && authEnabled !== '1') {
  console.log('copilot-agent-session-done.yml WEC checkbox not checked AND COPILOT_AGENT_AUTH_ENABLED not set — skipping.');
  return;
}

// Verify the PR is still open
let prData;
try {
  const { data } = await github.rest.pulls.get({ owner, repo, pull_number: pr });
  prData = data;
} catch (e) {
  console.log(`Could not fetch PR ${pr}: ${e.message}`);
  return;
}
if (prData.state !== 'open') {
  console.log(`PR #${pr} is ${prData.state} — skipping.`);
  return;
}

// ── STEP 1: Fetch the last 20 PR comments to check for unaddressed rescue ──
// Uses GraphQL because REST listComments returns pages in ascending order
// (per_page:5 gives OLDEST 5, not newest).
// Includes rateLimit check to circuit-break if remaining < 20.
let allNodes = [];
try {
  const result = await github.graphql(
    `query($owner: String!, $repo: String!, $pr: Int!) {
      rateLimit {
        remaining
        resetAt
      }
      repository(owner: $owner, name: $repo) {
        pullRequest(number: $pr) {
          comments(last: 20) {
            nodes {
              id
              databaseId
              body
              createdAt
              author { login }
            }
          }
        }
      }
    }`,
    { owner, repo, pr }
  );
  // Circuit-break if rate limit is low
  const rlRemaining = result?.rateLimit?.remaining ?? 999;
  const rlResetAt = result?.rateLimit?.resetAt ?? 'unknown';
  if (rlRemaining < 20) {
    core.warning(`GraphQL rate limit low (${rlRemaining} remaining, resets ${rlResetAt}) — skipping comment analysis`);
    return;
  }
  allNodes = result?.repository?.pullRequest?.comments?.nodes || [];
} catch (e) {
  console.log(`Could not fetch PR comments (non-blocking): ${e.message}`);
}

// ── STEP 2: Find unanswered CI rescue comments ──────────────────────────
// A rescue comment is any comment containing "## 🚨 CI Rescue", posted by
// any author EXCEPT the coding agent itself (to avoid treating agent quotes
// of the rescue marker as a new rescue).  This covers:
//   - github-actions[bot] (automated CI via GITHUB_TOKEN)
//   - Any human admin using a PAT (e.g. the repo owner's token shows their login)
// An "answer" is any subsequent @copilot bot reply that contains "Fixed in"
// or "Addressed in" after the rescue comment.
//
// Key insight: when the agent pushes new commits, GitHub may silently drop
// the queued session tied to an older rescue comment.  We detect this case
// by checking whether a rescue comment has NO bot reply AFTER it.
const RESCUE_MARKER = '## 🚨 CI Rescue';
const AGENT_LOGINS = new Set([
  'copilot-swe-agent[bot]',
  'github-copilot[bot]',
  'copilot[bot]',
]);

// Find the most-recent unanswered rescue comment (from any non-agent author)
let pendingRescueComment = null;
for (let i = allNodes.length - 1; i >= 0; i--) {
  const node = allNodes[i];
  const body = node.body || '';
  const authorLogin = node.author?.login || '';

  // Accept rescue comments from ANY author except the coding agent
  // (to avoid treating agent's quote-reply as a new rescue)
  if (body.includes(RESCUE_MARKER) && !AGENT_LOGINS.has(authorLogin)) {
    // Check if any agent comment AFTER this rescue comment addresses it
    const answeredAfter = allNodes.slice(i + 1).some(later => {
      const laterLogin = later.author?.login || '';
      const laterBody  = (later.body || '').toLowerCase();
      return (
        AGENT_LOGINS.has(laterLogin) &&
        (laterBody.includes('fixed in') || laterBody.includes('addressed in'))
      );
    });

    if (!answeredAfter) {
      pendingRescueComment = node;
      break;  // use the most-recent unanswered rescue
    }
  }
}

if (pendingRescueComment) {
  // ── PATH A: Re-trigger the unanswered rescue comment ────────────────
  // Post a targeted @copilot continue comment that references the rescue
  // comment so the new session picks it up immediately.
  const rescueUrl = `https://github.com/${owner}/${repo}/pull/${pr}#issuecomment-${pendingRescueComment.databaseId}`;
  const retriggerBody = [
    `@copilot+claude-haiku-4.5 /plan`,
    ``,
    `<!-- session-done-retrigger -->`,
    `A previous agent session pushed new commits after the CI rescue comment below`,
    `was posted, which caused GitHub to silently drop the queued rescue session.`,
    ``,
    `**Please address the rescue comment immediately:**`,
    `${rescueUrl}`,
    ``,
    `> **💡 Parallel execution:** Use the \`task\` tool to delegate independent subtasks to Custom Agents (e.g. \`ci-auto-healer-agent\`, \`ci-testing-agent\`, \`unified-coverage-agent\`) to work in parallel.`,
    ``,
    `> _Auto-posted by \`copilot-agent-session-done.yml\` (session-done retrigger path)_`,
  '',
  '---',
  `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
  ].join('\n');

  // Guard: don't re-post if we already re-triggered this rescue comment
  const alreadyRetriggered = allNodes.some(c => {
    const body = c.body || '';
    return body.includes('<!-- session-done-retrigger -->') &&
      body.includes(`issuecomment-${pendingRescueComment.databaseId}`);
  });
  if (alreadyRetriggered) {
    console.log(
      `Rescue comment ${pendingRescueComment.databaseId} was already re-triggered — skipping.`
    );
  } else {
    await github.rest.issues.createComment({
      owner, repo, issue_number: pr, body: retriggerBody,
    });
    console.log(
      `Re-triggered rescue comment ${pendingRescueComment.databaseId} on PR #${pr}.`
    );
    return;  // don't also post review
  }
}

// ── PATH B: No pending rescue — post "@copilot review" as usual ────────
// Guard 1: do not post if the most recent comment is already a review trigger
const reviewTriggers = new Set([
  '@copilot review',
  '@copilot+claude-haiku-4.5 /plan',
  '@copilot+claude-haiku-4.5 review',
]);
const recentTriggerCount = allNodes.slice(-10).filter(c => {
  const body = (c.body || '').trim();
  return reviewTriggers.has(body);
}).length;

// Guard 2: review-loop detection — if 3+ of the last 10 comments are
// @copilot review triggers with no meaningful work in between, break the
// loop by posting a diagnostic comment instead of another review trigger.
if (recentTriggerCount >= 3) {
  const loopBreaker = [
    `@copilot+claude-haiku-4.5 /plan`,
    ``,
    `<!-- session-done-loop-break -->`,
    `⚠️ **Review-loop detected**: ${recentTriggerCount} consecutive \`@copilot review\` triggers`,
    `were posted without a resolved rescue or meaningful commit in between.`,
    ``,
    `**Possible causes:**`,
    `1. A CI failure is blocking the session from completing work`,
    `2. The agent is not receiving the review trigger (token issue)`,
    `3. The rescue comment chain is exhausted without a fix`,
    ``,
    `**Requested action:** Please check the latest CI failure and address it directly.`,
    `Check \`docs/accountability/.codex/archive/reports/AGENT_ACCOUNTABILITY_REPORT.md\` for patterns.`,
    ``,
    `> _Auto-posted by \`copilot-agent-session-done.yml\` (loop-break guard)_`,
  '',
  '---',
  `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
  ].join('\n');

  // Only post loop-breaker once per review-loop cycle
  const alreadyBroke = allNodes.slice(-5).some(c => {
    return (c.body || '').includes('<!-- session-done-loop-break -->');
  });
  if (!alreadyBroke) {
    await github.rest.issues.createComment({
      owner, repo, issue_number: pr, body: loopBreaker,
    });
    console.log(`Loop-break comment posted to PR #${pr} (${recentTriggerCount} review triggers detected).`);
  } else {
    console.log(`Loop-break already posted — skipping to avoid double-loop.`);
  }
  return;
}

const alreadyPosted = allNodes.slice(-5).some(c => {
  const body = (c.body || '').trim();
  // Only treat agent-posted review triggers as "already posted".
  // A human writing exactly "@copilot+claude-haiku-4.5 review" would
  // be intentional and should NOT suppress a new trigger.
  return reviewTriggers.has(body) && AGENT_LOGINS.has(c.author?.login || '');
});
if (alreadyPosted) {
  console.log('Most recent comment is already a "@copilot review" — skipping to avoid loop.');
  return;
}

// P2-A (S299): SHA-scoped dedup marker — one session-done trigger per commit.
// When two workflow_run events fire for the same SHA (e.g. Copilot coding agent
// + CodeQL), without this guard both would post "@copilot review" a few seconds
// apart. The marker is stored as an HTML comment inside the trigger body so it
// is not rendered but can be searched across allNodes.
// Note: allNodes is limited to last 20 comments (GraphQL comments(last:20)) so
// the scan is bounded O(20) and does not degrade on large comment histories.
const rawHeadSha = context.payload.workflow_run.head_sha || '';
if (!rawHeadSha) {
  console.log('head_sha is unavailable — skipping SHA-scoped dedup check and proceeding without marker.');
}
const sessionDoneSha = rawHeadSha.slice(0, 12);
const SESSION_DONE_MARKER = rawHeadSha
  ? `<!-- session-done-dedup:${sessionDoneSha} -->`
  : '';
if (SESSION_DONE_MARKER) {
  const alreadyTriggeredForSha = allNodes.some(c =>
    (c.body || '').includes(SESSION_DONE_MARKER)
  );
  if (alreadyTriggeredForSha) {
    console.log(`Session-done trigger already posted for SHA ${sessionDoneSha} — skipping duplicate.`);
    return;
  }
}

const reviewBody = SESSION_DONE_MARKER
  ? `@copilot+claude-haiku-4.5 /plan\n\nreview\n\n${SESSION_DONE_MARKER}`
  : '@copilot+claude-haiku-4.5 /plan';

await github.rest.issues.createComment({
  owner, repo, issue_number: pr,
  body: reviewBody,
});
console.log(`@copilot review posted to PR #${pr}${sessionDoneSha ? ` (SHA ${sessionDoneSha})` : ''}.`);

const owner = context.repo.owner;
const repo  = context.repo.repo;
const prs   = context.payload.workflow_run.pull_requests;
if (!prs || prs.length === 0) return;
const prNumber = prs[0].number;
const MAX_COMMENT_LENGTH = 65536;
// Branch-head SHA used for a SHA-scoped upsert marker.
//
// Use the PR head SHA (not workflow_run.head_sha) because pull_request
// workflow_run events often carry ephemeral merge-preview SHAs.  Those
// merge-preview SHAs can change within one agent session even when the
// PR branch head has not, causing multiple @mbaetiong continuation
// comments instead of one same-session thread.
let headSha = (context.payload.workflow_run.head_sha || '').slice(0, 12);

// Gate: only run when copilot-agent-session-done.yml WEC checkbox is checked
let wecChecked = false;
try {
  const { data: prInfo } = await github.rest.pulls.get({ owner, repo, pull_number: prNumber });
  if (prInfo.state !== 'open') { console.log(`PR #${prNumber} is closed — skipping.`); return; }
  wecChecked = /[-*]\s*\[x\]\s*copilot-agent-session-done\.yml/i.test(prInfo.body || '');
  const prHeadSha = (prInfo.head && prInfo.head.sha) ? prInfo.head.sha : '';
  headSha = (prHeadSha || context.payload.workflow_run.head_sha || '').slice(0, 12);
} catch (e) {
  console.log(`Cannot fetch PR for gate check: ${e.message}`); return;
}
const authEnabled = '${{ vars.COPILOT_AGENT_AUTH_ENABLED }}';
if (!wecChecked && authEnabled !== 'true' && authEnabled !== '1') {
  console.log('WEC checkbox not checked — skipping compile-bot-feedback.'); return;
}

// ── Collect PR Review comments from Copilot AI reviewer ──────────────
const BOT_REVIEW_AUTHORS = new Set([
  'copilot-pull-request-reviewer[bot]',
  'github-copilot[bot]',
  'copilot[bot]',
]);
const BOT_COMMENT_AUTHORS = new Set([
  'github-actions[bot]',
  'copilot-pull-request-reviewer[bot]',
  'github-copilot[bot]',
  'github-code-quality[bot]',
  'github-advanced-security[bot]',
]);
// Quality/security markers commonly emitted by CI bots
const BOT_CONTENT_MARKERS = [
  '<!-- code-quality-report -->',
  '<!-- security-findings -->',
  '<!-- ci-code-quality',     // upserted code-quality section marker
  'semgrep',
  'codeql',
  '🔒 security',
  '⚠️ code quality',
  'code scanning',
  'code quality',
  'security scan',
  'potential problem',
  'github-code-quality',
];

let findings = [];

// 1. PR review comments (Copilot AI review findings)
try {
  const reviews = await github.paginate(github.rest.pulls.listReviews, {
    owner, repo, pull_number: prNumber, per_page: 50,
  });
  for (const review of reviews) {
    const login = review.user?.login || '';
    if (!BOT_REVIEW_AUTHORS.has(login)) continue;
    // Collect the review body if it has content
    if (review.body && review.body.trim().length > 20) {
      findings.push({ source: `Copilot AI Review (${review.submitted_at?.slice(0,10)})`, body: review.body.trim() });
    }
  }

  // Also collect inline review comments (diff comments)
  const reviewComments = await github.paginate(github.rest.pulls.listReviewComments, {
    owner, repo, pull_number: prNumber, per_page: 100, sort: 'created', direction: 'desc',
  });
  const recent = reviewComments.slice(0, 20);
  for (const rc of recent) {
    const login = rc.user?.login || '';
    if (!BOT_REVIEW_AUTHORS.has(login)) continue;
    findings.push({ source: `Copilot Review Comment (${rc.path}:${rc.line || rc.original_line || '?'})`, body: rc.body.trim() });
  }
} catch (e) {
  console.log(`Could not fetch reviews (non-fatal): ${e.message}`);
}

// 2. Issue comments from quality/security bots
try {
  const { data: issueComments } = await github.rest.issues.listComments({
    owner, repo, issue_number: prNumber,
    per_page: 50, sort: 'created', direction: 'desc',
  });
  // direction:'desc' gives newest-first; take the first 30 (most recent)
  const recent = issueComments.slice(0, 30);
  for (const c of recent) {
    const login = c.user?.login || '';
    const body  = c.body || '';
    const isBotAuthor = BOT_COMMENT_AUTHORS.has(login);
    const hasBotMarker = BOT_CONTENT_MARKERS.some(m => body.toLowerCase().includes(m.toLowerCase()));
    // Skip the compile-thread itself to avoid re-including old compilations
    // (matches both legacy `<!-- compiled-bot-feedback -->` and new SHA-scoped variant)
    if (body.includes('<!-- compiled-bot-feedback')) continue;
    if ((isBotAuthor || hasBotMarker) && body.trim().length > 40) {
      // Truncate very long bot comments to first 500 chars
      const excerpt = body.length > 500 ? body.slice(0, 497) + '…' : body;
      findings.push({ source: `Bot Comment (${login}, ${c.created_at?.slice(0,10)})`, body: excerpt });
    }
  }
} catch (e) {
  console.log(`Could not fetch issue comments (non-fatal): ${e.message}`);
}

if (findings.length === 0) {
  console.log(`No bot findings detected for PR #${prNumber} — skipping compile-bot-feedback.`);
  return;
}

// ── Build compiled continuation comment ──────────────────────────────
const findingsList = findings
  .map((f, i) => `**${i + 1}. ${f.source}**\n\n> ${(f.body || '').replace(/\n/g, '\n> ')}`)
  .join('\n\n---\n\n');

const PR_MARKER = `<!-- compiled-bot-feedback:pr-${prNumber} -->`;
const HEAD_MARKER = `<!-- compiled-bot-feedback-head:${headSha} -->`;
const RUN_MARKER = `<!-- compiled-bot-feedback-run:${context.runId} -->`;
const MARKER_PREFIX = `<!-- compiled-bot-feedback`;
const compiledBody = [
  PR_MARKER,
  HEAD_MARKER,
  `@copilot continue with all current priority 1, 2, 3, and 4 tasks as well as addressing all code quality and security concerns listed below.`,
  ``,
  `**📋 Bot-reported findings (${findings.length} item${findings.length > 1 ? 's' : ''}):**`,
  ``,
  findingsList,
  ``,
  `---`,
  `> _Compiled by \`copilot-agent-session-done.yml\` · compile-bot-feedback job_`,
  `> _[🔗 Workflow run](https://github.com/${owner}/${repo}/actions/runs/${context.runId})_`,
].join('\n');

// Upsert guard: scan every PR comment page for either the new PR-scoped
// marker or any legacy compiled-bot-feedback marker.  A busy PR can have
// more than 100 comments, so newest-only GraphQL windows can miss the
// existing thread and create another @copilot request for the same issue.
// PR-scoped upsert keeps all same-session bot findings in one appended
// thread even when follow-up [skip ci] commits change the branch head SHA.
// Rate-limit guard: check remaining before each page; break if < 20.
let existingCommentId = null;
let existingCommentBody = '';
try {
  for (let page = 1; ; page += 1) {
    // Rate-limit guard before each page
    try {
      const rl = await github.rest.rateLimit.get();
      const remaining = rl.data?.resources?.core?.remaining ?? 999;
      if (remaining < 20) {
        core.warning(`REST rate limit low (${remaining} remaining) — stopping upsert scan at page ${page}`);
        break;
      }
    } catch (_) { /* non-fatal — proceed */ }

    const { data: comments } = await github.rest.issues.listComments({
      owner, repo, issue_number: prNumber, per_page: 100, page,
    });
    if (!Array.isArray(comments) || comments.length === 0) break;
    for (const comment of comments) {
      const body = comment.body || '';
      if (body.includes(PR_MARKER) || body.includes(MARKER_PREFIX)) {
        existingCommentId = comment.id;
        existingCommentBody = body;
      }
    }
    if (comments.length < 100) break;
  }
} catch (e) {
  console.log(`Upsert lookup failed (non-fatal): ${e.message}`);
}

if (existingCommentId) {
  if (existingCommentBody.includes(RUN_MARKER)) {
    console.log(`compile-bot-feedback already appended run ${context.runId} for SHA ${headSha} on PR #${prNumber} — skipping duplicate.`);
    return;
  }
  let normalizedExistingBody = existingCommentBody.trimEnd();
  if (!normalizedExistingBody.includes(PR_MARKER)) {
    normalizedExistingBody = `${PR_MARKER}\n${normalizedExistingBody}`;
  }
  if (!normalizedExistingBody.includes(HEAD_MARKER)) {
    normalizedExistingBody = normalizedExistingBody.replace(PR_MARKER, `${PR_MARKER}\n${HEAD_MARKER}`);
  }
  const appendParts = [normalizedExistingBody];
  appendParts.push(
    ``,
    `---`,
    RUN_MARKER,
    `### 🔄 Same-session bot feedback update`,
    ``,
    `Additional request/run: [#${context.runId}](https://github.com/${owner}/${repo}/actions/runs/${context.runId})`,
    ``,
    findingsList,
    ``,
    `> _Appended by \`copilot-agent-session-done.yml\` · compile-bot-feedback job_`,
  );
  const appendBody = appendParts.join('\n');
  await github.rest.issues.updateComment({
    owner, repo, comment_id: existingCommentId, body: appendBody.slice(0, MAX_COMMENT_LENGTH),
  });
  console.log(`Appended ${findings.length} bot finding(s) to existing @copilot continue comment #${existingCommentId} for PR #${prNumber}.`);
  return;
}

await github.rest.issues.createComment({
  owner, repo, issue_number: prNumber, body: `${compiledBody}\n${RUN_MARKER}`,
});
console.log(`Compiled ${findings.length} bot finding(s) into @copilot continue comment on PR #${prNumber}.`);

const owner    = context.repo.owner;
const repo     = context.repo.repo;
const prs      = context.payload.workflow_run.pull_requests;
const prNumber = prs[0].number;
const headSha  = context.payload.workflow_run.head_sha || '';
const headShort = headSha.slice(0, 12);
const now      = new Date().toISOString();

// ── 1. Fetch open code scanning alerts for this SHA ──────────────
let alerts = [];
try {
  // Use REST API — requires security-events:read permission (set on workflow).
  const { data } = await github.rest.codeScanning.listAlertsForRepo({
    owner, repo, ref: headSha, state: 'open', per_page: 20,
  });
  alerts = data || [];
} catch (e) {
  // 403 means Advanced Security is not enabled or token lacks permission.
  // 404 means no alerts endpoint for this repo.  Both are non-fatal.
  console.log(`Code scanning alerts unavailable (${e.status || e.message}) — skipping.`);
  return;
}

if (alerts.length === 0) {
  console.log(`No open code scanning alerts for SHA ${headShort} — nothing to append.`);
  return;
}

// ── 2. Build the quality section ────────────────────────────────
// Dedup marker — one section per SHA (keyed by sha12 + alert count to
// refresh if new alerts appear on the same commit after a re-scan).
const QUALITY_MARKER = `<!-- ci-code-quality:${headShort}:${alerts.length} -->`;

const alertLines = alerts.slice(0, 15).map(a => {
  const rule = a.rule?.id || 'unknown';
  const desc = a.rule?.description || a.most_recent_instance?.message?.text || 'See alert';
  const file = a.most_recent_instance?.location?.path || '';
  const line = a.most_recent_instance?.location?.start_line || '';
  const loc  = file ? ` · \`${file}${line ? ':' + line : ''}\`` : '';
  return `- **${rule}**${loc} — ${desc} ([view](${a.html_url}))`;
});
if (alerts.length > 15) alertLines.push(`- _…and ${alerts.length - 15} more — [view all](https://github.com/${owner}/${repo}/security/code-scanning)_`);

const qualitySection = [
  ``,
  `---`,
  ``,
  QUALITY_MARKER,
  `<details><summary>🔵 <code>github-code-quality</code> — ${alerts.length} alert(s) · ${now}</summary>`,
  ``,
  `**${alerts.length} open alert(s) on commit \`${headShort}\`** — fix before merging:`,
  ``,
  ...alertLines,
  ``,
  `> Run \`python -m ruff check .\` + \`python -m mypy src\` locally, or view the`,
  `> [Security → Code scanning](https://github.com/${owner}/${repo}/security/code-scanning) tab.`,
  ``,
  `</details>`,
].join('\n');

// ── 3. Find existing rescue comment for this SHA ─────────────────
// Rate-limit guard: check remaining before each page.
const rescueMarker = `<!-- ci-rescue-sha:${prNumber}:${headShort} -->`;
let page = 1, existingComment = null;
while (!existingComment) {
  // Rate-limit guard before each page
  try {
    const rl = await github.rest.rateLimit.get();
    const rlRemaining = rl.data?.resources?.core?.remaining ?? 999;
    if (rlRemaining < 20) {
      core.warning(`REST rate limit low (${rlRemaining} remaining) — stopping rescue scan at page ${page}`);
      break;
    }
  } catch (_) { /* non-fatal — proceed */ }

  const { data: batch } = await github.rest.issues.listComments({
    owner, repo, issue_number: prNumber, per_page: 100, page,
  });
  if (!batch || batch.length === 0) break;
  existingComment = batch.find(c => (c.body || '').includes(rescueMarker));
  if (batch.length < 100) break;
  page++;
}

// ── 4. Upsert ────────────────────────────────────────────────────
if (existingComment) {
  // Idempotent: skip if same marker already present (same alert count)
  if (existingComment.body.includes(QUALITY_MARKER)) {
    console.log(`Quality section for SHA ${headShort} already up-to-date — skipping.`);
    return;
  }
  // Remove any previous quality section (different alert count) and re-append.
  // Regex matches the exact marker format: <!-- ci-code-quality:{sha12}:{N} -->
  // {12} is intentional: headShort is always sha.slice(0,12) — exactly 12 hex chars.
  const withoutOldQuality = existingComment.body.replace(
    /\n\n---\n\n<!-- ci-code-quality:[a-f0-9]{12}:\d+ -->[^]*$/,
    ''
  );
  const updated = (withoutOldQuality.trimEnd() + qualitySection).slice(0, 65536);
  await github.rest.issues.updateComment({
    owner, repo, comment_id: existingComment.id, body: updated,
  });
  console.log(`✅ Appended/updated ${alerts.length} code scanning alert(s) in rescue comment for SHA ${headShort}.`);
} else {
  // No rescue comment yet (CI passed but quality issues found) — create standalone
  const standaloneBody = [
    rescueMarker,
    `## 🔵 Code Quality Findings — @copilot Fix Required`,
    ``,
    `**Branch:** \`${context.payload.workflow_run.head_branch}\` | **Commit:** \`${headSha}\``,
    ``,
    `@copilot Code scanning found **${alerts.length} alert(s)** on commit \`${headShort}\` that must be resolved before this PR can merge.`,
    ``,
    `<details><summary>📋 Steps to resolve</summary>`,
    ``,
    `1. Load \`.codex/CODEBASE_AGENCY_POLICY.md\` (§0 — fix ALL issues found)`,
    `2. Review each alert linked below and apply the minimal fix`,
    `3. Push the fix and confirm the Security tab shows 0 open alerts`,
    `4. Update \`docs/accountability/.codex/archive/reports/AGENT_ACCOUNTABILITY_REPORT.md\``,
    ``,
    `</details>`,
    ``,
    `---`,
    ``,
    QUALITY_MARKER,
    `<details><summary>🔵 <code>github-code-quality</code> — ${alerts.length} alert(s) · ${now}</summary>`,
    ``,
    `**${alerts.length} open alert(s) on commit \`${headShort}\`:**`,
    ``,
    ...alertLines,
    ``,
    `</details>`,
  ].join('\n');
  const { data: created } = await github.rest.issues.createComment({
    owner, repo, issue_number: prNumber, body: standaloneBody.slice(0, 65536),
  });
  console.log(`✅ Created quality-findings comment: ${created.html_url}`);
}

with.prompt:
Triage this GitHub issue:

Repository: ${{ github.repository }}
Issue #${{ github.event.issue.number }}: ${{ github.event.issue.title }}
Author: ${{ github.event.issue.user.login }}
Body:
${{ github.event.issue.body }}

Return a JSON triage object following the schema exactly.

with.script:
const triage = JSON.parse(process.env.TRIAGE_JSON);

// Apply labels (ignore any that don't exist yet)
if (triage.labels && triage.labels.length > 0) {
  try {
    await github.rest.issues.addLabels({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: context.issue.number,
      labels: triage.labels,
    });
    core.info(`Applied labels: ${triage.labels.join(', ')}`);
  } catch (e) {
    core.warning(`Label apply failed: ${e.message}`);
  }
}

// Build triage comment
const severityEmoji = {
  critical: '🔴', high: '🟠', medium: '🟡', low: '🟢'
}[triage.severity] || '⚪';

const typeEmoji = {
  bug: '🐛', feature: '✨', documentation: '📚',
  question: '❓', security: '🔒', 'ci-cd': '⚙️',
  'cognitive-brain': '🧠'
}[triage.type] || '📌';

const brainNote = triage.cognitive_brain_relevant
  ? `\n> 🧠 **Cognitive Brain relevant** — affects \`${triage.affected_component}\``
  : '';

const patternNote = triage.suggested_pattern_id
  ? `\n> 📚 **Pattern match:** \`${triage.suggested_pattern_id}\` — see \`.codex/cognitive_brain/${triage.suggested_pattern_id}.md\``
  : '';

const needsInfo = triage.needs_more_info
  ? `\n\n> ⚠️ **More information needed** — please provide additional context (logs, steps to reproduce, etc.)`
  : '';

const bodyLines = [
  `### ${typeEmoji} AI Triage Summary`,
  '',
  '| Field | Value |',
  '|-------|-------|',
  `| **Type** | ${triage.type} |`,
  `| **Severity** | ${severityEmoji} ${triage.severity} |`,
  `| **Component** | \`${triage.affected_component}\` |`,
  `| **Summary** | ${triage.summary} |`,
];
if (brainNote)   bodyLines.push(brainNote);
if (patternNote) bodyLines.push(patternNote);
if (needsInfo)   bodyLines.push(needsInfo);
bodyLines.push('');
bodyLines.push('<sub>🤖 Auto-triaged by [GitHub Copilot Action](https://github.com/marketplace/actions/github-copilot-action) (mvkaran/gh-copilot@5694b7d7a242d1c025e40d0965a0c5c5e68f5fba) — S108 cognitive brain integration</sub>');
bodyLines.push('');
bodyLines.push('---');
bodyLines.push(`_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`);
const body = bodyLines.join('\n');

await github.rest.issues.createComment({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.issue.number,
  body,
});
core.info(`✅ Triage comment posted on issue #${context.issue.number}`);

