with.prompt:
Analyze this pull request for the _codex_ repository:

PR #${{ github.event.pull_request.number }}: ${{ github.event.pull_request.title }}
Author: ${{ github.event.pull_request.user.login }}
Base: ${{ github.base_ref }} ← Head: ${{ github.head_ref }}
Changed files (${{ steps.meta.outputs.brain_touched }} cognitive brain files,
${{ steps.meta.outputs.ci_touched }} CI files):
${{ steps.meta.outputs.changed_files }}

PR Description:
${{ github.event.pull_request.body }}

Provide a structured analysis JSON.

with.script:
const analysis = JSON.parse(process.env.ANALYSIS_JSON);
const brainTouched = parseInt(process.env.BRAIN_TOUCHED || '0') > 0;
const ciTouched    = parseInt(process.env.CI_TOUCHED    || '0') > 0;

const riskEmoji = {
  critical: '🔴', high: '🟠', medium: '🟡', low: '🟢'
}[analysis.risk_level] || '⚪';

const impactEmoji = {
  high: '🧠🔴', medium: '🧠🟡', low: '🧠🟢', none: ''
}[analysis.cognitive_brain_impact] || '';

const patterns = analysis.relevant_patterns?.length
  ? analysis.relevant_patterns.map(p => `\`${p}\``).join(', ')
  : '_none detected_';

const gaps = analysis.test_coverage_gaps?.length
  ? analysis.test_coverage_gaps.map(g => `- ${g}`).join('\n')
  : '- None identified';

const components = analysis.affected_components?.length
  ? analysis.affected_components.map(c => `\`${c}\``).join(', ')
  : '_unknown_';

const brainBadge = brainTouched ? ' 🧠 **Cognitive Brain files modified**' : '';
const ciBadge    = ciTouched    ? ' ⚙️ **CI/CD files modified**'            : '';

// Build @copilot follow-up seeded with analysis
const copilotTask = analysis.suggested_copilot_task || 'Continue implementation following the plan.';

const gapsText = analysis.test_coverage_gaps?.length
  ? analysis.test_coverage_gaps.map(g => `- ${g}`).join('\n            ')
  : '- None identified';

const bodyLines = [
  '## 🧠 Cognitive Brain PR Briefing',
  '',
  `${riskEmoji} **Risk:** ${analysis.risk_level}${impactEmoji ? ' · ' + impactEmoji : ''}${brainBadge}${ciBadge}`,
  '',
  '| Field | Value |',
  '|-------|-------|',
  `| **Affected components** | ${components} |`,
  `| **Relevant patterns** | ${patterns} |`,
  `| **Cognitive brain impact** | ${analysis.cognitive_brain_impact} |`,
  `| **Review focus** | ${analysis.review_focus} |`,
  '',
  '### 🔍 Test Coverage Gaps',
  gapsText,
  '',
  '---',
  '',
  '### 🤖 Suggested @copilot continuation task',
  `> ${copilotTask}`,
  '',
  'To trigger immediately, reply with:',
  '```',
  `@copilot ${copilotTask}`,
  '```',
  '',
  `<sub>Generated by [GitHub Copilot Action](https://github.com/marketplace/actions/github-copilot-action) (mvkaran/gh-copilot@5694b7d7a242d1c025e40d0965a0c5c5e68f5fba) · S108 Cognitive Brain Integration · \`.github/workflows/copilot-pr-session-injector.yml\`</sub>`,
];
const body = bodyLines.join('\n');

// Store for dashboard posting
core.setOutput('body', body);
core.info(`✅ Cognitive brain briefing prepared for PR #${context.payload.pull_request.number}`);

const owner = context.repo.owner;
const repo  = context.repo.repo;
const eventName = context.eventName;

// Bot actors whose comments we acknowledge with 👍
const BOT_ACTORS = new Set([
  'copilot-pull-request-reviewer[bot]',
  'copilot[bot]',
  'github-copilot[bot]',
  'gemini-code-assist[bot]',
  'copilot-swe-agent[bot]',
  'amazon-q[bot]',
]);

// Determine PR number for both event types
const pr = eventName === 'pull_request_review'
  ? context.payload.pull_request.number
  : context.payload.issue.number;

// ── 1. React 👍 to the PR review itself (pull_request_review only) ──
if (eventName === 'pull_request_review') {
  const reviewId = context.payload.review.id;
  try {
    await github.rest.reactions.createForPullRequestReview({
      owner, repo, pull_number: pr, review_id: reviewId, content: '+1',
    });
    console.log(`👍 Reacted to review ${reviewId}`);
  } catch (e) {
    console.log(`Could not react to review ${reviewId}: ${e.message}`);
  }
}

// ── 2. Fetch all PR review comments and react 👍 to bot ones ──────
let page = 1;
const acknowledged = [];
while (true) {
  const { data: comments } = await github.rest.pulls.listReviewComments({
    owner, repo, pull_number: pr, per_page: 100, page,
  });
  if (comments.length === 0) break;
  for (const comment of comments) {
    const actor = comment.user?.login ?? '';
    if (!BOT_ACTORS.has(actor)) continue;
    let alreadyReacted = false;
    try {
      const { data: reactions } = await github.rest.reactions.listForPullRequestReviewComment({
        owner, repo, comment_id: comment.id,
      });
      alreadyReacted = reactions.some(
        r => r.content === '+1' && r.user?.login === 'github-actions[bot]'
      );
    } catch (e) { /* ignore */ }
    if (!alreadyReacted) {
      try {
        await github.rest.reactions.createForPullRequestReviewComment({
          owner, repo, comment_id: comment.id, content: '+1',
        });
        acknowledged.push(comment.id);
        console.log(`👍 Acknowledged review comment ${comment.id} by ${actor}`);
      } catch (e) {
        console.log(`Could not react to comment ${comment.id}: ${e.message}`);
      }
    }
  }
  page++;
}

// ── 3. Also acknowledge regular PR issue comments from bots ───────
page = 1;
while (true) {
  const { data: issueComments } = await github.rest.issues.listComments({
    owner, repo, issue_number: pr, per_page: 100, page,
  });
  if (issueComments.length === 0) break;
  for (const comment of issueComments) {
    const actor = comment.user?.login ?? '';
    if (!BOT_ACTORS.has(actor)) continue;
    let alreadyReacted = false;
    try {
      const { data: reactions } = await github.rest.reactions.listForIssueComment({
        owner, repo, comment_id: comment.id,
      });
      alreadyReacted = reactions.some(
        r => r.content === '+1' && r.user?.login === 'github-actions[bot]'
      );
    } catch (e) { /* ignore */ }
    if (!alreadyReacted) {
      try {
        await github.rest.reactions.createForIssueComment({
          owner, repo, comment_id: comment.id, content: '+1',
        });
        acknowledged.push(comment.id);
        console.log(`👍 Acknowledged issue comment ${comment.id} by ${actor}`);
      } catch (e) {
        console.log(`Could not react to issue comment ${comment.id}: ${e.message}`);
      }
    }
  }
  page++;
}
console.log(`Total acknowledged: ${acknowledged.length} comment(s)`);

const owner       = context.repo.owner;
const repo        = context.repo.repo;
const pr          = context.payload.issue.number;
const commentBody = context.payload.comment.body ?? '';
const reviewer    = context.payload.comment.user.login;

// Extract the "generated N comments" count
const match = commentBody.match(/generated\s+(\d+)\s+comments?/i);
const count = match ? parseInt(match[1], 10) : null;

// Skip if the review explicitly generated 0 comments
if (count !== null && count === 0) {
  console.log('Review generated 0 comments — skipping @copilot trigger.');
  return;
}

// Find the most recent bot PR review to build the review URL.
// The review ID is not in the issue_comment payload, so we fetch it.
const BOT_ACTORS = new Set([
  'copilot-pull-request-reviewer[bot]',
  'copilot[bot]',
  'github-copilot[bot]',
  'gemini-code-assist[bot]',
  'copilot-swe-agent[bot]',
  'amazon-q[bot]',
]);

let reviewId = null;
try {
  const { data: reviews } = await github.rest.pulls.listReviews({
    owner, repo, pull_number: pr,
  });
  // Sort descending by submitted_at to get the most recent bot review
  const botReviews = reviews
    .filter(r => BOT_ACTORS.has(r.user?.login ?? ''))
    .sort((a, b) => new Date(b.submitted_at) - new Date(a.submitted_at));
  if (botReviews.length > 0) {
    reviewId = botReviews[0].id;
    console.log(`Found most recent bot review: ${reviewId} by ${botReviews[0].user.login}`);
  }
} catch (e) {
  console.log(`Could not fetch PR reviews (non-fatal): ${e.message}`);
}

const countStr  = count !== null ? `${count}` : 'some';
const reviewUrl = reviewId
  ? `https://github.com/${owner}/${repo}/pull/${pr}#pullrequestreview-${reviewId}`
  : `https://github.com/${owner}/${repo}/pull/${pr}`;

const body = [
  `@copilot+claude-haiku-4.5 /plan`,
  ``,
  `apply changes based on the comments in [this thread](${reviewUrl})`,
  ``,
  `> 🤖 **Auto-triggered** by \`${reviewer}\` review (${countStr} comment(s) generated).`,
  `> All bot review comments have been acknowledged with 👍.`,
  `> Please address all review comments and resolve any open threads.`,
  `> **💡 Parallel execution:** Use the \`task\` tool to delegate independent fixes to Custom Agents (e.g. \`ci-auto-healer-agent\`, \`test-alignment-fixer\`) to work in parallel.`,
  '',
  '---',
  `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
].join('\n');

await github.rest.issues.createComment({
  owner, repo, issue_number: pr, body,
});
console.log(`@copilot apply posted for review ${reviewId ?? 'unknown'} (${countStr} comments).`);

const INTEGRATION_BRANCHES = ['0D_base_'];
const event = context.eventName;

if (event === 'workflow_dispatch') {
  const src = '${{ inputs.source_branch }}' || '0D_base_';
  core.setOutput('should_chain', 'true');
  core.setOutput('integration_branch', src);
  core.info(`Manual dispatch — targeting integration branch: ${src}`);
  return;
}

// pull_request closed event
const pr = context.payload.pull_request;
if (!pr) {
  core.setOutput('should_chain', 'false');
  core.info('No PR payload — skipping');
  return;
}

const merged = pr.merged === true;
const base   = pr.base.ref;
const head   = pr.head.ref;

// Skip promotion PR (0D_base_ → main) and non-integration targets
const isIntegration = INTEGRATION_BRANCHES.includes(base);
const isPromotion   = INTEGRATION_BRANCHES.includes(head);

if (!merged || !isIntegration || isPromotion) {
  core.setOutput('should_chain', 'false');
  core.info(
    `Skipping chain: merged=${merged}, base=${base}, ` +
    `isIntegration=${isIntegration}, isPromotion=${isPromotion}`
  );
  return;
}

// Only chain if the merged PR explicitly opts in via the
// follow-up checkbox.  Leave it unchecked to suppress auto-chaining.
const body = pr.body || '';
const OPT_IN_MARKER = '- [x] **🔗 Needs follow-up session**';
if (!body.includes(OPT_IN_MARKER)) {
  core.setOutput('should_chain', 'false');
  core.info(
    `PR #${pr.number} merged into ${base} but opt-in marker not checked — ` +
    `skipping auto-chain. To enable, check "🔗 Needs follow-up session" ` +
    `in the PR body before merging.`
  );
  return;
}

core.setOutput('should_chain', 'true');
core.setOutput('integration_branch', base);
core.info(
  `Sub-PR #${pr.number} merged into ${base} with follow-up opt-in — ` +
  `opening next session chain.`
);

const fs = require('fs');

let annotation_level = 'notice';
let title = '✅ Core Validation Passed';
let summary = 'All core validation tests passed.';

if (fs.existsSync('/tmp/core_validation.json')) {
  const results = JSON.parse(fs.readFileSync('/tmp/core_validation.json', 'utf8'));
  if (results.failed > 0) {
    annotation_level = 'failure';
    title = '❌ Core Validation Failed';
  }
  summary = `${results.passed}/${results.total} tests passed`;

  // Add annotations for failed tests
  if (results.failed > 0) {
    results.results
      .filter(r => !r.passed && r.severity === 'error')
      .slice(0, 10)
      .forEach(r => {
        core.setFailed(`Core Validation: ${r.name} — ${r.message}`);
      });
  }
}

console.log(`${title}: ${summary}`);

const fs = require('fs');

let annotation_level = 'notice';
let title = '✅ Integration Tests Passed';
let summary = 'All integration tests passed.';

if (fs.existsSync('/tmp/integration_tests.json')) {
  const results = JSON.parse(fs.readFileSync('/tmp/integration_tests.json', 'utf8'));
  if (results.failed > 0) {
    annotation_level = 'failure';
    title = '❌ Integration Tests Failed';
  }
  summary = `${results.passed}/${results.total} tests passed`;

  // Add annotations for failed tests
  if (results.failed > 0) {
    results.results
      .filter(r => !r.passed && r.severity === 'error')
      .slice(0, 10)
      .forEach(r => {
        core.setFailed(`Integration: ${r.name} — ${r.message}`);
      });
  }
}

console.log(`${title}: ${summary}`);

const fs = require('fs');

let annotation_level = 'notice';
let title = '✅ Security Tests Passed';
let summary = 'All security tests passed.';

if (fs.existsSync('/tmp/security_tests.json')) {
  const results = JSON.parse(fs.readFileSync('/tmp/security_tests.json', 'utf8'));
  if (results.failed > 0) {
    annotation_level = 'failure';
    title = '❌ Security Tests Failed';
  }
  summary = `${results.passed}/${results.total} tests passed`;

  // Add annotations for failed tests
  if (results.failed > 0) {
    results.results
      .filter(r => !r.passed && r.severity === 'error')
      .slice(0, 10)
      .forEach(r => {
        core.setFailed(`Security: ${r.name} — ${r.message}`);
      });
  }
}

console.log(`${title}: ${summary}`);

const fs = require('fs');

let markdown = '## 🤖 Copilot Setup Steps Validation\n\n';
markdown += '### Test Results\n\n';

let totalPassed = 0, totalTests = 0, totalFailed = 0;

// Core validation
if (fs.existsSync('/tmp/core_validation.json')) {
  const results = JSON.parse(fs.readFileSync('/tmp/core_validation.json', 'utf8'));
  const status = results.failed === 0 ? '✅' : '❌';
  markdown += `| Phase | Status | Result |\n`;
  markdown += `|-------|--------|--------|\n`;
  markdown += `| Core Validation | ${status} | ${results.passed}/${results.total} passed |\n`;
  totalPassed += results.passed;
  totalTests += results.total;
  totalFailed += results.failed;
}

// Integration tests
if (fs.existsSync('/tmp/integration_tests.json')) {
  const results = JSON.parse(fs.readFileSync('/tmp/integration_tests.json', 'utf8'));
  const status = results.failed === 0 ? '✅' : '❌';
  markdown += `| Integration | ${status} | ${results.passed}/${results.total} passed |\n`;
  totalPassed += results.passed;
  totalTests += results.total;
  totalFailed += results.failed;
}

// Security tests
if (fs.existsSync('/tmp/security_tests.json')) {
  const results = JSON.parse(fs.readFileSync('/tmp/security_tests.json', 'utf8'));
  const status = results.failed === 0 ? '✅' : '❌';
  markdown += `| Security | ${status} | ${results.passed}/${results.total} passed |\n`;
  totalPassed += results.passed;
  totalTests += results.total;
  totalFailed += results.failed;
}

markdown += `\n### Summary\n`;
markdown += `**Total: ${totalPassed}/${totalTests} tests passed**\n`;

if (totalFailed > 0) {
  markdown += `\n⚠️ **${totalFailed} test(s) failed** — see details above.\n`;
} else {
