const workflowName = (process.env.WORKFLOW_NAME || '').trim();
const effMin       = parseFloat(process.env.EFFECTIVE_MIN || '0').toFixed(0);
const tierEmoji    = tier === 'GREEN' ? '✅' : tier === 'YELLOW' ? '⚠️' : '🔴';

