}

// Reduced from 10×60s (10 min) → 3×30s (90 sec) to keep CI fast.
// If approval is not in place within 90 s, fail immediately with
// actionable instructions rather than blocking the runner for 10 min.
const maxAttempts = 3;   // 3 × 30s = 90 seconds
const pollInterval = 30; // seconds

// Helper: check a body string for the approval marker in any accepted format.
function hasApproval(text) {
  const norm = (text || '').replace(/\*\*/g, '').replace(/__/g, '');
  return (
    norm.includes('- [x] 💰 Cost Proposal Approved') ||
    norm.includes('- [X] 💰 Cost Proposal Approved') ||
    norm.includes('[x] Cost Proposal Approved') ||
    norm.includes('[X] Cost Proposal Approved')
  );
}

for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  const pr = await github.rest.pulls.get({
    owner: context.repo.owner,
    repo: context.repo.repo,
    pull_number: prNumber,
  });

  // Primary: check PR body (normalise bold/italic so "**💰 Cost Proposal Approved**"
  // matches the same as the plain variant).
  if (hasApproval(pr.data.body)) {
    console.log(`✅ Stakeholder approval detected in PR body on attempt ${attempt}`);
    core.setOutput('approved', 'true');
    return;
  }

  // Fallback: also scan PR comments. Automated agents sometimes overwrite
  // the PR body with a session checklist, erasing the approval marker.
  // Accepting a comment avoids re-approval after every body rewrite.
  const { data: comments } = await github.rest.issues.listComments({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: prNumber,
    per_page: 100,
