  if (approvalComment) {
    console.log(`✅ Stakeholder approval detected in PR comment #${approvalComment.id} on attempt ${attempt}`);
    core.setOutput('approved', 'true');
    return;
  }

  if (attempt < maxAttempts) {
    console.log(`⏳ Attempt ${attempt}/${maxAttempts}: waiting ${pollInterval}s for stakeholder to tick the checkbox...`);
    await new Promise(r => setTimeout(r, pollInterval * 1000));
  }
}

