"""Scan documentation for code-path references and verify they exist."""
import json, os, re
from datetime import datetime, timezone
from pathlib import Path

DOC_DIRS = ["docs", ".codex", "README.md"]
CODE_PATH_RE = re.compile(
    r'(?:src/|scripts/|tests/|tools/|apps/|training/)[\w/._-]+\.(?:py|yml|yaml|json|toml|md)',
)
IGNORE_PATTERNS = {".git", "node_modules", "__pycache__", ".nox"}

def iter_docs():
    for d in DOC_DIRS:
        p = Path(d)
        if p.is_file():
            yield p
        elif p.is_dir():
            for f in p.rglob("*"):
                if f.is_file() and f.suffix in (".md", ".yaml", ".yml", ".rst", ".txt"):
                    if not any(part in IGNORE_PATTERNS for part in f.parts):
                        yield f

stale = []
checked = 0
for doc in iter_docs():
    try:
        content = doc.read_text(errors="replace")
    except Exception:
        continue
    for m in CODE_PATH_RE.finditer(content):
        ref = m.group(0)
        checked += 1
        if not Path(ref).exists():
            stale.append({"doc": str(doc), "ref": ref, "line": content[:m.start()].count("\n") + 1})

report = {
    "generated_at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
    "docs_scanned": sum(1 for _ in iter_docs()),
    "code_refs_checked": checked,
    "stale_refs_found": len(stale),
    "stale_refs": stale[:50],  # cap at 50 for readability
    "passed": len(stale) == 0,
}

Path("reports/docs").mkdir(parents=True, exist_ok=True)
Path("reports/docs/alignment_latest.json").write_text(json.dumps(report, indent=2))
print(json.dumps(report, indent=2))

output = os.environ.get("GITHUB_OUTPUT", "/dev/null")
with open(output, "a") as f:
    f.write(f"stale_count={len(stale)}\n")
    f.write(f"checked_count={checked}\n")

if stale:
    print(f"::warning::Found {len(stale)} stale code references in docs")
    for s in stale[:10]:
        print(f"::warning file={s['doc']},line={s['line']}::Stale ref: {s['ref']}")
else:
    print("::notice::✅ All code references in docs are valid")
