} else {
  try {
    const regContent = fs.readFileSync(registryPath, 'utf8');
    // Must have top-level 'agents:' list and 'active_agents:' count
    const hasAgentsList = /^agents:/m.test(regContent);
    const activeMatch = regContent.match(/^active_agents:\s*(\d+)/m);
    if (!hasAgentsList || !activeMatch) {
      core.warning('C1: AGENT_REGISTRY.yaml missing required keys: agents or active_agents');
    } else {
      const declaredActive = parseInt(activeMatch[1], 10);
      // Count actual entries with status: active
      const actualActive = (regContent.match(/^  status: active\s*$/gm) || []).length;
      if (actualActive === 0) {
        core.warning('C1: No agents with status=active found in AGENT_REGISTRY.yaml');
      } else {
        const drift = Math.abs(declaredActive - actualActive);
        if (drift > 10) {
          // Hard-fail: registry header count is significantly stale
          core.warning(
            `C1: active_agents count drift too large — declared: ${declaredActive}, actual: ${actualActive} (drift: ${drift}). ` +
            'Regenerate AGENT_REGISTRY.yaml to fix.'
          );
        } else {
          if (drift > 0) {
            core.warning(
              `C1: minor active_agents drift (declared: ${declaredActive}, actual: ${actualActive}) — ` +
              'acceptable but consider regenerating registry.'
            );
          }
          c1Pass = true;
        }
      }
    }
  } catch (e) {
    core.warning(`C1: AGENT_REGISTRY.yaml validation error: ${e.message}`);
  }
}
conditions.push({
  id: 'C1',
  label: 'AGENT_REGISTRY.yaml present with full coverage',
  pass: c1Pass
});

// C2: CODEX_MANIFEST.json valid and current (<24h)
let manifestOk = false;
if (fs.existsSync('CODEX_MANIFEST.json')) {
  try {
    const m = JSON.parse(fs.readFileSync('CODEX_MANIFEST.json', 'utf8'));
    const ageMs = Date.now() - new Date(m.generated_at).getTime();
    const has24hWindow = ageMs < 24 * 60 * 60 * 1000;
    const hasIntegrity = typeof m.integrity_sha256 === 'string' && m.integrity_sha256.length === 64;
    manifestOk = has24hWindow && hasIntegrity;
  } catch (e) {
    core.warning(`CODEX_MANIFEST.json parse error: ${e.message}`);
  }
}
conditions.push({
  id: 'C2',
  label: 'CODEX_MANIFEST.json valid + current (<24h)',
  pass: manifestOk
});

// C3: Tier-3 (SOFT) policy count <= 2
// C5 shares the same document — load once, fail both explicitly if missing
const gvsPath = '.codex/docs/GROUNDED_VS_SOFT_ENFORCEMENT.md';
const gvsExists = fs.existsSync(gvsPath);
if (!gvsExists) {
  core.warning(`C3/C5: ${gvsPath} not found — cannot verify SOFT or GROUNDED counts`);
}
const gvsDoc = gvsExists ? fs.readFileSync(gvsPath, 'utf8') : null;

// C3: SOFT count — hard-fail when doc is missing (missing doc ≠ zero SOFT policies)
const softCount = gvsDoc ? (gvsDoc.match(/\u274C \*\*SOFT\*\*/g) || []).length : null;
conditions.push({
  id: 'C3',
  label: softCount !== null
    ? `Tier-3 count \u22642 (current: ${softCount})`
    : 'Tier-3 count \u22642 (GVS doc MISSING)',
  pass: softCount !== null && softCount <= 2
});

// C4: agent-handoff-gate.yml deployed (Phase 2 complete)
const handoffGate = fs.existsSync('.github/workflows/agent-handoff-gate.yml');
conditions.push({
  id: 'C4',
  label: 'agent-handoff-gate.yml deployed (Phase 2 complete)',
  pass: handoffGate
});

// C5: GROUNDED Tier-1 gate count >= 8 — hard-fail when doc is missing
const tier1Count = gvsDoc ? (gvsDoc.match(/\u2705 \*\*GROUNDED\*\*/g) || []).length : null;
conditions.push({
  id: 'C5',
  label: tier1Count !== null
    ? `Tier-1 gates \u22658 (current: ${tier1Count})`
    : 'Tier-1 gates \u22658 (GVS doc MISSING)',
  pass: tier1Count !== null && tier1Count >= 8
});

const score = conditions.filter(c => c.pass).length;
const capable = score === 5;

// Write job summary
let summary = `## \U0001F504 E\u2192D Transition Readiness: ${score}/5\n\n`;
summary += `| ID | Condition | Status |\n|----|-----------|---------|\n`;
for (const c of conditions) {
  summary += `| ${c.id} | ${c.label} | ${c.pass ? '\u2705' : '\u274C'} |\n`;
}
summary += `\n**Operating Model:** ${capable ? '\U0001F7E2 D_CAPABLE unlocked' : '\U0001F7E1 E (continue building)'}\n`;
summary += `\n_Tier-1 GROUNDED gate: score < 5 blocks PR._\n`;
await core.summary.addRaw(summary).write();

core.setOutput('score', score.toString());
core.setOutput('capable', capable.toString());
// Export per-condition pass flags so downstream jobs can gate precisely
const c2Condition = conditions.find(c => c.id === 'C2');
core.setOutput('c2_pass', (c2Condition && c2Condition.pass).toString());

// Tier-1 GROUNDED gate: block PR when score < 5/5
if (!capable) {
  core.setFailed(`E\u2192D transition not ready: ${score}/5 conditions met`);
}

