with.script:
const pr = context.payload.pull_request.number;
await github.rest.issues.createComment({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: pr,
  body: [
    '🔧 **C2 Self-Heal Triggered**: `CODEX_MANIFEST.json` was stale (>24h) causing the E→D gate to fail.',
    '',
    'The manifest has been automatically regenerated and pushed. The E→D gate will re-run and should pass C2 on the next push or manual re-run.',
    '',
    '> **Next step:** Re-run the `E→D Transition Readiness Gate` check from the Actions tab, or push a new commit to trigger it automatically.',
  '',
  '---',
  `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
  ].join('\n'),
});

const owner = context.repo.owner;
const repo  = context.repo.repo;
const statusFilter = process.env.STATUS_FILTER;
const maxCancel    = parseInt(process.env.MAX_CANCEL, 10);
const dryRun       = process.env.DRY_RUN === 'true';
const excludeWf    = process.env.EXCLUDE_WF || '';
const thisRunId    = parseInt(process.env.THIS_RUN_ID, 10);

const statuses = statusFilter === 'all-stale'
  ? ['queued', 'waiting']
  : [statusFilter];

let cancelled = 0;
let skipped   = 0;
let errors    = 0;
const summary = {};

core.info(`🚿 Flush mode: ${dryRun ? 'DRY RUN' : 'LIVE'}`);
core.info(`   Status filter: ${statuses.join(', ')}`);
core.info(`   Max cancellations: ${maxCancel}`);
core.info(`   Exclude workflow: ${excludeWf || '(none)'}`);
core.info(`   This run ID (protected): ${thisRunId}`);
core.info('');

for (const status of statuses) {
  let page = 1;
  let hasMore = true;

  while (hasMore && cancelled < maxCancel) {
    const { data: { workflow_runs: runs } } = await github.rest.actions.listWorkflowRunsForRepo({
      owner, repo,
      status,
      per_page: 100,
      page,
    });

    if (runs.length === 0) {
      hasMore = false;
      break;
    }

    for (const run of runs) {
      if (cancelled >= maxCancel) break;

      // Never cancel ourselves
      if (run.id === thisRunId) {
        skipped++;
        continue;
      }

      // Exclude specific workflow if requested
      if (excludeWf && run.name && run.name.includes(excludeWf)) {
        skipped++;
        continue;
      }

      const wfName = run.name || run.workflow_id || '?';
      summary[wfName] = (summary[wfName] || 0) + 1;

      if (dryRun) {
        core.info(`[DRY] Would cancel: ${run.id} — ${wfName} (${status})`);
        cancelled++;
      } else {
        try {
          await github.rest.actions.cancelWorkflowRun({
            owner, repo,
            run_id: run.id,
          });
          cancelled++;
          if (cancelled % 50 === 0) {
            core.info(`   ...cancelled ${cancelled} runs so far`);
          }
        } catch (e) {
          // Run may have already completed or been cancelled
          if (e.status === 409) {
            skipped++;
          } else {
            errors++;
            core.warning(`Failed to cancel run ${run.id}: ${e.message}`);
          }
        }
      }
    }

    page++;
    // GitHub API returns max 100 per page
    if (runs.length < 100) hasMore = false;
  }
}

// Build summary
const fs = require('fs');
const lines = [
  `## 🚿 Flush Results`,
  '',
  `| Metric | Value |`,
  `|--------|-------|`,
  `| Mode | ${dryRun ? '🔍 DRY RUN' : '🚿 LIVE'} |`,
  `| Status filter | ${statuses.join(', ')} |`,
  `| Runs ${dryRun ? 'found' : 'cancelled'} | **${cancelled}** |`,
  `| Runs skipped | ${skipped} |`,
  `| Errors | ${errors} |`,
  '',
  `### By Workflow`,
  '',
  `| Workflow | Count |`,
  `|----------|-------|`,
];

const sorted = Object.entries(summary).sort((a, b) => b[1] - a[1]);
for (const [name, count] of sorted) {
  lines.push(`| ${name} | ${count} |`);
}

if (sorted.length === 0) {
  lines.push(`| _(none found)_ | 0 |`);
}

lines.push('');
lines.push(`_flush-queued-runs.yml | ${new Date().toISOString()}_`);

const body = lines.join('\n');
fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, `\n${body}\n`);
core.info('');
core.info(body);

if (errors > 10) {
  core.setFailed(`Too many errors (${errors}) — check logs`);
}

