const fs = require('fs');
const status = '${{ steps.status.outputs.status }}';
const score = '${{ steps.status.outputs.score }}';
const statusEmoji = { APPROVED: '✅', WARN: '⚠️', BLOCK: '🚫' }[status] || '❓';

let body = `## ${statusEmoji} Phase 12.2 Compliance: **${status}**\n\n`;
body += `**Score:** ${score}\n\n`;

if (fs.existsSync('.codex/PHASE_12_2_COMPLIANCE_REPORT.md')) {
  const report = fs.readFileSync('.codex/PHASE_12_2_COMPLIANCE_REPORT.md', 'utf8');
  // Extract the requirements table section
  const tableMatch = report.match(/## Requirement Status\n\n[\s\S]*?\n\n---/);
  if (tableMatch) {
    body += tableMatch[0].replace('\n\n---', '');
  }
}

body += '\n\n*Generated by [Phase 12.2 Compliance Workflow](../actions)*';

try {
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    body,
  });
} catch (error) {
  core.warning(`Could not post Phase 12.2 compliance comment: ${error.message}`);
}

const issue = context.payload.issue;
const body = (issue.title + ' ' + (issue.body || '')).toLowerCase();
const labels = ['triage-automated'];

// Detect severity
let severity = 'P4';
if (body.includes('production outage') || body.includes('data loss') || body.includes('security breach') || body.includes('critical')) {
  severity = 'P0';
} else if (body.includes('deployment blocked') || body.includes('test failure') || body.includes('ci broken')) {
  severity = 'P1';
} else if (body.includes('significant') || body.includes('high priority')) {
  severity = 'P2';
} else if (body.includes('minor bug') || body.includes('performance')) {
  severity = 'P3';
}
labels.push(`severity-${severity}`);

// Detect category
if (body.includes('bug') || body.includes('error') || body.includes('crash')) {
  labels.push('category-bug');
} else if (body.includes('feature') || body.includes('enhancement')) {
  labels.push('category-feature-request');
} else if (body.includes('doc') || body.includes('documentation')) {
  labels.push('category-documentation');
} else if (body.includes('ci') || body.includes('deploy') || body.includes('workflow')) {
  labels.push('category-infrastructure');
} else if (body.includes('security') || body.includes('vulnerability')) {
  labels.push('category-security');
} else if (body.includes('performance') || body.includes('slow') || body.includes('optimize')) {
  labels.push('category-performance');
} else if (body.includes('test') || body.includes('pytest')) {
  labels.push('category-testing');
}

// Apply unique labels
const uniqueLabels = [...new Set(labels)];
console.log(`Applying labels to issue #${context.issue.number}: ${uniqueLabels.join(', ')}`);

await github.rest.issues.addLabels({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.issue.number,
  labels: uniqueLabels,
});

const fs = require('fs');
const violations = JSON.parse(fs.readFileSync('sla-violations.json', 'utf8'));

if (violations.violations_count > 0) {
  github.rest.issues.createComment({
    issue_number: context.issue.number,
    owner: context.repo.owner,
    repo: context.repo.repo,
    body: `⚠️ Performance regression detected!\n\nFound ${violations.violations_count} SLA violation(s).`
  });
}

