run_commands.command:
python3 - <<'EOF'
import ast, os, json, pathlib, sys

src_root = pathlib.Path("src")
issues = []

for py_file in sorted(src_root.rglob("*.py")):
    try:
        source = py_file.read_text(encoding="utf-8")
        tree = ast.parse(source, filename=str(py_file))
        for node in ast.walk(tree):
            # Detect bare except
            if isinstance(node, ast.ExceptHandler) and node.type is None:
                issues.append({
                    "file": str(py_file),
                    "line": node.lineno,
                    "severity": "warning",
                    "category": "exception_handling",
                    "description": "Bare except clause"
                })
    except SyntaxError as e:
        issues.append({
            "file": str(py_file),
            "line": e.lineno or 0,
            "severity": "error",
            "category": "syntax",
            "description": f"SyntaxError: {e.msg}"
        })

report = {"total_files": len(list(src_root.rglob("*.py"))), "issues": issues}
pathlib.Path("qa-report.json").write_text(json.dumps(report, indent=2))
print(f"Scanned {report['total_files']} files, found {len(issues)} issues")
EOF

