with.script:
const fs = require('fs');
const results = fs.readFileSync('coverage/benchmark_validation_report.txt', 'utf8');
const MARKER = '<!-- benchmark-results-v1 -->';
const body = `${MARKER}\n## 📊 Benchmark Results\n\n\`\`\`\n${results}\n\`\`\`\n\n---\n_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`;

// Retry loop — benchmark results update on every matrix shard
// and every re-run, making concurrent races likely over a long
// PR lifecycle. Retries with linear back-off (2s/4s/6s).
for (let attempt = 0; attempt <= 3; attempt++) {
  try {
    // Paginate through all comments to find the marker, regardless of
    // comment count (PRs with >100 comments would miss older marker comments).
    let existing = null;
    let page = 1;
    while (!existing) {
      const { data: batch } = await github.rest.issues.listComments({
        owner: context.repo.owner, repo: context.repo.repo,
        issue_number: context.issue.number, per_page: 100, page,
      });
      existing = batch.find(c => c.body && c.body.includes(MARKER)) || null;
      if (batch.length < 100) break;
      page++;
    }
    if (existing) {
      await github.rest.issues.updateComment({
        owner: context.repo.owner, repo: context.repo.repo,
        comment_id: existing.id, body,
      });
    } else {
      await github.rest.issues.createComment({
        issue_number: context.issue.number,
        owner: context.repo.owner, repo: context.repo.repo, body,
      });
    }
    break; // success
  } catch (e) {
    if (attempt === 3) throw e;
    await new Promise(r => setTimeout(r, (attempt + 1) * 2000));
  }
}

const MAX_COMMENT_LENGTH = 65536; // GitHub comment body limit
const MARKER = '<!-- secrets-baseline-enforcer -->';
const RUN_MARKER = `<!-- secrets-baseline-enforcer-run:${context.runId} -->`;
const secretsSettingsUrl =
  `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/settings/secrets`;
const section = [
  RUN_MARKER,
  `## 🔐 Secrets Baseline Enforcer — Action Required`,
  ``,
  `**Run:** [${context.runId}](${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})`,
  ``,
  `A new file added in this PR contains a string that \`detect-secrets\` flags.`,
  ``,
  `### Remediation`,
  `\`\`\`bash`,
  `# Option A — false positive in test/fixture file:`,
  `#   Add this comment to the flagged line:`,
  `#   # pragma: allowlist secret`,
  ``,
  `# Option B — update baseline (after adding pragma):`,
  `python scripts/ci/sync_tracked_files.py --fix`,
  `git add .secrets.baseline`,
  `git commit -m "fix(ci): update .secrets.baseline"`,
  `\`\`\``,
  ``,
  `> **Never** commit real secrets.  If a real credential was accidentally`,
  `> committed, rotate it immediately via [GitHub Settings → Secrets](${secretsSettingsUrl}).`,
].join('\n');

let existing = null;
for (let page = 1; ; page += 1) {
  const { data: comments } = await github.rest.issues.listComments({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    per_page: 100,
    page,
  });
  if (!Array.isArray(comments) || comments.length === 0) break;
  existing = comments.find(c =>
    (c.body || '').includes(MARKER) ||
    (c.body || '').includes('## 🔐 Secrets Baseline Enforcer — Action Required')
  );
  if (existing || comments.length < 100) break;
}

if (existing) {
  const existingBody = existing.body || '';
  if (existingBody.includes(RUN_MARKER)) {
    core.info(`Secrets baseline comment already contains run ${context.runId}; skipping duplicate.`);
  } else {
    const body = [
      existingBody.includes(MARKER) ? existingBody.trimEnd() : `${MARKER}\n${existingBody.trimEnd()}`,
      `---`,
      section,
    ].join('\n').slice(0, MAX_COMMENT_LENGTH);
    await github.rest.issues.updateComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      comment_id: existing.id,
      body,
    });
  }
} else {
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    body: `${MARKER}\n${section}`,
  });
}

const MARKER = '<!-- secrets-fp-healer -->';
const body = `${MARKER}
## ✅ Secrets False-Positive Healer Applied (RP-007)

The **Secrets False-Positive Healer** detected and automatically annotated
documentation example lines flagged by \`detect-secrets\`.

### What was fixed:
- Added \`<!-- pragma: allowlist secret -->\` to markdown table rows containing example credential strings
- Added \`# pragma: allowlist secret\` to Python code block lines with example secrets

These are **documentation examples**, not real credentials.
The \`🔐 Enforce Secrets Baseline\` workflow should now pass.

> **If you see a real secret was annotated:** Rotate it immediately and remove from codebase.
> The healer only annotates lines in \`.md\` files inside table cells or labeled code blocks.

_Auto-generated by [Secrets False-Positive Healer](${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`;

const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner, repo: context.repo.repo,
  issue_number: context.issue.number, per_page: 100,
});
const existing = comments.find(c => c.body && c.body.includes(MARKER));
if (existing) {
  await github.rest.issues.updateComment({
    owner: context.repo.owner, repo: context.repo.repo,
    comment_id: existing.id, body,
  });
} else {
  await github.rest.issues.createComment({
    issue_number: context.issue.number,
    owner: context.repo.owner, repo: context.repo.repo,
    body,
  });
}

let alerts;
try {
  const response = await github.rest.dependabot.listAlertsForRepo({
    owner: context.repo.owner,
    repo: context.repo.repo,
    state: 'open',
    sort: 'created',
    direction: 'desc',
    per_page: 100
  });
  alerts = response.data;
} catch (err) {
  core.warning(`Unable to fetch Dependabot alerts: ${err.message} (status ${err.status})`);
  core.setOutput('alert-count', 0);
  core.setOutput('critical-count', 0);
  core.setOutput('high-count', 0);
  core.setOutput('moderate-count', 0);
  core.setOutput('low-count', 0);
  core.setOutput('alerts', '[]');
  core.setOutput('has-alerts', false);
  return { count: 0, alerts: [] };
}

// Filter alerts created in last 24 hours
const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
const newAlerts = alerts.filter(alert =>
  new Date(alert.created_at) > oneDayAgo
);

// Group by severity
const groupedAlerts = {
  critical: [],
  high: [],
  moderate: [],
  low: []
};

newAlerts.forEach(alert => {
  const severity = alert.security_advisory.severity.toLowerCase();
  if (groupedAlerts[severity]) {
    groupedAlerts[severity].push(alert);
  }
});

core.setOutput('alert-count', newAlerts.length);
core.setOutput('critical-count', groupedAlerts.critical.length);
core.setOutput('high-count', groupedAlerts.high.length);
core.setOutput('moderate-count', groupedAlerts.moderate.length);
core.setOutput('low-count', groupedAlerts.low.length);
core.setOutput('alerts', JSON.stringify(newAlerts));
core.setOutput('has-alerts', newAlerts.length > 0);

return {
  count: newAlerts.length,
  alerts: newAlerts
};

const alerts = JSON.parse(process.env.ALERTS_JSON || '[]');

let summary = '## 🚨 New Security Alerts Detected\n\n';
summary += `**Total New Alerts:** ${alerts.length}\n\n`;

// Summary table
summary += '| Severity | Count |\n';
summary += '|----------|-------|\n';
summary += `| Critical | ${{ steps.get-alerts.outputs.critical-count }} |\n`;
summary += `| High | ${{ steps.get-alerts.outputs.high-count }} |\n`;
summary += `| Moderate | ${{ steps.get-alerts.outputs.moderate-count }} |\n`;
summary += `| Low | ${{ steps.get-alerts.outputs.low-count }} |\n\n`;

// Group and display alerts
const severityGroups = {
  'critical': { emoji: '🔴', alerts: [] },
  'high': { emoji: '🟠', alerts: [] },
  'moderate': { emoji: '🟡', alerts: [] },
  'low': { emoji: '🔵', alerts: [] }
};

alerts.forEach(alert => {
  const severity = alert.security_advisory.severity.toLowerCase();
  if (severityGroups[severity]) {
    severityGroups[severity].alerts.push(alert);
  }
});

// Add alert details by severity
for (const [severity, group] of Object.entries(severityGroups)) {
  if (group.alerts.length > 0) {
    summary += `### ${group.emoji} ${severity.charAt(0).toUpperCase() + severity.slice(1)} Severity\n\n`;

    group.alerts.forEach(alert => {
      const advisory = alert.security_advisory;
      summary += `#### Alert #${alert.number}: ${advisory.summary}\n`;
      summary += `- **Package:** ${alert.dependency.package.name} (${alert.dependency.package.ecosystem})\n`;
      if (advisory.cve_id) {
        summary += `- **CVE:** [${advisory.cve_id}](${advisory.references[0]?.url || advisory.html_url})\n`;
      }
      if (advisory.cvss?.score) {
        summary += `- **CVSS Score:** ${advisory.cvss.score}\n`;
      }
      summary += `- **URL:** ${alert.html_url}\n`;
      summary += `- **Created:** ${new Date(alert.created_at).toISOString().split('T')[0]}\n\n`;
    });
  }
}

summary += '\n---\n\n';
summary += '### 📋 Next Steps\n\n';
summary += '1. **Critical/High Alerts:** Address within 48 hours\n';
summary += '2. **Moderate Alerts:** Address within 1 week\n';
summary += '3. **Low Alerts:** Address within 1 month\n\n';
summary += '**Review Process:**\n';
summary += '- Check if current version includes the fix\n';
summary += '- If patched: Dismiss alert and document in `reports/security_audit.md`\n';
summary += '- If not patched: Create PR to update dependency\n\n';
summary += `**View All Alerts:** https://github.com/${context.repo.owner}/${context.repo.repo}/security/dependabot\n`;

core.setOutput('summary', summary);
return summary;

const summary = process.env.ISSUE_SUMMARY || '';
const criticalCount = parseInt(process.env.CRITICAL_COUNT || '0', 10);
const highCount = parseInt(process.env.HIGH_COUNT || '0', 10);

// Only create issue for critical/high severity alerts
if (criticalCount > 0 || highCount > 0) {
  const title = `🚨 Security Alert: ${criticalCount} Critical, ${highCount} High Severity Vulnerabilities Detected`;

  // Check if similar issue already exists
  const { data: existingIssues } = await github.rest.issues.listForRepo({
    owner: context.repo.owner,
    repo: context.repo.repo,
    state: 'open',
    labels: 'security,dependabot',
    per_page: 10
  });

  // Don't create duplicate if issue already exists from today
  const today = new Date().toISOString().split('T')[0];
  const existingToday = existingIssues.find(issue =>
    issue.created_at.startsWith(today)
  );

  if (!existingToday) {
    await github.rest.issues.create({
      owner: context.repo.owner,
      repo: context.repo.repo,
      title: title,
      body: summary,
      labels: ['security', 'dependabot', 'high-priority']
    });

    core.info('Created security alert issue');
  } else {
    core.info('Security issue already exists for today, skipping creation');
  }
}

const owner = context.repo.owner;
const repo = context.repo.repo;
const pendingCount = parseInt('${{ steps.pending.outputs.count }}', 10) || 0;

core.info(`Dispatching auto-approve-workflows.yml for batch approval (${pendingCount} pending runs)`);

try {
  await github.rest.actions.createWorkflowDispatch({
    owner,
    repo,
    workflow_id: 'auto-approve-workflows.yml',
    ref: 'main',
    inputs: {
      approval_source: 'self-approve-pending-runs',
