      approval_reason: `Batch approval sweep: ${pendingCount} pending runs detected`,
      approval_ttl_hours: '0.5',
      dry_run: 'false'
    }
  });
  core.info(`✅ auto-approve-workflows.yml dispatched for batch of ${pendingCount} runs`);
} catch (err) {
  core.warning(`Hub dispatch failed: ${err.message}`);
}

const fs = require('fs');
const path = require('path');

// Read context file
const contextFile = fs.readdirSync('context').find(f => f.endsWith('.json'));
if (!contextFile) {
  console.log('No context file found');
  return;
}

const context = JSON.parse(fs.readFileSync(path.join('context', contextFile), 'utf8'));
const marker = '<!-- session-context-capture -->';

const body = [
  marker,
  '## 📋 Session Context Captured',
  '',
  `**Time:** ${context.timestamp}`,
  `**PR:** #${context.pr_number}`,
  `**SHA:** ${context.sha}`,
  '',
  '### 📝 PR State',
  `- **Title:** ${context.sections.pr_state.title || 'N/A'}`,
  `- **State:** ${context.sections.pr_state.state} (Draft: ${context.sections.pr_state.draft})`,
  `- **Branch:** \`${context.sections.pr_state.head_branch}\` → \`${context.sections.pr_state.base_branch}\``,
  '',
  '### ✅ Outstanding Tasks',
  context.sections.outstanding_tasks.map(t => `- [ ] ${t.description}`).join('\n') || '- No outstanding tasks',
  '',
  '### 🚨 Blocking Issues',
  context.sections.blocking_issues.map(i => `- **${i.type}** (${i.status}): ${i.name || i.author}`).join('\n') || '- No blocking issues',
  '',
  '---',
  `_Context captured for session handoff. Run at: [GitHub Actions](${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }})_`,
].join('\n');

const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: ${{ inputs.pr_number }},
  per_page: 100,
});

const existing = comments.find(c => c.body && c.body.includes(marker));
if (existing) {
  await github.rest.issues.updateComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    comment_id: existing.id,
    body,
  });
} else {
  await github.rest.issues.createComment({
    issue_number: ${{ inputs.pr_number }},
    owner: context.repo.owner,
    repo: context.repo.repo,
    body,
  });
}

const EXPLORATION_MARKER    = 'SESSION_TYPE_EXPLORATION';
const REMINDER_MARKER       = 'INCREMENTAL_SUMMARY_REMINDER';
const SILENCE_THRESHOLD_MS  = 10 * 60 * 1000;   // 10 minutes
const REMINDER_COOLDOWN_MS  = 10 * 60 * 1000;   // Don't re-remind within 10 min

// Bot/agent actor logins — suppress reminder if last comment is from a human
const AGENT_LOGINS = new Set([
  'copilot-swe-agent[bot]',
  'github-copilot[bot]',
  'github-actions[bot]',
]);

const now = new Date();

// Fetch recently-updated open PRs (limit: 30 — enough for active repos)
const { data: prs } = await github.rest.pulls.list({
  owner:     context.repo.owner,
  repo:      context.repo.repo,
  state:     'open',
  sort:      'updated',
  direction: 'desc',
  per_page:  30,
});

let remindedCount = 0;
for (const pr of prs) {
  try {
    // Fetch all comments on this PR
    const { data: comments } = await github.rest.issues.listComments({
      owner:      context.repo.owner,
      repo:       context.repo.repo,
      issue_number: pr.number,
      per_page:   100,
    });

    // Skip if no SESSION_TYPE_EXPLORATION marker active
    if (!comments.some(c => c.body.includes(EXPLORATION_MARKER))) {
      continue;
    }

    // Skip if SESSION_TIMEBOX_EXPIRED is present (session already ended)
    if (comments.some(c => c.body.includes('SESSION_TIMEBOX_EXPIRED'))) {
      continue;
    }

    // Find the most recent agent comment
    const agentComments = comments.filter(c => AGENT_LOGINS.has(c.user.login));
    if (agentComments.length === 0) {
      continue;  // No agent activity yet — no need to remind
    }
    agentComments.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
    const lastAgentComment = agentComments[0];
    const lastAgentTime    = new Date(lastAgentComment.created_at);
    const silenceDuration  = now - lastAgentTime;

    if (silenceDuration < SILENCE_THRESHOLD_MS) {
      continue;  // Agent was active within the last 10 min — no reminder needed
    }

    // Dedup: check if a reminder was already posted within the cooldown window
    const recentReminder = comments.find(
      c => c.body.includes(REMINDER_MARKER) &&
           (now - new Date(c.created_at)) < REMINDER_COOLDOWN_MS
    );
    if (recentReminder) {
      continue;  // Reminder already posted within cooldown — skip
    }

    // Compute elapsed time in human-readable format
    const elapsedMin = Math.round(silenceDuration / 60000);

    const body = [
      `## 📝 ${REMINDER_MARKER} — Incremental Progress Summary Due`,
      '',
      `> **Auto-posted by Session Reminder Workflow (WF-003)**`,
      `> An exploration session is active on this PR. The last agent update was **${elapsedMin} minutes ago**.`,
      '',
      '**Policy:** During an exploration session, the agent must post an incremental progress',
      'summary approximately every **~10 minutes**. This is **Tier-2 grounded enforcement**',
      '(present-tense injection — not background memory).',
      '',
      '### Required Action',
      '',
      '- [ ] Post a PR comment with `## 📊 Incremental Progress Summary` containing:',
      '  - Topics covered so far',
      '  - Key findings / decisions made',
      '  - What remains to be done',
      '  - Explicit question for the human: "Proceed to X, or go deeper on Y?"',
      '',
      `_Last agent activity: ${lastAgentComment.created_at} (${elapsedMin}min ago)_`,
      `_Exploration marker detected: ${EXPLORATION_MARKER}_`,
      '',
      '_WF-003 | session-incremental-summary-reminder | [GROUNDED_VS_SOFT_ENFORCEMENT.md](.codex/docs/GROUNDED_VS_SOFT_ENFORCEMENT.md)_',
      '',
      '---',
      `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
    ].join('\n');

    await github.rest.issues.createComment({
      owner:        context.repo.owner,
      repo:         context.repo.repo,
      issue_number: pr.number,
      body,
    });

    core.info(`✅ Posted incremental summary reminder on PR #${pr.number} (${elapsedMin}min silence)`);
    remindedCount++;

  } catch (prError) {
    core.warning(`PR #${pr.number}: ${prError.message}`);
  }
}

if (remindedCount === 0) {
  core.info('No active exploration sessions require reminders at this time.');
} else {
  core.info(`Posted ${remindedCount} incremental summary reminder(s).`);
}

const fs = require('fs');
const report = JSON.parse(fs.readFileSync('.codex/session_recovery_monitoring_report.json', 'utf8'));

if (report.recent_failures.length > 0) {
  github.rest.issues.createComment({
    issue_number: process.env.GITHUB_PR_NUMBER,
    owner: context.repo.owner,
    repo: context.repo.repo,
    body: `## 🔄 Session Recovery Monitoring Report\n\n` +
          `Generated: ${report.timestamp}\n` +
          `Recovery System Status: ${report.recovery_system_status}\n\n` +
          `### Recent Events\n` +
          report.recent_failures.map(f =>
            `- **${f.type}**: ${f.timestamp} (Session: ${f.session_id})`
          ).join('\n')
  });
}

run_commands.command:
RECOVERY_FILE=".codex/session_recovery_$(date +%Y%m%d_%H%M%S).md"

cat > "$RECOVERY_FILE" << 'EOF'
# Session Recovery — ${{ steps.extract_context.outputs.updated_at }}

**Failed Workflow Run:** ${{ steps.extract_context.outputs.workflow_run_id }}
**Workflow Name:** ${{ steps.extract_context.outputs.workflow_name }}
