with.script:
const commentBody = context.payload.comment.body || '';
const prNumber    = context.issue.number;

const TIMEBOX_START_MARKER   = 'SESSION_TIMEBOX_START';
const TIMEBOX_EXPIRED_MARKER = 'SESSION_TIMEBOX_EXPIRED';
const EXPLORATION_MARKER     = 'SESSION_TYPE_EXPLORATION';

// Skip watchdog's own marker comments to prevent re-trigger loops
if (
  commentBody.includes(TIMEBOX_START_MARKER) ||
  commentBody.includes(TIMEBOX_EXPIRED_MARKER) ||
  commentBody.includes(EXPLORATION_MARKER)
) {
  console.log('Skipping watchdog-generated comment to prevent loop.');
  return;
}

// Get all existing PR comments for dedup and expiry checks
const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: prNumber,
});

// ── A. Detect and record timebox directive ────────────────────────────
const timeboxMatch = commentBody.match(/~\s*(\d+)\s*(?:minutes?|mins?)/i);
if (timeboxMatch) {
  const minutes    = parseInt(timeboxMatch[1], 10);
  const now        = new Date();
  const expiresAt  = new Date(now.getTime() + minutes * 60000);
  const expiresISO = expiresAt.toISOString();

  // Dedup: skip if there is already an active (non-expired) timebox on this PR
  const activeStart = comments.find(c => {
    if (!c.body.includes(TIMEBOX_START_MARKER)) return false;
    const em = c.body.match(/\*\*Expires:\*\*\s*(\S+)/);
    if (!em) return false;
    const exp = new Date(em[1]);
    return !isNaN(exp.getTime()) && new Date() < exp;
  });

  if (!activeStart) {
    await github.rest.issues.createComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: prNumber,
      body: [
        `## ⏱ ${TIMEBOX_START_MARKER}`,
        '',
        `**Timebox detected:** \`~${minutes} minutes\``,
        `**Started:** ${now.toISOString()}`,
        `**Expires:** ${expiresISO}`,
        '',
        `> 🤖 **Agent:** Your session window is **${minutes} minutes**.`,
        '> Post a `## 🧠 Session Summary` comment before this expires.',
        '> To extend: post a new `~N minutes` comment.',
        '',
        '_session-watchdog | WF-002 | [SessionContinuityPolicy.md](.github/docs/SessionContinuityPolicy.md)_',
    '',
    '---',
    `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
      ].join('\n'),
    });
    core.notice(`Timebox set: ${minutes}min, expires ${expiresISO}`, {
      title: '⏱ Session Timebox Recorded',
    });
  }
}

// ── B. Detect and record exploration session ──────────────────────────
const isExploration    = /exploration\s+session|capability\s+discussion/i.test(commentBody);
const doNotAutoProceed = /do\s+not\s+auto.?proceed/i.test(commentBody);

if (isExploration && !comments.find(c => c.body.includes(EXPLORATION_MARKER))) {
  const dnap = doNotAutoProceed
    ? '\n> 🛑 **"Do NOT auto-proceed"** directive active. Agent MUST wait for explicit human "continue" after each item.\n'
    : '';

  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: prNumber,
    body: [
      `## 🔍 ${EXPLORATION_MARKER}`,
      '',
      '**Exploration session detected.** [Session Continuity Policy](.github/docs/SessionContinuityPolicy.md) is now **active:**',
      dnap,
      '| Rule | Enforcement |',
      '|------|-------------|',
      '| Never self-close | Post findings + ask "proceed or deeper?" after each agenda item |',
      '| Incremental summaries | Post a PR comment every ~10 minutes of work |',
      `| Wait for human | ${doNotAutoProceed ? '🛑 **REQUIRED** — "Do NOT auto-proceed" detected' : 'Treat silence as pause, not signal to close'} |`,
      '| Session close | **REQUIRED:** Post `## 🧠 Session Summary` with topics + follow-up `@copilot` prompt |',
      '',
      '_session-watchdog | WF-002 | [SessionContinuityPolicy.md](.github/docs/SessionContinuityPolicy.md)_',
  '',
  '---',
  `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
    ].join('\n'),
  });
  core.notice('Exploration session recorded — Session Continuity Policy active', {
    title: '🔍 Exploration Session Active',
  });
}

// ── C. Check if any active timebox has expired ────────────────────────
const timeboxStarts = comments.filter(c => c.body.includes(TIMEBOX_START_MARKER));
for (const ts of timeboxStarts) {
  const m = ts.body.match(/\*\*Expires:\*\*\s*(\S+)/);
  if (!m) continue;

  const expiresAt = new Date(m[1]);
  if (isNaN(expiresAt.getTime())) continue;

  if (new Date() > expiresAt) {
    // Already posted expiry notice for this exact timebox?
    const alreadyExpired = comments.find(c =>
      c.body.includes(TIMEBOX_EXPIRED_MARKER) && c.body.includes(m[1])
    );

    if (!alreadyExpired) {
      await github.rest.issues.createComment({
        owner: context.repo.owner,
        repo: context.repo.repo,
        issue_number: prNumber,
        body: [
          `## 🔔 ${TIMEBOX_EXPIRED_MARKER}`,
          '',
          '**Your session timebox has expired.**',
          '',
          `**Expired:** ${expiresAt.toISOString()}`,
          `**Current time:** ${new Date().toISOString()}`,
          '',
          'If you are the active agent on this session:',
          '- [ ] Post `## 🧠 Session Summary` with topics covered and key findings',
          '- [ ] Include a suggested follow-up `@copilot` prompt for the next session',
          '- [ ] Do NOT start new work — timebox is expired',
          '',
          'To extend: post a new `~N minutes` comment.',
          '',
          '_session-watchdog | WF-002 | [SessionContinuityPolicy.md](.github/docs/SessionContinuityPolicy.md)_',
    '',
    '---',
    `_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`,
        ].join('\n'),
      });
      core.warning(`Timebox expired: ${m[1]}`, {
        title: '🔔 Session Timebox Expired',
      });
    }
  }
}

const fs = require('fs');
const reportFile = fs.readdirSync('.').find(f => f.startsWith('telemetry_report_'));
const telemetry = JSON.parse(fs.readFileSync(reportFile, 'utf8'));

let body = '## 🚨 CI Health Alert\n\n';
body += `Telemetry analysis for the past ${{ github.event.inputs.days || '7' }} days has detected concerning patterns.\n\n`;

body += '### Summary\n\n';
body += `- **Total Runs:** ${telemetry.summary.total_runs}\n`;
body += `- **Failed Runs:** ${telemetry.summary.failed_runs}\n`;
body += `- **Failure Rate:** ${(telemetry.summary.failure_rate * 100).toFixed(1)}%\n\n`;

body += '### Pattern Distribution\n\n';
body += '| Pattern | Count |\n|---------|-------|\n';
for (const [pattern, count] of Object.entries(telemetry.pattern_distribution)) {
  body += `| ${pattern} | ${count} |\n`;
}

body += '\n### Recommended Actions\n\n';

const criticalFailure = '${{ steps.critical.outputs.critical_failure_rate }}' === 'true';
const highAutoFix = '${{ steps.critical.outputs.high_auto_fix_failures }}' === 'true';
const highCoverage = '${{ steps.critical.outputs.high_coverage_timeouts }}' === 'true';

if (criticalFailure) {
  body += '- ⚠️ **Critical:** Failure rate exceeds 20% - immediate investigation required\n';
}
if (highAutoFix) {
  body += '- 🔧 Review auto-fix workflow configuration and permissions\n';
}
if (highCoverage) {
  body += '- ⏱️ Investigate coverage timeout issues - consider increasing timeout or splitting tests\n';
}

body += '\n**Report:** Telemetry collected on ' + new Date().toISOString().split('T')[0];
body += `\n\n---\n_[🔗 Workflow run](https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId})_`;

// Check if similar issue exists
const { data: issues } = await github.rest.issues.listForRepo({
  owner: context.repo.owner,
  repo: context.repo.repo,
  state: 'open',
  labels: 'ci-health'
});

if (issues.length === 0) {
  // Create new issue
  await github.rest.issues.create({
    owner: context.repo.owner,
    repo: context.repo.repo,
    title: `CI Health Alert: High Failure Rate Detected`,
    body: body,
    labels: ['ci-health', 'automation', 'priority-high']
  });
} else {
  // Update existing issue
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: issues[0].number,
    body: body
  });
}

const prNumber = parseInt('${{ github.event.inputs.pr_number }}', 10);
const runUrl   = `${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}`;
const requireBoth = process.env.REQUIRE_BOTH === 'true';

const mFn = process.env.MASTER_FUNCTIONAL === 'true';
const bFn = process.env.BACKUP_FUNCTIONAL === 'true';
const bothFn = mFn && bFn;

const mRow = `| \`CODEX_MASTER_KEY\` | Read: HTTP ${process.env.MASTER_READ} | Write: HTTP ${process.env.MASTER_WRITE} | ${mFn ? '✅ FUNCTIONAL' : '❌ NON-FUNCTIONAL'} |`;
const bRow = `| \`CODEX_BACKUP_KEY\`  | Read: HTTP ${process.env.BACKUP_READ}  | Write: HTTP ${process.env.BACKUP_WRITE}  | ${bFn ? '✅ FUNCTIONAL' : '❌ NON-FUNCTIONAL'} |`;

let overall;
if (bothFn) {
  overall = '🟢 BOTH KEYS OPERATIONAL (100% coverage)';
} else if (mFn && !bFn) {
  overall = '🟡 PRIMARY KEY ONLY — backup key non-functional (50% coverage)';
} else if (!mFn && bFn) {
  overall = '🟡 BACKUP KEY ONLY — primary key non-functional (50% coverage)';
} else {
  overall = '🔴 BOTH KEYS FAILED — REQUIRES IMMEDIATE ACTION';
}

const body = [
  `## 🔑 Token Probe Result — S117`,
  '',
  `| Secret | Read Probe | Write Probe | Status |`,
  `|--------|-----------|------------|--------|`,
  mRow,
  bRow,
  '',
  `**Overall:** ${overall}`,
  `**Require both keys:** ${requireBoth ? 'YES' : 'NO'}`,
  '',
  `**Tested at:** ${new Date().toISOString()}`,
  `**Run:** [${process.env.GITHUB_RUN_NUMBER || '?'}](${runUrl})`,
  '',
  bothFn
    ? '✅ Both `CODEX_MASTER_KEY` and `CODEX_BACKUP_KEY` validated. `@copilot continue` automation is **fully operational**.'
    : mFn
      ? '⚠️ `CODEX_MASTER_KEY` works but `CODEX_BACKUP_KEY` is non-functional. Sessions can activate but failover is unavailable.'
      : '⛔ Fix `CODEX_MASTER_KEY` before activating any agent session. See repo Settings → Secrets.',
  '',
  '_token-probe.yml | S117 | admin_setup_verification.yml §3a/§3b_',
].join('\n');

await github.rest.issues.createComment({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: prNumber,
  body,
});

// Also write to job summary
const fs = require('fs');
fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, `\n${body}\n`);

// Fail conditions:
// 1. Always fail if master key is broken
// 2. Fail if require_both_keys=true and backup key is also broken
if (!mFn) {
  core.setFailed('CODEX_MASTER_KEY is non-functional. Agent sessions cannot activate.');
} else if (requireBoth && !bFn) {
  core.setFailed('CODEX_BACKUP_KEY is non-functional and require_both_keys=true. Both keys must pass.');
}

const owner = context.repo.owner;
const repo = context.repo.repo;
const prNumber = parseInt('${{ steps.ctx.outputs.pr_num }}', 10);
const prSha = '${{ steps.ctx.outputs.pr_sha }}';
const reviewer = '${{ steps.ctx.outputs.reviewer }}';

core.info(`Dispatching auto-approve-workflows.yml for PR #${prNumber} @ ${prSha.slice(0,8)}`);

try {
  await github.rest.actions.createWorkflowDispatch({
    owner,
    repo,
    workflow_id: 'auto-approve-workflows.yml',
    ref: 'main',
    inputs: {
      approval_source: 'trigger-on-approval',
      approval_intent: 'dispatch_validation_suite',
      target_pr: prNumber.toString(),
      approval_reason: `Code review approval from @${reviewer}`,
      approval_ttl_hours: '2',
      dry_run: 'false'
    }
  });
  core.info('✅ auto-approve-workflows.yml dispatched');
} catch (err) {
  core.warning(`Hub dispatch failed: ${err.message}`);
}

const owner = context.repo.owner;
const repo  = context.repo.repo;
const ref   = '${{ steps.ctx.outputs.pr_sha }}';
core.info(`Dispatching validate.yml @ ${ref}`);
try {
  await github.rest.actions.createWorkflowDispatch({
    owner, repo,
    workflow_id: 'validate.yml',
    ref,
    inputs: { mode: 'fast' },
  });
  core.info('✅ validate.yml dispatched');
} catch (err) {
  core.warning(`validate.yml dispatch failed: ${err.message}`);
}

const owner = context.repo.owner;
const repo  = context.repo.repo;
const ref   = '${{ steps.ctx.outputs.pr_sha }}';
core.info(`Dispatching pre-merge-validation.yml @ ${ref}`);
try {
  await github.rest.actions.createWorkflowDispatch({
    owner, repo,
    workflow_id: 'pre-merge-validation.yml',
    ref,
    inputs: {},
  });
  core.info('✅ pre-merge-validation.yml dispatched');
} catch (err) {
  core.warning(`pre-merge-validation.yml dispatch failed: ${err.message}`);
}

const owner = context.repo.owner;
const repo  = context.repo.repo;
const ref   = '${{ steps.ctx.outputs.pr_sha }}';
core.info(`Dispatching codeql-alert-fetcher.yml @ ${ref}`);
try {
  await github.rest.actions.createWorkflowDispatch({
    owner, repo,
    workflow_id: 'codeql-alert-fetcher.yml',
    ref,
    inputs: {
      state: 'open',
      tool_name: 'CodeQL',
      max_pages: '10',
      page_sleep_ms: '1000',
      top_n: '30',
    },
  });
  core.info('✅ codeql-alert-fetcher.yml dispatched');
} catch (err) {
  // Non-fatal — CODEX_MASTER_KEY may be absent in fork contexts
  core.warning(`codeql-alert-fetcher.yml dispatch failed (needs CODEX_MASTER_KEY/security_events): ${err.message}`);
}

const owner    = context.repo.owner;
const repo     = context.repo.repo;
const prNumber = parseInt('${{ steps.ctx.outputs.pr_num }}', 10);
const reviewer = '${{ steps.ctx.outputs.reviewer }}';
const sha      = '${{ steps.ctx.outputs.pr_sha }}';

const body = [
  `<!-- trigger-on-approval-agent-resume -->`,
  `## ⚡ Approval Dispatch — Copilot Resume`,
  ``,
  `PR #${prNumber} approved by **@${reviewer}** at \`${sha.slice(0,8)}\`.`,
  ``,
  `**Dispatched workflows:**`,
  `- \`validate.yml\` (fast mode) ✅`,
  `- \`pre-merge-validation.yml\` ✅`,
  `- \`codeql-alert-fetcher.yml\` (requires CODEX_MASTER_KEY) ✅`,
  `- All \`action_required\` runs auto-approved via \`approve_pending_runs.py\` ✅`,
  ``,
  `@copilot continue`,
].join('\n');

try {
  await github.rest.issues.createComment({ owner, repo, issue_number: prNumber, body });
  core.info('✅ @copilot continue comment posted');
} catch (err) {
  core.warning(`Could not post @copilot continue comment: ${err.message}`);
}

const fs = require('fs');
let report = {};
try {
  report = JSON.parse(fs.readFileSync('.codex/compliance/report.json', 'utf8'));
} catch (e) {
  console.error('Failed to parse report:', e);
  return;
}

const status = report.status || 'UNKNOWN';
const score = report.overall_score || 0;
const rationale = report.decision_rationale || '';

let comment = `## 📋 Governance Compliance Check\n\n`;
comment += `**Status:** ${status === 'APPROVE' ? '✅' : status === 'WARN' ? '⚠️' : '❌'} ${status}\n`;
comment += `**Score:** ${score.toFixed(1)}/100\n`;
comment += `**Rationale:** ${rationale}\n\n`;

comment += `### Requirement Status\n`;
for (const validator of report.validators || []) {
  const icon = validator.status === 'pass' ? '✅' : validator.status === 'warn' ? '⚠️' : '❌';
  comment += `- ${icon} **${validator.requirement_id}**: ${validator.reason}\n`;
  if (validator.remediation && validator.remediation.length > 0) {
    comment += `  - *Remediation:* ${validator.remediation.slice(0, 2).join(', ')}\n`;
  }
}

if (report.next_steps && report.next_steps.length > 0) {
  comment += `\n### Recommended Next Steps\n`;
  report.next_steps.forEach((step, i) => {
    comment += `${i + 1}. ${step}\n`;
  });
}

// Try to find existing comment
try {
  const { data: comments } = await github.rest.issues.listComments({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
  });

  const existingComment = comments.find(c =>
    c.user.type === 'Bot' && c.body.includes('Governance Compliance Check')
  );

  if (existingComment) {
    await github.rest.issues.updateComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      comment_id: existingComment.id,
      body: comment,
    });
  } else {
    await github.rest.issues.createComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      issue_number: context.issue.number,
      body: comment,
    });
  }
} catch (error) {
  core.warning(`Could not post governance comment: ${error.message}`);
}

const fs = require('fs');
let report = {};
try {
  report = JSON.parse(fs.readFileSync('.codex/compliance/report.json', 'utf8'));
} catch (e) {
  console.log('Warning: Could not parse compliance report');
  return;
}

const status = report.status || 'UNKNOWN';

// Set check run status
const state = status === 'BLOCK' ? 'failure' : status === 'WARN' ? 'neutral' : 'success';

await github.rest.checks.create({
  owner: context.repo.owner,
  repo: context.repo.repo,
  name: 'Governance Compliance',
  head_sha: context.payload.pull_request.head.sha,
  status: 'completed',
  conclusion: state === 'failure' ? 'failure' : state === 'neutral' ? 'neutral' : 'success',
  output: {
    title: `Governance Compliance: ${status}`,
    summary: `Score: ${report.overall_score}/100\n\n${report.decision_rationale}`,
  },
});

// Block merge if BLOCK status
if (status === 'BLOCK') {
  core.setFailed('Governance compliance check failed - merge blocked');
}

const violations = ${{ steps.safety-check.outputs.violation-count }};
const comment = `## API Null-Handling Validation Report

Status: Warnings Found (Non-blocking for PRs)

Found ${violations} potential unsafe API null-handling pattern(s).

Use auto-fix: python scripts/ci/validate_api_null_handling.py --fix`;

github.rest.issues.createComment({
  issue_number: context.issue.number,
  owner: context.repo.owner,
  repo: context.repo.repo,
  body: comment
});

