with open('python_blocks.json') as f:
    blocks = json.load(f)

common_modules = {
    'os': ['os.'],
    'sys': ['sys.'],
    'json': ['json.'],
    'requests': ['requests.', 'get(', 'post('],
    'pathlib': ['Path('],
    'typing': ['Dict', 'List', 'Optional'],
}

issues = []
for file_path, idx, code in blocks:
    lines = code.split('\n')

    # Skip if first line is import
    if any('import' in line for line in lines[:3]):
        continue

    for module, patterns in common_modules.items():
        has_import = any(f'import {module}' in line for line in lines)
        if not has_import:
            for pattern in patterns:
                if pattern in code:
                    issues.append(f"{file_path}:{idx}: Missing 'import {module}'")
                    break

if issues:
    print("⚠️  Missing imports found:")
    for issue in issues[:10]:
        print(f"  {issue}")
    print(f"\nTotal: {len(issues)} blocks with missing imports")
else:
    print("✅ No obvious missing imports detected")
EOF

